def get_ticket_fields(tenant_id, field_scope=None, include_disabled=None, refresh=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_iso(ts):
        if ts is None:
            return None
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, tenant_id_val, status, latency_ms, meta=None):
        fn = _ensure_request_log()
        logs = _load(fn)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "tenant_id": tenant_id_val,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _tenant_usable(t):
        if not isinstance(t, dict):
            return False
        if t.get("status") != "active":
            return False
        at = t.get("auth_type")
        if at == "api_key":
            return t.get("api_key_ciphertext") is not None
        if at == "oauth":
            return t.get("oauth_access_token_ciphertext") is not None
        return False

    def _enforce_rate_limit(tenant_row):
        # safety limit: per-tenant max calls/minute across all endpoints
        limit = tenant_row.get("rate_limit_per_minute")
        if not isinstance(limit, int) or limit < 1:
            return None  # misconfigured; don't block here
        fn = _ensure_request_log()
        logs = _load(fn)
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_iso(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= window_start:
                c += 1
        if c >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=limit)
        return None

    t0 = time.time()
    endpoint = "get_ticket_fields"

    # Validate inputs
    if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
        _log(endpoint, tenant_id if isinstance(tenant_id, str) else None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "tenant_id is invalid; expected pattern ^fdten_[0-9A-Z]{10,}$.")
    if field_scope is None:
        field_scope = "ticket"
    if field_scope != "ticket":
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "field_scope must be 'ticket'.")
    if include_disabled is None:
        include_disabled = False
    if not isinstance(include_disabled, bool):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_disabled must be boolean.")
    if refresh is None:
        refresh = False
    if not isinstance(refresh, bool):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "refresh must be boolean.")

    tenants = _load("tenants.json")
    tenant = next((x for x in tenants if x.get("id") == tenant_id), None)
    if tenant is None or tenant.get("status") == "deleted":
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Tenant not found.")
    if not _tenant_usable(tenant):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Tenant has no usable Freshdesk credentials.")
    rl = _enforce_rate_limit(tenant)
    if rl:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": rl["error"]["code"]})
        return rl

    # Offline server: "refresh" cannot call upstream; we treat it as a no-op but keep behavior observable.
    # We still advance last_synced_at on cached field definitions to represent a refresh attempt.
    custom_fields = _load("custom_fields.json")
    if refresh:
        changed = False
        now_iso = _now_iso()
        for cf in custom_fields:
            if cf.get("tenant_id") == tenant_id and cf.get("field_scope") == "ticket" and cf.get("status") != "deleted":
                cf["last_synced_at"] = now_iso
                cf["updated_at"] = now_iso
                changed = True
        if changed:
            _save("custom_fields.json", custom_fields)

    rows = []
    for cf in custom_fields:
        if cf.get("tenant_id") != tenant_id:
            continue
        if cf.get("field_scope") != "ticket":
            continue
        st = cf.get("status")
        if include_disabled:
            # include active/disabled, and include deleted too as requested
            rows.append(cf)
        else:
            if st == "deleted":
                continue
            if st == "disabled":
                continue
            rows.append(cf)

    body = {
        "tenant_id": tenant_id,
        "field_scope": "ticket",
        "fields": rows,
        "count": len(rows),
        "refreshed": bool(refresh),
    }
    _log(endpoint, tenant_id, "ok", (time.time() - t0) * 1000, {"count": len(rows), "refresh": bool(refresh)})
    return body

def get_tickets(tenant_id, status=None, agent_freshdesk_id=None, group_freshdesk_id=None, requester_contact_freshdesk_id=None, company_freshdesk_id=None, updated_since=None, sort_by=None, sort_order=None, page=None, page_size=None, refresh=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_iso(ts):
        if ts is None:
            return None
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, tenant_id_val, status_val, latency_ms, meta=None):
        fn = _ensure_request_log()
        logs = _load(fn)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "tenant_id": tenant_id_val,
            "status": status_val,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _tenant_usable(t):
        if not isinstance(t, dict):
            return False
        if t.get("status") != "active":
            return False
        at = t.get("auth_type")
        if at == "api_key":
            return t.get("api_key_ciphertext") is not None
        if at == "oauth":
            return t.get("oauth_access_token_ciphertext") is not None
        return False

    def _enforce_rate_limit(tenant_row):
        limit = tenant_row.get("rate_limit_per_minute")
        if not isinstance(limit, int) or limit < 1:
            return None
        fn = _ensure_request_log()
        logs = _load(fn)
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_iso(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= window_start:
                c += 1
        if c >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=limit)
        return None

    t0 = time.time()
    endpoint = "get_tickets"

    # Validate inputs
    if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
        _log(endpoint, tenant_id if isinstance(tenant_id, str) else None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "tenant_id is invalid; expected pattern ^fdten_[0-9A-Z]{10,}$.")

    if status is not None:
        if not isinstance(status, str) or status not in ("open", "pending", "resolved", "closed", "deleted"):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "status must be one of open, pending, resolved, closed, deleted.")

    for nm, v in (
        ("agent_freshdesk_id", agent_freshdesk_id),
        ("group_freshdesk_id", group_freshdesk_id),
        ("requester_contact_freshdesk_id", requester_contact_freshdesk_id),
        ("company_freshdesk_id", company_freshdesk_id),
    ):
        if v is not None and (not isinstance(v, int) or v <= 0):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{nm} must be a positive integer.")

    updated_since_dt = None
    if updated_since is not None:
        if not isinstance(updated_since, str):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "updated_since must be an ISO 8601 date-time string.")
        updated_since_dt = _parse_iso(updated_since)
        if updated_since_dt is None:
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "updated_since is not a valid ISO 8601 timestamp.")

    if sort_by is None:
        sort_by = "updated_at"
    if sort_by not in ("created_at", "updated_at"):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort_by must be 'created_at' or 'updated_at'.")

    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'.")

    tenants = _load("tenants.json")
    tenant = next((x for x in tenants if x.get("id") == tenant_id), None)
    if tenant is None or tenant.get("status") == "deleted":
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Tenant not found.")
    if not _tenant_usable(tenant):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Tenant has no usable Freshdesk credentials.")

    if page is None:
        page = 1
    if not isinstance(page, int) or page < 1:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")

    if page_size is None:
        dps = tenant.get("default_page_size")
        page_size = dps if isinstance(dps, int) else 25
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")

    if refresh is None:
        refresh = False
    if not isinstance(refresh, bool):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "refresh must be boolean.")

    rl = _enforce_rate_limit(tenant)
    if rl:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": rl["error"]["code"]})
        return rl

    tickets = _load("tickets.json")

    # Offline refresh: no upstream. For observability, we can mark last_synced_at for matching rows as a "refresh attempt".
    if refresh:
        now_iso = _now_iso()
        changed = False
        for tk in tickets:
            if tk.get("tenant_id") != tenant_id:
                continue
            if tk.get("status") == "deleted" and status != "deleted":
                continue
            tk["last_synced_at"] = now_iso
            tk["updated_at"] = now_iso
            changed = True
        if changed:
            _save("tickets.json", tickets)

    def _dt_for(row, key):
        dt = _parse_iso(row.get(key))
        return dt

    # Filter
    out = []
    for tk in tickets:
        if tk.get("tenant_id") != tenant_id:
            continue

        # default exclude deleted unless explicitly asked
        if status is None:
            if tk.get("status") == "deleted":
                continue
        else:
            if tk.get("status") != status:
                continue

        if agent_freshdesk_id is not None and tk.get("agent_freshdesk_id") != agent_freshdesk_id:
            continue
        if group_freshdesk_id is not None and tk.get("group_freshdesk_id") != group_freshdesk_id:
            continue
        if requester_contact_freshdesk_id is not None and tk.get("requester_contact_freshdesk_id") != requester_contact_freshdesk_id:
            continue
        if company_freshdesk_id is not None and tk.get("company_freshdesk_id") != company_freshdesk_id:
            continue

        if updated_since_dt is not None:
            u = _dt_for(tk, "updated_at") or _dt_for(tk, "last_synced_at") or _dt_for(tk, "created_at")
            if u is None or u < updated_since_dt:
                continue

        out.append(tk)

    # Sort
    reverse = (sort_order == "desc")

    def _sort_key(row):
        dt = _dt_for(row, sort_by)
        if dt is None:
            dt = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        # stable-ish tiebreaker
        return (dt, str(row.get("id", "")))

    out.sort(key=_sort_key, reverse=reverse)

    total = len(out)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = out[start:end]
    has_more = end < total
    next_page = (page + 1) if has_more else None

    body = {
        "tenant_id": tenant_id,
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "next_page": next_page,
        "tickets": page_rows,
        "refreshed": bool(refresh),
        "sort_by": sort_by,
        "sort_order": sort_order,
    }
    _log(endpoint, tenant_id, "ok", (time.time() - t0) * 1000, {"returned": len(page_rows), "total": total, "refresh": bool(refresh)})
    return body

def create_ticket(tenant_id, subject, description, email=None, requester_id=None, priority=None, status=None, source=None, type=None, group_id=None, responder_id=None, company_id=None, tags=None, custom_fields=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, tenant_id_val, status_val, latency_ms, meta=None):
        fn = _ensure_request_log()
        logs = _load(fn)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "tenant_id": tenant_id_val,
            "status": status_val,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _tenant_usable(t):
        if not isinstance(t, dict):
            return False
        if t.get("status") != "active":
            return False
        at = t.get("auth_type")
        if at == "api_key":
            return t.get("api_key_ciphertext") is not None
        if at == "oauth":
            return t.get("oauth_access_token_ciphertext") is not None
        return False

    def _parse_iso(ts):
        if ts is None:
            return None
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _enforce_rate_limit(tenant_row):
        limit = tenant_row.get("rate_limit_per_minute")
        if not isinstance(limit, int) or limit < 1:
            return None
        fn = _ensure_request_log()
        logs = _load(fn)
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_iso(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= window_start:
                c += 1
        if c >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=limit)
        return None

    t0 = time.time()
    endpoint = "create_ticket"

    # Validate inputs
    if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
        _log(endpoint, tenant_id if isinstance(tenant_id, str) else None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "tenant_id is invalid; expected pattern ^fdten_[0-9A-Z]{10,}$.")
    if not isinstance(subject, str) or not subject.strip():
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "subject is required and must be a non-empty string.")
    if not isinstance(description, str) or not description.strip():
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "description is required and must be a non-empty string.")

    if requester_id is not None and (not isinstance(requester_id, int) or requester_id <= 0):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "requester_id must be a positive integer.")
    if email is not None:
        if not isinstance(email, str) or not email.strip():
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "email must be a non-empty string when provided.")
    if requester_id is None and (email is None or not isinstance(email, str) or not email.strip()):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Either requester_id or email must be provided.")

    if priority is not None and (not isinstance(priority, int) or priority < 1 or priority > 4):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "priority must be an integer between 1 and 4.")
    if source is not None and (not isinstance(source, int) or source < 1):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "source must be an integer >= 1.")
    if status is not None and (not isinstance(status, int) or status < 1):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "status must be a positive integer (Freshdesk numeric status).")

    for nm, v in (("group_id", group_id), ("responder_id", responder_id), ("company_id", company_id)):
        if v is not None and (not isinstance(v, int) or v <= 0):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{nm} must be a positive integer.")
    if type is not None and not isinstance(type, str):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "type must be a string when provided.")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(x, str) for x in tags):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "tags must be an array of strings.")
    if custom_fields is not None and not isinstance(custom_fields, dict):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "custom_fields must be an object (key/value pairs).")

    tenants = _load("tenants.json")
    tenant = next((x for x in tenants if x.get("id") == tenant_id), None)
    if tenant is None or tenant.get("status") == "deleted":
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Tenant not found.")
    if not _tenant_usable(tenant):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Tenant has no usable Freshdesk credentials.")
    rl = _enforce_rate_limit(tenant)
    if rl:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": rl["error"]["code"]})
        return rl

    # Build request payload (what we'd send upstream)
    payload = {
        "subject": subject,
        "description": description,
    }
    if requester_id is not None:
        payload["requester_id"] = requester_id
    elif email is not None:
        payload["email"] = email
    if priority is not None:
        payload["priority"] = priority
    if status is not None:
        payload["status"] = status
    if source is not None:
        payload["source"] = source
    if type is not None:
        payload["type"] = type
    if group_id is not None:
        payload["group_id"] = group_id
    if responder_id is not None:
        payload["responder_id"] = responder_id
    if company_id is not None:
        payload["company_id"] = company_id
    if tags is not None:
        payload["tags"] = tags
    if custom_fields is not None:
        payload["custom_fields"] = custom_fields

    # Create local row first (staged create)
    tickets = _load("tickets.json")
    now_iso = _now_iso()
    local_id = "fdtic_" + uuid.uuid4().hex
    staged = {
        "id": local_id,
        "tenant_id": tenant_id,
        "status": "open",
        "freshdesk_id": None,
        "subject": subject,
        "description_text": description,
        "priority": priority,
        "source": source,
        "type": type,
        "group_freshdesk_id": group_id,
        "agent_freshdesk_id": responder_id,
        "requester_contact_freshdesk_id": requester_id,
        "company_freshdesk_id": company_id,
        "tags": tags,
        "custom_fields": custom_fields,
        "raw": {"staged_request": payload},
        "search_text": " ".join([x for x in [subject, description] if isinstance(x, str)]),
        "last_synced_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    tickets.append(staged)
    _save("tickets.json", tickets)

    # Offline "upstream success": assign a synthetic Freshdesk id and mark as synced.
    # This keeps the cache consistent for later update_* calls (freshdesk_id must be non-null).
    used_ids = set()
    for tk in tickets:
        if tk.get("tenant_id") == tenant_id and isinstance(tk.get("freshdesk_id"), int):
            used_ids.add(tk["freshdesk_id"])
    # deterministic-ish new id based on current time
    candidate = int(time.time() * 1000) % 1000000000
    if candidate <= 0:
        candidate = 1
    while candidate in used_ids:
        candidate += 1

    upstream_ticket = {
        "id": candidate,
        "subject": subject,
        "description": description,
        "priority": priority,
        "status": status,
        "source": source,
        "type": type,
        "group_id": group_id,
        "responder_id": responder_id,
        "company_id": company_id,
        "tags": tags,
        "custom_fields": custom_fields,
        "requester_id": requester_id,
        "email": email if requester_id is None else None,
    }

    # Update the just-created local row with upstream values
    tickets = _load("tickets.json")
    found = False
    for tk in tickets:
        if tk.get("id") == local_id and tk.get("tenant_id") == tenant_id:
            tk["freshdesk_id"] = candidate
            tk["raw"] = upstream_ticket
            tk["last_synced_at"] = _now_iso()
            tk["updated_at"] = tk["last_synced_at"]
            # map numeric Freshdesk status to cache lifecycle best-effort
            # If caller didn't specify status, keep "open". If specified, keep open/pending/resolved/closed mapping.
            num = status
            if isinstance(num, int):
                if num in (2,):
                    tk["status"] = "open"
                elif num in (3,):
                    tk["status"] = "pending"
                elif num in (4,):
                    tk["status"] = "resolved"
                elif num in (5,):
                    tk["status"] = "closed"
            found = True
            break
    if not found:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Staged ticket row not found after creation (internal state).")
    _save("tickets.json", tickets)

    result = next((x for x in tickets if x.get("id") == local_id and x.get("tenant_id") == tenant_id), None)
    _log(endpoint, tenant_id, "ok", (time.time() - t0) * 1000, {"local_id": local_id, "freshdesk_id": candidate})
    return {"tenant_id": tenant_id, "ticket": result}

def update_ticket(tenant_id, ticket_id, subject=None, description=None, priority=None, status=None, source=None, type=None, group_id=None, responder_id=None, company_id=None, tags=None, custom_fields=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_iso(ts):
        if ts is None:
            return None
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, tenant_id_val, status_val, latency_ms, meta=None):
        fn = _ensure_request_log()
        logs = _load(fn)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "tenant_id": tenant_id_val,
            "status": status_val,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _tenant_usable(t):
        if not isinstance(t, dict):
            return False
        if t.get("status") != "active":
            return False
        at = t.get("auth_type")
        if at == "api_key":
            return t.get("api_key_ciphertext") is not None
        if at == "oauth":
            return t.get("oauth_access_token_ciphertext") is not None
        return False

    def _enforce_rate_limit(tenant_row):
        limit = tenant_row.get("rate_limit_per_minute")
        if not isinstance(limit, int) or limit < 1:
            return None
        fn = _ensure_request_log()
        logs = _load(fn)
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_iso(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= window_start:
                c += 1
        if c >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=limit)
        return None

    t0 = time.time()
    endpoint = "update_ticket"

    # Validate inputs
    if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
        _log(endpoint, tenant_id if isinstance(tenant_id, str) else None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "tenant_id is invalid; expected pattern ^fdten_[0-9A-Z]{10,}$.")
    if not isinstance(ticket_id, int) or ticket_id <= 0:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "ticket_id must be a positive integer (Freshdesk ticket id).")

    any_field = any(v is not None for v in [subject, description, priority, status, source, type, group_id, responder_id, company_id, tags, custom_fields])
    if not any_field:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "No updatable fields provided.")

    if subject is not None and (not isinstance(subject, str) or not subject.strip()):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "subject must be a non-empty string when provided.")
    if description is not None and (not isinstance(description, str) or not description.strip()):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "description must be a non-empty string when provided.")
    if priority is not None and (not isinstance(priority, int) or priority < 1 or priority > 4):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "priority must be an integer between 1 and 4.")
    if source is not None and (not isinstance(source, int) or source < 1):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "source must be an integer >= 1.")
    if status is not None and (not isinstance(status, int) or status < 1):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "status must be a positive integer (Freshdesk numeric status).")
    if type is not None and not isinstance(type, str):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "type must be a string when provided.")
    for nm, v in (("group_id", group_id), ("responder_id", responder_id), ("company_id", company_id)):
        if v is not None and (not isinstance(v, int) or v <= 0):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{nm} must be a positive integer.")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(x, str) for x in tags):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "tags must be an array of strings.")
    if custom_fields is not None and not isinstance(custom_fields, dict):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "custom_fields must be an object (key/value pairs).")

    tenants = _load("tenants.json")
    tenant = next((x for x in tenants if x.get("id") == tenant_id), None)
    if tenant is None or tenant.get("status") == "deleted":
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Tenant not found.")
    if not _tenant_usable(tenant):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Tenant has no usable Freshdesk credentials.")
    rl = _enforce_rate_limit(tenant)
    if rl:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": rl["error"]["code"]})
        return rl

    tickets = _load("tickets.json")
    # find local cached ticket by freshdesk_id (as tool uses Freshdesk ticket id)
    tk = next((x for x in tickets if x.get("tenant_id") == tenant_id and x.get("freshdesk_id") == ticket_id), None)
    if tk is None:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Ticket not found in local cache for this tenant.")
    if tk.get("freshdesk_id") is None:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "CONFLICT"})
        return _err("CONFLICT", "Cannot update ticket that has not been created upstream (freshdesk_id is null).")

    # Enforce lifecycle transition if we can infer cache status changes from numeric status
    def _num_to_cache_status(num):
        if not isinstance(num, int):
            return None
        if num == 2:
            return "open"
        if num == 3:
            return "pending"
        if num == 4:
            return "resolved"
        if num == 5:
            return "closed"
        return None

    transitions = {
        "open": {"pending", "resolved", "closed", "deleted"},
        "pending": {"open", "resolved", "closed", "deleted"},
        "resolved": {"open", "closed", "deleted"},
        "closed": {"open", "deleted"},
        "deleted": set(),
    }

    new_cache_status = _num_to_cache_status(status) if status is not None else None
    if new_cache_status is not None:
        cur = tk.get("status")
        if cur not in transitions:
            cur = "open"
        if new_cache_status != cur and new_cache_status not in transitions.get(cur, set()):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "INVALID_TRANSITION", "from": cur, "to": new_cache_status})
            return _err("INVALID_TRANSITION", "Illegal ticket status transition.", from_status=cur, to_status=new_cache_status)

    # Apply update (offline "upstream success" by mutating raw and synced timestamps)
    payload = {}
    if subject is not None:
        payload["subject"] = subject
        tk["subject"] = subject
    if description is not None:
        payload["description"] = description
        tk["description_text"] = description
    if priority is not None:
        payload["priority"] = priority
        tk["priority"] = priority
    if status is not None:
        payload["status"] = status
        if new_cache_status is not None:
            tk["status"] = new_cache_status
    if source is not None:
        payload["source"] = source
        tk["source"] = source
    if type is not None:
        payload["type"] = type
        tk["type"] = type
    if group_id is not None:
        payload["group_id"] = group_id
        tk["group_freshdesk_id"] = group_id
    if responder_id is not None:
        payload["responder_id"] = responder_id
        tk["agent_freshdesk_id"] = responder_id
    if company_id is not None:
        payload["company_id"] = company_id
        tk["company_freshdesk_id"] = company_id
    if tags is not None:
        payload["tags"] = tags
        tk["tags"] = tags
    if custom_fields is not None:
        payload["custom_fields"] = custom_fields
        tk["custom_fields"] = custom_fields

    # Update raw: merge into existing raw dict when possible
    raw = tk.get("raw")
    if not isinstance(raw, dict):
        raw = {}
    raw = dict(raw)
    raw.update(payload)
    tk["raw"] = raw

    # Search text refresh
    subj = tk.get("subject") if isinstance(tk.get("subject"), str) else ""
    desc = tk.get("description_text") if isinstance(tk.get("description_text"), str) else ""
    tk["search_text"] = " ".join([x for x in [subj, desc] if x])

    now_iso = _now_iso()
    tk["updated_at"] = now_iso
    tk["last_synced_at"] = now_iso

    # Persist
    updated = False
    for i, row in enumerate(tickets):
        if row.get("tenant_id") == tenant_id and row.get("freshdesk_id") == ticket_id:
            tickets[i] = tk
            updated = True
            break
    if not updated:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Ticket not found for update (internal state).")
    _save("tickets.json", tickets)

    _log(endpoint, tenant_id, "ok", (time.time() - t0) * 1000, {"freshdesk_id": ticket_id, "updated_fields": list(payload.keys())})
    return {"tenant_id": tenant_id, "ticket": tk}

def delete_ticket(tenant_id, ticket_id, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_ticket"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, tenant_row=None, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
                "credential_type": (tenant_row.get("auth_type") if isinstance(tenant_row, dict) else None),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now_iso(),
            }
            if error is not None:
                row["error"] = error
            if meta is not None:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _tenant_has_creds(t):
        if not isinstance(t, dict):
            return False
        if t.get("status") != "active":
            return False
        at = t.get("auth_type")
        if at == "api_key":
            return bool(t.get("api_key_ciphertext"))
        if at == "oauth":
            return bool(t.get("oauth_access_token_ciphertext"))
        return False

    def _enforce_rate_limit(tenant_row):
        rpm = tenant_row.get("rate_limit_per_minute")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= cutoff:
                count += 1
        if count >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=rpm)
        return None

    try:
        if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
            e = _err("VALIDATION_ERROR", "tenant_id is malformed.", field="tenant_id")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(ticket_id, int) or isinstance(ticket_id, bool) or ticket_id < 1:
            e = _err("VALIDATION_ERROR", "ticket_id must be a positive integer.", field="ticket_id")
            _append_log("error", error=e["error"])
            return e

        tenants = _load("tenants.json")
        if not isinstance(tenants, list):
            tenants = []
        tenant_row = None
        for t in tenants:
            if isinstance(t, dict) and t.get("id") == tenant_id and t.get("status") != "deleted":
                tenant_row = t
                break
        if tenant_row is None:
            e = _err("NOT_FOUND", "Tenant not found.")
            _append_log("error", error=e["error"])
            return e

        if not _tenant_has_creds(tenant_row):
            e = _err("UNAUTHORIZED", "Tenant Freshdesk credentials are missing/invalid.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        rl = _enforce_rate_limit(tenant_row)
        if rl:
            _append_log("error", tenant_row=tenant_row, error=rl["error"])
            return rl

        tickets = _load("tickets.json")
        if not isinstance(tickets, list):
            tickets = []

        # ticket_id parameter is a Freshdesk ticket id (not local id)
        target_idx = None
        for i, r in enumerate(tickets):
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_id:
                continue
            if r.get("freshdesk_id") == ticket_id:
                target_idx = i
                break
        if target_idx is None:
            e = _err("NOT_FOUND", "Ticket not found for this tenant.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        row = tickets[target_idx]
        if row.get("status") == "deleted":
            # idempotent delete: already deleted -> return current ticket row
            _append_log("ok", tenant_row=tenant_row, meta={"idempotent": True})
            return {"ticket": row}

        prev = row.get("status")
        allowed = {
            "open": ["pending", "resolved", "closed", "deleted"],
            "pending": ["open", "resolved", "closed", "deleted"],
            "resolved": ["open", "closed", "deleted"],
            "closed": ["open", "deleted"],
            "deleted": [],
        }
        if prev not in allowed or "deleted" not in allowed.get(prev, []):
            e = _err("INVALID_TRANSITION", f"Cannot transition ticket status from '{prev}' to 'deleted'.", from_status=prev, to_status="deleted")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        now = _now_iso()
        row["status"] = "deleted"
        row["updated_at"] = now
        # even if upstream delete fails/not-found, rule says local delete may succeed but must record last_synced_at
        row["last_synced_at"] = now
        tickets[target_idx] = row
        _save("tickets.json", tickets)

        _append_log("ok", tenant_row=tenant_row, meta={"deleted": True, "freshdesk_id": ticket_id})
        return {"ticket": row}
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(ex))
        _append_log("error", error=e["error"])
        return e

