            return False
        at = t.get("auth_type")
        if at == "api_key":
            return bool(t.get("api_key_ciphertext"))
        if at == "oauth":
            return bool(t.get("oauth_access_token_ciphertext"))
        return False

    def _enforce_rate_limit(tenant_row):
        rpm = tenant_row.get("rate_limit_per_minute")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= cutoff:
                count += 1
        if count >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=rpm)
        return None

    try:
        if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
            e = _err("VALIDATION_ERROR", "tenant_id is malformed.", field="tenant_id")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(ticket_id, int) or isinstance(ticket_id, bool) or ticket_id < 1:
            e = _err("VALIDATION_ERROR", "ticket_id must be a positive integer.", field="ticket_id")
            _append_log("error", error=e["error"])
            return e
        if refresh is not None and not isinstance(refresh, bool):
            e = _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")
            _append_log("error", error=e["error"])
            return e

        tenants = _load("tenants.json")
        if not isinstance(tenants, list):
            tenants = []
        tenant_row = None
        for t in tenants:
            if isinstance(t, dict) and t.get("id") == tenant_id and t.get("status") != "deleted":
                tenant_row = t
                break
        if tenant_row is None:
            e = _err("NOT_FOUND", "Tenant not found.")
            _append_log("error", error=e["error"])
            return e

        if not _tenant_has_creds(tenant_row):
            e = _err("UNAUTHORIZED", "Tenant Freshdesk credentials are missing/invalid.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        rl = _enforce_rate_limit(tenant_row)
        if rl:
            _append_log("error", tenant_row=tenant_row, error=rl["error"])
            return rl

        tickets = _load("tickets.json")
        if not isinstance(tickets, list):
            tickets = []

        # ticket_id parameter is Freshdesk ticket id
        found = None
        for r in tickets:
            if isinstance(r, dict) and r.get("tenant_id") == tenant_id and r.get("freshdesk_id") == ticket_id:
                found = r
                break

        if found is None:
            e = _err("NOT_FOUND", "Ticket not found for this tenant.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        # Offline server: "refresh" accepted but cannot call upstream; treat as no-op cache hit.
        _append_log("ok", tenant_row=tenant_row, meta={"refreshed": bool(refresh)})
        return {"ticket": found}
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(ex))
        _append_log("error", error=e["error"])
        return e

def search_tickets(tenant_id, query, page=None, page_size=None, sort_by=None, sort_order=None, refresh=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_tickets"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_value, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "fdlog_" + uuid.uuid4().hex[:24],
            "endpoint": endpoint,
            "tenant_id": tenant_id,
            "status": status_value,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if meta is not None:
            row["meta"] = meta
        if error is not None:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id):
        err = _err("VALIDATION_ERROR", "Invalid tenant_id.", field="tenant_id")
        _log("error", error=err["error"])
        return err
    if not isinstance(query, str) or not query.strip():
        err = _err("VALIDATION_ERROR", "Invalid query.", field="query")
        _log("error", error=err["error"])
        return err

    if page is None:
        page = 1
    if page_size is None:
        page_size = None  # maybe from tenant default
    if not isinstance(page, int) or page < 1:
        err = _err("VALIDATION_ERROR", "Invalid page.", field="page")
        _log("error", error=err["error"])
        return err
    if page_size is not None and (not isinstance(page_size, int) or page_size < 1 or page_size > 100):
        err = _err("VALIDATION_ERROR", "Invalid page_size.", field="page_size")
        _log("error", error=err["error"])
        return err
    if sort_by is not None and sort_by not in ("created_at", "updated_at"):
        err = _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")
        _log("error", error=err["error"])
        return err
    if sort_order is not None and sort_order not in ("asc", "desc"):
        err = _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order")
        _log("error", error=err["error"])
        return err
    if refresh is not None and not isinstance(refresh, bool):
        err = _err("VALIDATION_ERROR", "Invalid refresh flag.", field="refresh")
        _log("error", error=err["error"])
        return err
    refresh = bool(refresh) if refresh is not None else False

    tenants = _load("tenants.json")
    tenant = next((x for x in tenants if isinstance(x, dict) and x.get("id") == tenant_id), None)
    if not tenant:
        err = _err("NOT_FOUND", "Tenant not found.", tenant_id=tenant_id)
        _log("error", error=err["error"])
        return err
    if tenant.get("status") != "active":
        err = _err("UNAUTHORIZED", "Tenant is not active.")
        _log("error", error=err["error"])
        return err

    if page_size is None:
        dps = tenant.get("default_page_size")
        if isinstance(dps, int) and 1 <= dps <= 100:
            page_size = dps
        else:
            page_size = 25

    # Optional refresh (offline not supported)
    if refresh:
        auth_type = tenant.get("auth_type")
        if auth_type == "api_key":
            if not tenant.get("api_key_ciphertext"):
                err = _err("UNAUTHORIZED", "Missing Freshdesk API key for tenant.")
                _log("error", error=err["error"])
                return err
        elif auth_type == "oauth":
            if not tenant.get("oauth_access_token_ciphertext"):
                err = _err("UNAUTHORIZED", "Missing Freshdesk OAuth access token for tenant.")
                _log("error", error=err["error"])
                return err
        else:
            err = _err("UNAUTHORIZED", "Invalid tenant auth configuration.")
            _log("error", error=err["error"])
            return err
        err = _err("UPSTREAM_ERROR", "Freshdesk refresh requested but upstream is unavailable in offline mode.")
        _log("error", error=err["error"])
        return err

    tickets = _load("tickets.json")
    if not isinstance(tickets, list):
        tickets = []

    q = query.strip().lower()

    def _match(ticket):
        if not isinstance(ticket, dict):
            return False
        if ticket.get("tenant_id") != tenant_id:
            return False
        if ticket.get("status") == "deleted":
            return False
        st = ticket.get("search_text")
        if isinstance(st, str) and q in st.lower():
            return True
        raw = ticket.get("raw")
        try:
            raw_s = json.dumps(raw, ensure_ascii=False).lower() if isinstance(raw, (dict, list)) else (str(raw).lower() if raw is not None else "")
        except Exception:
            raw_s = ""
        if q in raw_s:
            return True
        subj = ticket.get("subject")
        if isinstance(subj, str) and q in subj.lower():
            return True
        desc = ticket.get("description_text")
        if isinstance(desc, str) and q in desc.lower():
            return True
        return False

    results = [t for t in tickets if _match(t)]

    sb = sort_by or "updated_at"
    so = sort_order or "desc"

    def _parse_dt(v):
        if not isinstance(v, str) or not v:
            return None
        try:
            # Handles Z and offsets
            vv = v.replace("Z", "+00:00")
            return datetime.datetime.fromisoformat(vv)
        except Exception:
            return None

    def _sort_key(t):
        dt = _parse_dt(t.get(sb)) or _parse_dt(t.get("updated_at")) or _parse_dt(t.get("created_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt

    results.sort(key=_sort_key, reverse=(so == "desc"))

    total = len(results)
    start = (page - 1) * page_size
    end = start + page_size
    page_items = results[start:end]
    has_more = end < total

    _log("success", meta={"total": total, "page": page, "page_size": page_size})
    return {
        "tenant_id": tenant_id,
        "query": query,
        "page": page,
        "page_size": page_size,
        "sort_by": sb,
        "sort_order": so,
        "total": total,
        "has_more": has_more,
        "tickets": page_items,
    }

def get_ticket_conversation(tenant_id, ticket_id, conversation_id, refresh=None, **_extra):
