                "credential_type": (tenant_row.get("auth_type") if isinstance(tenant_row, dict) else None),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now_iso(),
            }
            if error is not None:
                row["error"] = error
            if meta is not None:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _tenant_has_creds(t):
        if not isinstance(t, dict):
            return False
        if t.get("status") != "active":
            return False
        at = t.get("auth_type")
        if at == "api_key":
            return bool(t.get("api_key_ciphertext"))
        if at == "oauth":
            return bool(t.get("oauth_access_token_ciphertext"))
