    def _enforce_rate_limit(tenant_row):
        rpm = tenant_row.get("rate_limit_per_minute")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= cutoff:
                count += 1
        if count >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=rpm)
        return None

    try:
        if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
            e = _err("VALIDATION_ERROR", "tenant_id is malformed.", field="tenant_id")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(ticket_id, int) or isinstance(ticket_id, bool) or ticket_id < 1:
            e = _err("VALIDATION_ERROR", "ticket_id must be a positive integer.", field="ticket_id")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(conversation_id, int) or isinstance(conversation_id, bool) or conversation_id < 1:
            e = _err("VALIDATION_ERROR", "conversation_id must be a positive integer.", field="conversation_id")
            _append_log("error", error=e["error"])
            return e
        if refresh is not None and not isinstance(refresh, bool):
            e = _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")
            _append_log("error", error=e["error"])
            return e

        tenants = _load("tenants.json")
        if not isinstance(tenants, list):
            tenants = []
        tenant_row = None
        for t in tenants:
            if isinstance(t, dict) and t.get("id") == tenant_id and t.get("status") != "deleted":
                tenant_row = t
                break
        if tenant_row is None:
            e = _err("NOT_FOUND", "Tenant not found.")
            _append_log("error", error=e["error"])
            return e

        if not _tenant_has_creds(tenant_row):
            e = _err("UNAUTHORIZED", "Tenant Freshdesk credentials are missing/invalid.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        rl = _enforce_rate_limit(tenant_row)
        if rl:
            _append_log("error", tenant_row=tenant_row, error=rl["error"])
            return rl

        tickets = _load("tickets.json")
        if not isinstance(tickets, list):
            tickets = []

        # Ensure the ticket belongs to tenant; ticket_id param is Freshdesk ticket id
        local_ticket = None
        for t in tickets:
            if isinstance(t, dict) and t.get("tenant_id") == tenant_id and t.get("freshdesk_id") == ticket_id:
                local_ticket = t
                break
        if local_ticket is None:
            e = _err("NOT_FOUND", "Ticket not found for this tenant.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        convs = _load("ticket_conversations.json")
        if not isinstance(convs, list):
            convs = []

        # conversation_id param is Freshdesk conversation id; also enforce tenant and local ticket_id FK
        found = None
        for c in convs:
            if not isinstance(c, dict):
                continue
            if c.get("tenant_id") != tenant_id:
                continue
            if c.get("ticket_id") != local_ticket.get("id"):
                continue
            if c.get("freshdesk_id") == conversation_id:
                found = c
                break

        if found is None:
            e = _err("NOT_FOUND", "Conversation not found for this tenant and ticket.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        _append_log("ok", tenant_row=tenant_row, meta={"refreshed": bool(refresh)})
        return {"conversation": found, "ticket": local_ticket}
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(ex))
        _append_log("error", error=e["error"])
        return e

def create_ticket_reply(tenant_id, ticket_id, body_html=None, body_text=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_ticket_reply"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        def enc(v, n):
            out = []
            for _ in range(n):
                out.append(_CROCKFORD[v & 31])
                v >>= 5
            return "".join(reversed(out))
        # 48-bit time => 10 chars, 80-bit randomness => 16 chars
        rand = random.getrandbits(80)
        return enc(ms, 10) + enc(rand, 16)

    def _log(status, tenant_row=None, error_code=None):
        # Best-effort request logging if collection exists.
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "fdlog_" + _ulid(),
                "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
                "endpoint": endpoint,
                "status": status,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "created_at": _now(),
            })
            _save("request_logs.json", logs)

        # Rate limit enforcement: tenant.rate_limit_per_minute
        if tenant_row and isinstance(tenant_row, dict):
            rlim = tenant_row.get("rate_limit_per_minute")
            if isinstance(rlim, int) and 1 <= rlim <= 600 and isinstance(logs, list):
                cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
                count = 0
                for r in logs:
                    if r.get("tenant_id") != tenant_row.get("id"):
                        continue
                    ts = _parse_dt(r.get("created_at"))
                    if ts and ts >= cutoff:
                        count += 1
                if count > rlim:
                    return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=rlim)
        return None

    # Validate inputs
    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{26}$", tenant_id):
        out = _err("VALIDATION_ERROR", "Invalid tenant_id.")
        _log("error", None, "VALIDATION_ERROR")
        return out
    if not isinstance(ticket_id, str) or not re.match(r"^fdtkt_[0-9A-HJKMNP-TV-Z]{26}$", ticket_id):
        out = _err("VALIDATION_ERROR", "Invalid ticket_id.")
        _log("error", None, "VALIDATION_ERROR")
        return out
    if body_html is not None and not isinstance(body_html, str):
        out = _err("VALIDATION_ERROR", "body_html must be a string when provided.")
        _log("error", None, "VALIDATION_ERROR")
        return out
    if body_text is not None and not isinstance(body_text, str):
        out = _err("VALIDATION_ERROR", "body_text must be a string when provided.")
        _log("error", None, "VALIDATION_ERROR")
        return out
    if (body_html is None or body_html.strip() == "") and (body_text is None or body_text.strip() == ""):
        out = _err("VALIDATION_ERROR", "Either body_html or body_text must be provided.")
        _log("error", None, "VALIDATION_ERROR")
        return out

    tenants = _load("tenants.json")
    tenant = None
    if isinstance(tenants, list):
        for tr in tenants:
            if isinstance(tr, dict) and tr.get("id") == tenant_id:
                tenant = tr
                break
    if not tenant or tenant.get("status") != "active":
        out = _err("UNAUTHORIZED", "Tenant is not authorized or not active.")
        _log("error", tenant, "UNAUTHORIZED")
        return out

    # Rate limit check before doing work (based on existing logs)
    pre_rl = _log("precheck", tenant, None)
    if isinstance(pre_rl, dict) and pre_rl.get("error"):
        return pre_rl

    # Check tenant has usable connection (do not validate ciphertext contents; just presence per rules)
    auth_type = tenant.get("auth_type")
    if auth_type == "api_key":
        if not tenant.get("api_key_ciphertext"):
            out = _err("UNAUTHORIZED", "Tenant Freshdesk API key connection is missing.")
            _log("error", tenant, "UNAUTHORIZED")
            return out
    elif auth_type == "oauth":
        if not tenant.get("oauth_access_token_ciphertext"):
            out = _err("UNAUTHORIZED", "Tenant Freshdesk OAuth connection is missing.")
            _log("error", tenant, "UNAUTHORIZED")
            return out
    else:
        out = _err("UNAUTHORIZED", "Tenant Freshdesk connection is invalid.")
        _log("error", tenant, "UNAUTHORIZED")
        return out

    tickets = _load("tickets.json")
    ticket = None
    ti = None
    if isinstance(tickets, list):
        for i, r in enumerate(tickets):
            if isinstance(r, dict) and r.get("id") == ticket_id and r.get("tenant_id") == tenant_id:
                ticket = r
                ti = i
                break
    if not ticket:
        out = _err("NOT_FOUND", "Ticket not found.")
        _log("error", tenant, "NOT_FOUND")
        return out
    if ticket.get("freshdesk_id") is None:
        out = _err("INVALID_TRANSITION", "Cannot create a reply for a ticket that has not been created upstream (freshdesk_id is null).")
        _log("error", tenant, "INVALID_TRANSITION")
        return out
    if ticket.get("status") == "deleted":
        out = _err("INVALID_TRANSITION", "Cannot create a reply for a deleted ticket.")
        _log("error", tenant, "INVALID_TRANSITION")
        return out

    # Create local conversation row first (freshdesk_id null) with request payload in raw
    conversations = _load("ticket_conversations.json")
    if not isinstance(conversations, list):
        conversations = []

    now = _now()
    payload = {
        "body": body_html if (isinstance(body_html, str) and body_html.strip() != "") else body_text,
        "body_html": body_html,
        "body_text": body_text,
        "type": "reply",
        "ticket_freshdesk_id": ticket.get("freshdesk_id"),
    }

    conv_id = "fdcnv_" + _ulid()
    conv = {
        "id": conv_id,
        "tenant_id": tenant_id,
        "ticket_id": ticket_id,
        "status": "active",
        "freshdesk_id": None,
        "conversation_type": "reply",
        "body_html": body_html,
        "body_text": body_text,
        "private": False,
        "author_freshdesk_id": None,
        "raw": payload,
        "last_synced_at": None,
        "created_at": now,
