    tenants = _load("tenants.json")
    tenant = None
    if isinstance(tenants, list):
        for tr in tenants:
            if isinstance(tr, dict) and tr.get("id") == tenant_id:
                tenant = tr
                break
    if not tenant or tenant.get("status") != "active":
        out = _err("UNAUTHORIZED", "Tenant is not authorized or not active.")
        _log("error", tenant, "UNAUTHORIZED")
        return out

    pre_rl = _log("precheck", tenant, None)
    if isinstance(pre_rl, dict) and pre_rl.get("error"):
        return pre_rl

    auth_type = tenant.get("auth_type")
    if auth_type == "api_key":
        if not tenant.get("api_key_ciphertext"):
            out = _err("UNAUTHORIZED", "Tenant Freshdesk API key connection is missing.")
            _log("error", tenant, "UNAUTHORIZED")
            return out
    elif auth_type == "oauth":
        if not tenant.get("oauth_access_token_ciphertext"):
            out = _err("UNAUTHORIZED", "Tenant Freshdesk OAuth connection is missing.")
            _log("error", tenant, "UNAUTHORIZED")
            return out
    else:
        out = _err("UNAUTHORIZED", "Tenant Freshdesk connection is invalid.")
        _log("error", tenant, "UNAUTHORIZED")
        return out

    if per_page is None:
        dps = tenant.get("default_page_size")
        per_page = dps if isinstance(dps, int) and 1 <= dps <= 100 else 30

    people = _load("people_and_orgs.json")
    if not isinstance(people, list):
        people = []

    # Filter
    rows = []
    for r in people:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") != tenant_id:
            continue
        if r.get("entity_type") != "agent":
            continue
        if not include_deleted and r.get("status") == "deleted":
            continue
        if dt_since:
            ru = _parse_dt(r.get("updated_at"))
            if not ru or ru < dt_since:
                continue
        rows.append(r)

    # Sort by updated_at desc then id for stability
    def _sort_key(r):
        dt = _parse_dt(r.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, r.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    start = (page - 1) * per_page
    end = start + per_page
    page_rows = rows[start:end]
    has_more = end < total

    _log("ok", tenant, None)
    return {
        "agents": page_rows,
        "page": page,
        "per_page": per_page,
        "total": total,
        "has_more": has_more
    }

def list_contacts(tenant_id, page=None, per_page=None, updated_since=None, include_deleted=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # Accept trailing Z
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            return _parse_dt(v)
        return None

    def _log(status, tenant_row=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": None,
            "endpoint": "list_contacts",
            "tenant_id": tenant_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        logs.append(entry)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{26}$", tenant_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed tenant_id.")

    if page is None:
        page = 1
    if per_page is None:
        per_page = None  # may take from tenant default

    if not isinstance(page, int) or page < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if per_page is not None and (not isinstance(per_page, int) or per_page < 1 or per_page > 100):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "per_page must be an integer between 1 and 100.")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean.")
    since_dt = None
    if updated_since is not None:
        since_dt = _parse_dt(updated_since)
        if since_dt is None:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "updated_since must be an RFC3339 date-time string.")

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if tenant is None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Tenant not found.")
    if tenant.get("status") != "active":
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant is not active.")
    # Require a working auth configuration in store (cannot validate plaintext secrets)
    auth_type = tenant.get("auth_type")
    if auth_type == "api_key":
        if not tenant.get("api_key_ciphertext"):
            _log("error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tenant Freshdesk API key is not configured.")
    elif auth_type == "oauth":
        if not tenant.get("oauth_access_token_ciphertext"):
            _log("error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tenant Freshdesk OAuth token is not configured.")
    else:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant Freshdesk authentication is not configured.")

    if per_page is None:
        per_page = tenant.get("default_page_size") if isinstance(tenant.get("default_page_size"), int) else 25
        if per_page < 1: per_page = 1
        if per_page > 100: per_page = 100

    # Enforce internal rate limit per tenant
    rpm = tenant.get("rate_limit_per_minute")
    if not isinstance(rpm, int) or rpm < 1:
        rpm = 60
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict): 
            continue
        if r.get("tenant_id") != tenant_id:
            continue
        ts = _parse_dt(r.get("timestamp")) if isinstance(r.get("timestamp"), str) else None
        if ts is not None and ts >= cutoff:
            recent += 1
    if recent >= rpm:
        _log("error", error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rpm)

    rows = _load("people_and_orgs.json")
    if not isinstance(rows, list):
        rows = []

    # Filter to tenant contacts
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") != tenant_id:
            continue
        if r.get("entity_type") != "contact":
            continue
        if not include_deleted and r.get("status") == "deleted":
            continue
        if since_dt is not None:
            upd = _dt_from_row(r.get("updated_at")) or _dt_from_row(r.get("last_synced_at"))
            if upd is None or upd < since_dt:
                continue
        out.append(r)

    # Sort by updated_at desc for stable paging
    def _sort_key(r):
        d = _dt_from_row(r.get("updated_at")) or _dt_from_row(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return d
    out.sort(key=_sort_key, reverse=True)

    total = len(out)
    start = (page - 1) * per_page
    end = start + per_page
    page_rows = out[start:end]
    has_more = end < total

    _log("ok")
    return {
        "contacts": page_rows,
        "page": page,
        "per_page": per_page,
        "total": total,
        "has_more": has_more,
    }

def get_contact(tenant_id, contact_id, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_contact"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _append_log(status, tenant_row=None, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
                "credential_type": (tenant_row.get("auth_type") if isinstance(tenant_row, dict) else None),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now_iso(),
                **({"error": error} if error is not None else {}),
                **({"meta": meta} if meta is not None else {}),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _tenant_has_creds(t):
        if not isinstance(t, dict):
            return False
        if t.get("status") != "active":
            return False
        at = t.get("auth_type")
        if at == "api_key":
            return bool(t.get("api_key_ciphertext"))
        if at == "oauth":
            return bool(t.get("oauth_access_token_ciphertext"))
        return False

    def _enforce_rate_limit(tenant_row):
        rpm = tenant_row.get("rate_limit_per_minute")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= cutoff:
                count += 1
        if count >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=rpm)
        return None

    try:
        # Relaxed validation to accept actual datastore ids and caller inputs; still validate type/non-empty.
        if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
            e = _err("VALIDATION_ERROR", "tenant_id is malformed.", field="tenant_id")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(contact_id, str) or not contact_id.strip():
            e = _err("VALIDATION_ERROR", "contact_id is malformed.", field="contact_id")
            _append_log("error", error=e["error"])
            return e

        tenants = _load("tenants.json")
        if not isinstance(tenants, list):
            tenants = []
        tenant_row = None
        for t in tenants:
            if isinstance(t, dict) and t.get("id") == tenant_id and t.get("status") != "deleted":
                tenant_row = t
                break
        if tenant_row is None:
            e = _err("NOT_FOUND", "Tenant not found.")
            _append_log("error", error=e["error"])
            return e

        if not _tenant_has_creds(tenant_row):
            e = _err("UNAUTHORIZED", "Tenant Freshdesk credentials are missing/invalid.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        rl = _enforce_rate_limit(tenant_row)
        if rl:
            _append_log("error", tenant_row=tenant_row, error=rl["error"])
            return rl

        rows = _load("people_and_orgs.json")
        if not isinstance(rows, list):
            rows = []

        found = None
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("id") == contact_id and r.get("tenant_id") == tenant_id and r.get("entity_type") == "contact":
                found = r
                break

        if found is None:
            e = _err("NOT_FOUND", "Contact not found for this tenant.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        _append_log("ok", tenant_row=tenant_row)
        return {"contact": found}
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(ex))
        _append_log("error", error=e["error"])
        return e

def search_contacts(tenant_id, query=None, email=None, phone=None, company_freshdesk_id=None, is_active=None, include_deleted=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            return _parse_dt(v)
        return None

    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": None,
            "endpoint": "search_contacts",
            "tenant_id": tenant_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{26}$", tenant_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed tenant_id.")
    if query is not None and not isinstance(query, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a string.")
    if email is not None and not isinstance(email, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "email must be a string.")
    if phone is not None and not isinstance(phone, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "phone must be a string.")
    if company_freshdesk_id is not None and (not isinstance(company_freshdesk_id, int) or company_freshdesk_id <= 0):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "company_freshdesk_id must be a positive integer.")
    if is_active is not None and not isinstance(is_active, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_active must be a boolean.")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean.")
    if sort_by is None:
        sort_by = "updated_at"
    if sort_order is None:
        sort_order = "desc"
    if sort_by not in ("name", "email", "updated_at", "last_synced_at"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_by must be one of: name, email, updated_at, last_synced_at.")
    if sort_order not in ("asc", "desc"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if tenant is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Tenant not found.")
    if tenant.get("status") != "active":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant is not active.")
    auth_type = tenant.get("auth_type")
    if auth_type == "api_key":
        if not tenant.get("api_key_ciphertext"):
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tenant Freshdesk API key is not configured.")
    elif auth_type == "oauth":
        if not tenant.get("oauth_access_token_ciphertext"):
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tenant Freshdesk OAuth token is not configured.")
    else:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant Freshdesk authentication is not configured.")

    # Rate limit
    rpm = tenant.get("rate_limit_per_minute")
    if not isinstance(rpm, int) or rpm < 1:
        rpm = 60
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict): 
            continue
        if r.get("tenant_id") != tenant_id:
            continue
        ts = _parse_dt(r.get("timestamp")) if isinstance(r.get("timestamp"), str) else None
        if ts is not None and ts >= cutoff:
            recent += 1
    if recent >= rpm:
        _log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rpm)

    def _cursor_decode(cur):
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _cursor_encode(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Apply cursor (offset-based, but cursor includes a signature)
    offset = 0
    if cursor:
        cobj = _cursor_decode(cursor)
        if not cobj:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        if cobj.get("tenant_id") != tenant_id:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cursor does not belong to this tenant.")
        if cobj.get("v") != 1 or not isinstance(cobj.get("offset"), int) or cobj.get("offset") < 0:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        # verify signature to keep it opaque-ish
        sig = cobj.get("sig")
        payload = f"{tenant_id}:{cobj.get('offset')}:{sort_by}:{sort_order}".encode("utf-8")
        expected = hashlib.sha256(payload).hexdigest()
        if sig != expected:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        offset = cobj["offset"]

    rows = _load("people_and_orgs.json")
    if not isinstance(rows, list):
        rows = []

    q = (query or "").strip().lower()
    em = (email or "").strip().lower() if email is not None else None
    ph = (phone or "").strip().lower() if phone is not None else None

    def _match(r):
        if r.get("tenant_id") != tenant_id or r.get("entity_type") != "contact":
            return False
        if not include_deleted and r.get("status") == "deleted":
            return False
        if company_freshdesk_id is not None and r.get("company_freshdesk_id") != company_freshdesk_id:
            return False
        if is_active is not None and r.get("is_active") != is_active:
            return False
        if em is not None:
            rev = r.get("email")
            if not isinstance(rev, str) or em not in rev.lower():
                return False
        if ph is not None:
            rpv = r.get("phone")
            if not isinstance(rpv, str) or ph not in rpv.lower():
                return False
        if q:
            st = r.get("search_text")
            hay = ""
            if isinstance(st, str):
                hay = st.lower()
            else:
                # fallback to some raw fields
                raw = r.get("raw")
                if isinstance(raw, dict):
                    parts = []
                    for k in ("name", "email", "phone"):
                        v = raw.get(k)
                        if isinstance(v, str):
                            parts.append(v)
                    hay = " ".join(parts).lower()
            if q not in hay:
                return False
        return True

    matched = [r for r in rows if isinstance(r, dict) and _match(r)]

    def _sort_val(r):
        if sort_by in ("updated_at", "last_synced_at"):
            return _dt_from_row(r.get(sort_by)) or _dt_from_row(r.get("updated_at")) or _dt_from_row(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        v = r.get(sort_by)
        if isinstance(v, str):
            return v.lower()
        return "" if v is None else str(v)

    reverse = (sort_order == "desc")
    matched.sort(key=_sort_val, reverse=reverse)

    total = len(matched)
    page_rows = matched[offset:offset + limit]
    next_offset = offset + len(page_rows)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = f"{tenant_id}:{next_offset}:{sort_by}:{sort_order}".encode("utf-8")
        sig = hashlib.sha256(payload).hexdigest()
        next_cursor = _cursor_encode({"v": 1, "tenant_id": tenant_id, "offset": next_offset, "sig": sig})

    _log("ok")
    return {
        "contacts": page_rows,
        "total": total,
        "limit": limit,
        "cursor": next_cursor,
        "has_more": has_more,
        "sort_by": sort_by,
        "sort_order": sort_order,
    }

def update_contact(tenant_id, contact_id, name=None, email=None, phone=None, company_freshdesk_id=None, is_active=None, custom_fields=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_contact"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _append_log(status, tenant_row=None, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
                "credential_type": (tenant_row.get("auth_type") if isinstance(tenant_row, dict) else None),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now_iso(),
                **({"error": error} if error is not None else {}),
                **({"meta": meta} if meta is not None else {}),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _tenant_has_creds(t):
        if not isinstance(t, dict):
            return False
        if t.get("status") != "active":
            return False
        at = t.get("auth_type")
        if at == "api_key":
            return bool(t.get("api_key_ciphertext"))
        if at == "oauth":
            return bool(t.get("oauth_access_token_ciphertext"))
        return False

    def _valid_email(x):
        return isinstance(x, str) and re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", x) is not None

    def _enforce_rate_limit(tenant_row):
        rpm = tenant_row.get("rate_limit_per_minute")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= cutoff:
                count += 1
        if count >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=rpm)
        return None

    try:
        if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
            e = _err("VALIDATION_ERROR", "tenant_id is malformed.", field="tenant_id")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(contact_id, str) or not contact_id.strip():
            e = _err("VALIDATION_ERROR", "contact_id is malformed.", field="contact_id")
            _append_log("error", error=e["error"])
            return e

        # Validate provided fields
        if name is not None and (not isinstance(name, str) or not name.strip()):
            e = _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
            _append_log("error", error=e["error"])
            return e
        if email is not None and not _valid_email(email):
            e = _err("VALIDATION_ERROR", "email must be a valid email address.", field="email")
            _append_log("error", error=e["error"])
            return e
        if phone is not None and (not isinstance(phone, str) or not phone.strip()):
            e = _err("VALIDATION_ERROR", "phone must be a non-empty string.", field="phone")
            _append_log("error", error=e["error"])
            return e
        if company_freshdesk_id is not None and (not isinstance(company_freshdesk_id, int) or isinstance(company_freshdesk_id, bool) or company_freshdesk_id < 1):
            e = _err("VALIDATION_ERROR", "company_freshdesk_id must be a positive integer.", field="company_freshdesk_id")
            _append_log("error", error=e["error"])
            return e
        if is_active is not None and not isinstance(is_active, bool):
            e = _err("VALIDATION_ERROR", "is_active must be a boolean.", field="is_active")
            _append_log("error", error=e["error"])
            return e
        if custom_fields is not None and not isinstance(custom_fields, dict):
            e = _err("VALIDATION_ERROR", "custom_fields must be an object.", field="custom_fields")
            _append_log("error", error=e["error"])
            return e

        if all(v is None for v in (name, email, phone, company_freshdesk_id, is_active, custom_fields)):
            e = _err("VALIDATION_ERROR", "At least one updatable field must be provided.")
            _append_log("error", error=e["error"])
            return e

        tenants = _load("tenants.json")
        if not isinstance(tenants, list):
            tenants = []
        tenant_row = None
        for t in tenants:
            if isinstance(t, dict) and t.get("id") == tenant_id and t.get("status") != "deleted":
                tenant_row = t
                break
        if tenant_row is None:
            e = _err("NOT_FOUND", "Tenant not found.")
            _append_log("error", error=e["error"])
            return e
        if not _tenant_has_creds(tenant_row):
            e = _err("UNAUTHORIZED", "Tenant Freshdesk credentials are missing/invalid.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        rl = _enforce_rate_limit(tenant_row)
        if rl:
            _append_log("error", tenant_row=tenant_row, error=rl["error"])
            return rl

        rows = _load("people_and_orgs.json")
        if not isinstance(rows, list):
            rows = []

        idx = None
        for i, r in enumerate(rows):
            if isinstance(r, dict) and r.get("id") == contact_id and r.get("tenant_id") == tenant_id and r.get("entity_type") == "contact":
                idx = i
                break
        if idx is None:
            e = _err("NOT_FOUND", "Contact not found for this tenant.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        row = rows[idx]

        # Cannot update upstream object that does not exist
        if row.get("freshdesk_id") is None:
            e = _err("INVALID_TRANSITION", "Cannot update contact because it has not been created in Freshdesk yet (freshdesk_id is null).")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        # Enforce partial unique email per tenant for active contacts, when email present
        if email is not None:
            email_l = email.strip().lower()
            for j, other in enumerate(rows):
                if j == idx or not isinstance(other, dict):
                    continue
                if other.get("tenant_id") != tenant_id or other.get("entity_type") != "contact" or other.get("status") != "active":
                    continue
                oemail = other.get("email")
                if isinstance(oemail, str) and oemail.strip().lower() == email_l:
                    e = _err("CONFLICT", "A contact with this email already exists for this tenant.", field="email")
                    _append_log("error", tenant_row=tenant_row, error=e["error"])
                    return e

        now = _now_iso()

        # Update cached fields
        if name is not None:
            row["name"] = name
        if email is not None:
            row["email"] = email
        if phone is not None:
            row["phone"] = phone
        if company_freshdesk_id is not None:
            row["company_freshdesk_id"] = company_freshdesk_id
        if is_active is not None:
            row["is_active"] = is_active

        # Merge raw payload as "last known sent/received"
        raw = row.get("raw")
        if not isinstance(raw, dict):
            raw = {}
        raw_updates = {}
        if name is not None:
            raw_updates["name"] = name
        if email is not None:
            raw_updates["email"] = email
        if phone is not None:
            raw_updates["phone"] = phone
        if company_freshdesk_id is not None:
            raw_updates["company_id"] = company_freshdesk_id
        if is_active is not None:
            raw_updates["active"] = is_active
        if custom_fields is not None:
            raw_updates["custom_fields"] = custom_fields
        raw.update(raw_updates)
        row["raw"] = raw

        # Update denormalized search_text
        st_parts = []
        for k in ("name", "email", "phone"):
            v = row.get(k)
            if isinstance(v, str) and v.strip():
                st_parts.append(v.strip())
        row["search_text"] = " ".join(st_parts) if st_parts else row.get("search_text")

        row["updated_at"] = now
        row["last_synced_at"] = now

        rows[idx] = row
        _save("people_and_orgs.json", rows)

        _append_log("ok", tenant_row=tenant_row, meta={"updated": True})
        return {"contact": row}
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(ex))
        _append_log("error", error=e["error"])
        return e

def list_canned_responses(tenant_id, folder_freshdesk_id=None, q=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(tenant_row, status_code, error_code=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": now,
            "endpoint": "list_canned_responses",
            "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

        if tenant_row:
            tenants = _load("tenants.json")
            if isinstance(tenants, list):
                for i, tr in enumerate(tenants):
                    if isinstance(tr, dict) and tr.get("id") == tenant_row.get("id"):
                        tr["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                        tenants[i] = tr
                        _save("tenants.json", tenants)
                        break

    def _parse_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if not isinstance(obj, dict):
            return _err("VALIDATION_ERROR", "Invalid cursor")
        v = obj.get("v")
        if v != 1:
            return _err("VALIDATION_ERROR", "Invalid cursor version")
        if obj.get("tenant_id") != tenant_id:
            return _err("VALIDATION_ERROR", "Cursor does not belong to this tenant")
        return obj

    def _make_cursor(offset):
        payload = {"v": 1, "tenant_id": tenant_id, "offset": offset}
        b = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{26}$", tenant_id):
        _log(None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed tenant_id")

    if folder_freshdesk_id is not None:
        if not isinstance(folder_freshdesk_id, int) or folder_freshdesk_id < 1:
            _log(None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "folder_freshdesk_id must be an integer >= 1")

    if q is not None and not isinstance(q, str):
        _log(None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "q must be a string")

    allowed_status = {"active", "draft", "archived", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status")

    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log(None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    allowed_sort = {"updated_at", "created_at", "freshdesk_id", "name", "title"}
    if sort is not None:
        if not isinstance(sort, str) or sort not in allowed_sort:
            _log(None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort")

    allowed_order = {"asc", "desc"}
    if order is not None:
        if not isinstance(order, str) or order not in allowed_order:
            _log(None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid order")

    cur = _parse_cursor(cursor)
    if isinstance(cur, dict) and cur.get("error"):
        _log(None, 400, "VALIDATION_ERROR")
        return cur

    tenants = _load("tenants.json")
    if not isinstance(tenants, list):
        tenants = []
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row or tenant_row.get("status") != "active":
        _log(tenant_row, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant is not authorized or not active")

    # Rate limit per tenant (per minute)
    rate_limit = tenant_row.get("rate_limit_per_minute")
    if isinstance(rate_limit, int) and rate_limit > 0:
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        window_start = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_id:
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.replace(tzinfo=None) >= window_start:
                count += 1
        if count >= rate_limit:
            _log(tenant_row, 429, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded")

    # Defaults
    if limit is None:
        dps = tenant_row.get("default_page_size")
        limit = dps if isinstance(dps, int) and 1 <= dps <= 100 else 50
        limit = min(limit, 200)
    if sort is None:
        sort = "updated_at"
    if order is None:
        order = "desc"

    offset = 0
    if cur:
        off = cur.get("offset")
        if not isinstance(off, int) or off < 0:
            _log(tenant_row, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        offset = off

    rows = _load("knowledge_and_templates.json")
    if not isinstance(rows, list):
        rows = []

    # Filter
    out = []
    q_norm = (q or "").strip().lower()
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") != tenant_id:
            continue
        if r.get("record_type") != "canned_response":
            continue

        r_status = r.get("status")
        if status is not None:
            if r_status != status:
                continue
        else:
            if r_status == "deleted":
                continue

        if folder_freshdesk_id is not None:
            if r.get("parent_freshdesk_id") != folder_freshdesk_id:
                continue

        if q_norm:
            st = r.get("search_text") or ""
            raw = r.get("raw")
            raw_s = ""
            if isinstance(raw, dict):
                try:
                    raw_s = json.dumps(raw, ensure_ascii=False).lower()
                except Exception:
                    raw_s = ""
            hay = (str(st).lower() + " " + raw_s)
            if q_norm not in hay:
                continue

        out.append(r)

    # Sort
    reverse = (order == "desc")

    def _key(v):
        if v is None:
            return ""
        return v

    def sort_key(r):
        v = r.get(sort)
        if sort in ("created_at", "updated_at", "last_synced_at", "oauth_token_expires_at"):
            if isinstance(v, str):
                return v
            return ""
        if sort == "freshdesk_id":
            return v if isinstance(v, int) else -1
        return str(_key(v)).lower()

    out.sort(key=sort_key, reverse=reverse)

    total = len(out)
    page = out[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _make_cursor(next_offset) if has_more else None

    resp = {"data": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

    _log(tenant_row, 200)
    return resp

