            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.replace(tzinfo=None) >= window_start:
                count += 1
        if count >= rate_limit:
            _log(tenant_row, 429, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded")

    # Defaults
    if limit is None:
        dps = tenant_row.get("default_page_size")
        limit = dps if isinstance(dps, int) and 1 <= dps <= 100 else 50
        limit = min(limit, 200)
    if sort is None:
        sort = "updated_at"
    if order is None:
        order = "desc"

    offset = 0
    if cur:
        off = cur.get("offset")
        if not isinstance(off, int) or off < 0:
            _log(tenant_row, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        offset = off

    rows = _load("knowledge_and_templates.json")
    if not isinstance(rows, list):
        rows = []

    # Filter
    out = []
    q_norm = (q or "").strip().lower()
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") != tenant_id:
            continue
        if r.get("record_type") != "canned_folder":
            continue

        r_status = r.get("status")
        if status is not None:
            if r_status != status:
                continue
        else:
            if r_status == "deleted":
                continue

        if q_norm:
            st = r.get("search_text") or ""
            raw = r.get("raw")
            raw_s = ""
            if isinstance(raw, dict):
                try:
                    raw_s = json.dumps(raw, ensure_ascii=False).lower()
                except Exception:
                    raw_s = ""
            hay = (str(st).lower() + " " + raw_s)
            if q_norm not in hay:
                continue

        out.append(r)

    # Sort
    reverse = (order == "desc")

    def _key(v):
        if v is None:
            return ""
        return v

    def sort_key(r):
        v = r.get(sort)
        if sort in ("created_at", "updated_at", "last_synced_at", "oauth_token_expires_at"):
            if isinstance(v, str):
                return v
            return ""
        if sort == "freshdesk_id":
            return v if isinstance(v, int) else -1
        return str(_key(v)).lower()

    out.sort(key=sort_key, reverse=reverse)

    total = len(out)
    page = out[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _make_cursor(next_offset) if has_more else None

    resp = {"data": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

    _log(tenant_row, 200)
    return resp

def view_canned_response(tenant_id, canned_response_id=None, freshdesk_id=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
