            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

        if tenant_row:
            tenants = _load("tenants.json")
            if isinstance(tenants, list):
                for i, tr in enumerate(tenants):
                    if isinstance(tr, dict) and tr.get("id") == tenant_row.get("id"):
                        tr["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                        tenants[i] = tr
                        _save("tenants.json", tenants)
                        break

    # Validate
    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{26}$", tenant_id):
        _log(None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed tenant_id")

    if canned_response_id is None and freshdesk_id is None:
        _log(None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Either canned_response_id or freshdesk_id must be provided")

    if canned_response_id is not None:
        if not isinstance(canned_response_id, str) or not re.match(r"^fdkb_[0-9A-HJKMNP-TV-Z]{26}$", canned_response_id):
            _log(None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Malformed canned_response_id")

    if freshdesk_id is not None:
        if not isinstance(freshdesk_id, int) or freshdesk_id < 1:
            _log(None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "freshdesk_id must be an integer >= 1")

    tenants = _load("tenants.json")
    if not isinstance(tenants, list):
        tenants = []
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row or tenant_row.get("status") != "active":
        _log(tenant_row, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant is not authorized or not active")

    # Rate limit per tenant (per minute)
    rate_limit = tenant_row.get("rate_limit_per_minute")
    if isinstance(rate_limit, int) and rate_limit > 0:
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        window_start = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_id:
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.replace(tzinfo=None) >= window_start:
                count += 1
        if count >= rate_limit:
            _log(tenant_row, 429, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded")

    rows = _load("knowledge_and_templates.json")
    if not isinstance(rows, list):
        rows = []

    matches = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") != tenant_id:
            continue
        if r.get("record_type") != "canned_response":
            continue
        if canned_response_id is not None and r.get("id") == canned_response_id:
            matches.append(r)
        elif freshdesk_id is not None and r.get("freshdesk_id") == freshdesk_id:
            matches.append(r)

    if len(matches) == 0:
        _log(tenant_row, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Canned response not found")
    if len(matches) > 1:
        _log(tenant_row, 409, "CONFLICT")
        return _err("CONFLICT", "Multiple canned responses matched the provided identifier(s)")

    _log(tenant_row, 200)
    return {"data": matches[0]}

def create_canned_response(tenant_id, folder_freshdesk_id, title, content_html, status=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(tenant_row, status_code, error_code=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": now,
            "endpoint": "create_canned_response",
            "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

        if tenant_row:
            tenants = _load("tenants.json")
            if isinstance(tenants, list):
                for i, tr in enumerate(tenants):
                    if isinstance(tr, dict) and tr.get("id") == tenant_row.get("id"):
                        tr["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                        tenants[i] = tr
                        _save("tenants.json", tenants)
                        break

    # Validate inputs
    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{26}$", tenant_id):
        _log(None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed tenant_id")

    if not isinstance(folder_freshdesk_id, int) or folder_freshdesk_id < 1:
        _log(None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "folder_freshdesk_id must be an integer >= 1")

    if not isinstance(title, str) or not title.strip():
        _log(None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title is required")

    if not isinstance(content_html, str) or not content_html.strip():
        _log(None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "content_html is required")

    allowed_status = {"active", "draft", "archived"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status")
    else:
        status = "draft"

    tenants = _load("tenants.json")
    if not isinstance(tenants, list):
        tenants = []
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row or tenant_row.get("status") != "active":
        _log(tenant_row, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant is not authorized or not active")

    # Ensure tenant has usable auth configured (ambient auth)
    auth_type = tenant_row.get("auth_type")
    if auth_type == "api_key":
        if tenant_row.get("api_key_ciphertext") in (None, ""):
            _log(tenant_row, 401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tenant does not have an API key configured")
    elif auth_type == "oauth":
        if tenant_row.get("oauth_access_token_ciphertext") in (None, ""):
            _log(tenant_row, 401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tenant does not have an OAuth access token configured")
    else:
        _log(tenant_row, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant does not have a supported auth configuration")

    # Rate limit per tenant (per minute)
    rate_limit = tenant_row.get("rate_limit_per_minute")
    if isinstance(rate_limit, int) and rate_limit > 0:
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        window_start = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_id:
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.replace(tzinfo=None) >= window_start:
                count += 1
        if count >= rate_limit:
            _log(tenant_row, 429, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded")

    # Create locally staged record first (freshdesk_id=null)
    def _ulid_like(prefix):
        # Crockford base32 26 chars (not full ULID spec, but matches pattern)
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(26))

    kb = _load("knowledge_and_templates.json")
    if not isinstance(kb, list):
        kb = []

    # Validate folder exists in cache (best-effort) and not deleted
    folder_row = None
    for r in kb:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") == tenant_id and r.get("record_type") == "canned_folder" and r.get("freshdesk_id") == folder_freshdesk_id:
            folder_row = r
            break
    if folder_row and folder_row.get("status") == "deleted":
        _log(tenant_row, 409, "CONFLICT")
        return _err("CONFLICT", "Target folder is deleted in cache")

    request_payload = {
        "folder_freshdesk_id": folder_freshdesk_id,
        "title": title,
        "content_html": content_html,
        "status": status,
    }

    new_id = _ulid_like("fdkb")
    while any(isinstance(r, dict) and r.get("id") == new_id for r in kb):
        new_id = _ulid_like("fdkb")

    staged = {
        "id": new_id,
        "tenant_id": tenant_id,
        "record_type": "canned_response",
        "status": status,
        "freshdesk_id": None,
        "parent_freshdesk_id": folder_freshdesk_id,
        "name": title,
        "title": title,
        "content_html": content_html,
        "raw": {"request": request_payload},
        "search_text": f"{title}\n{content_html}",
        "last_synced_at": None,
        "created_at": now,
        "updated_at": now,
    }
    kb.append(staged)
    _save("knowledge_and_templates.json", kb)

    # Simulate upstream Freshdesk creation success by allocating a new freshdesk_id not used in cache
    used = set()
    for r in kb:
        if isinstance(r, dict) and r.get("tenant_id") == tenant_id and r.get("record_type") == "canned_response":
            fid = r.get("freshdesk_id")
            if isinstance(fid, int) and fid > 0:
                used.add(fid)
    new_freshdesk_id = 1
    if used:
        new_freshdesk_id = max(used) + 1

    # Enforce unique(tenant_id, record_type, freshdesk_id) where not null
    if new_freshdesk_id in used:
        _log(tenant_row, 409, "CONFLICT")
        return _err("CONFLICT", "Freshdesk id collision")

    upstream_obj = {
        "id": new_freshdesk_id,
        "folder_id": folder_freshdesk_id,
        "title": title,
        "content": content_html,
        "status": status,
        "updated_at": now,
        "created_at": now,
    }

    # Write-through: update the staged row with freshdesk_id, raw, last_synced_at, updated_at
    kb2 = _load("knowledge_and_templates.json")
    if not isinstance(kb2, list):
        kb2 = []

    updated = None
    for i, r in enumerate(kb2):
        if not isinstance(r, dict):
            continue
        if r.get("id") == new_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "canned_response":
            r["freshdesk_id"] = new_freshdesk_id
            r["raw"] = upstream_obj
            r["last_synced_at"] = now
            r["updated_at"] = now
            # Maintain denormalized fields
            r["title"] = title
            r["name"] = title
            r["content_html"] = content_html
            r["parent_freshdesk_id"] = folder_freshdesk_id
            r["search_text"] = f"{title}\n{content_html}"
            kb2[i] = r
            updated = r
            break

    if updated is None:
        _log(tenant_row, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Staged canned response not found to finalize")

    _save("knowledge_and_templates.json", kb2)

    _log(tenant_row, 201)
    return {"data": updated}

def update_canned_response(tenant_id, canned_response_id=None, freshdesk_id=None, folder_freshdesk_id=None, title=None, content_html=None, status=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_canned_response"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status_code, tenant_row=None, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
                "credential_type": (tenant_row.get("auth_type") if isinstance(tenant_row, dict) else None),
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now_iso(),
                **({"error": error} if error is not None else {}),
                **({"meta": meta} if meta is not None else {}),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _tenant_has_creds(t):
        if not isinstance(t, dict):
            return False
        if t.get("status") != "active":
            return False
        at = t.get("auth_type")
        if at == "api_key":
            return bool(t.get("api_key_ciphertext"))
        if at == "oauth":
            return bool(t.get("oauth_access_token_ciphertext"))
        return False

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _enforce_rate_limit(tenant_row):
        rpm = tenant_row.get("rate_limit_per_minute")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= cutoff:
                count += 1
        if count >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=rpm)
        return None

    try:
        if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
            e = _err("VALIDATION_ERROR", "tenant_id is malformed.", field="tenant_id")
            _append_log("error", error=e["error"])
            return e

        if canned_response_id is None and freshdesk_id is None:
            e = _err("VALIDATION_ERROR", "Either canned_response_id or freshdesk_id must be provided.")
            _append_log("error", error=e["error"])
            return e

        # Relax local id validation: accept any non-empty string; some callers pass tenant id mistakenly.
        if canned_response_id is not None and (not isinstance(canned_response_id, str) or not canned_response_id.strip()):
            e = _err("VALIDATION_ERROR", "canned_response_id must be a non-empty string.", field="canned_response_id")
            _append_log("error", error=e["error"])
            return e
        if freshdesk_id is not None and (not isinstance(freshdesk_id, int) or isinstance(freshdesk_id, bool) or freshdesk_id < 1):
            e = _err("VALIDATION_ERROR", "freshdesk_id must be a positive integer.", field="freshdesk_id")
            _append_log("error", error=e["error"])
            return e

        if folder_freshdesk_id is not None and (not isinstance(folder_freshdesk_id, int) or isinstance(folder_freshdesk_id, bool) or folder_freshdesk_id < 1):
            e = _err("VALIDATION_ERROR", "folder_freshdesk_id must be a positive integer.", field="folder_freshdesk_id")
            _append_log("error", error=e["error"])
            return e
        if title is not None and (not isinstance(title, str) or not title.strip()):
            e = _err("VALIDATION_ERROR", "title must be a non-empty string.", field="title")
            _append_log("error", error=e["error"])
            return e
        if content_html is not None and (not isinstance(content_html, str) or not content_html.strip()):
            e = _err("VALIDATION_ERROR", "content_html must be a non-empty string.", field="content_html")
            _append_log("error", error=e["error"])
            return e
        if status is not None and status not in ("active", "draft", "archived", "deleted"):
            e = _err("VALIDATION_ERROR", "status must be one of: active, draft, archived, deleted.", field="status")
            _append_log("error", error=e["error"])
            return e

        if all(v is None for v in (folder_freshdesk_id, title, content_html, status)):
            e = _err("VALIDATION_ERROR", "At least one updatable field must be provided.")
            _append_log("error", error=e["error"])
            return e

        tenants = _load("tenants.json")
        if not isinstance(tenants, list):
            tenants = []
        tenant_row = None
        for t in tenants:
            if isinstance(t, dict) and t.get("id") == tenant_id and t.get("status") != "deleted":
                tenant_row = t
                break
        if tenant_row is None:
            e = _err("NOT_FOUND", "Tenant not found.")
            _append_log("error", error=e["error"])
            return e
        if not _tenant_has_creds(tenant_row):
            e = _err("UNAUTHORIZED", "Tenant Freshdesk credentials are missing/invalid.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        rl = _enforce_rate_limit(tenant_row)
        if rl:
            _append_log("error", tenant_row=tenant_row, error=rl["error"])
            return rl

        kb = _load("knowledge_and_templates.json")
        if not isinstance(kb, list):
            kb = []

        idx = None
        for i, r in enumerate(kb):
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_id:
                continue
            if r.get("record_type") != "canned_response":
                continue
            if canned_response_id is not None and r.get("id") == canned_response_id:
                idx = i
                break
            if canned_response_id is None and freshdesk_id is not None and r.get("freshdesk_id") == freshdesk_id:
                idx = i
                break

        if idx is None:
            e = _err("NOT_FOUND", "Canned response not found for this tenant.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        row = kb[idx]

        # Cannot update upstream object that does not exist
        if row.get("freshdesk_id") is None:
            e = _err("INVALID_TRANSITION", "Cannot update canned response because it has not been created in Freshdesk yet (freshdesk_id is null).")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        # Enforce lifecycle transitions if status change
        if status is not None:
            cur = row.get("status")
            allowed = {
                "draft": ["active", "archived", "deleted"],
                "active": ["archived", "deleted"],
                "archived": ["active", "deleted"],
                "deleted": [],
            }
            if cur not in allowed or status not in allowed.get(cur, []):
                e = _err("INVALID_TRANSITION", f"Cannot transition canned_response status from '{cur}' to '{status}'.", from_status=cur, to_status=status)
                _append_log("error", tenant_row=tenant_row, error=e["error"])
                return e

        now = _now_iso()

        if folder_freshdesk_id is not None:
            row["parent_freshdesk_id"] = folder_freshdesk_id
        if title is not None:
            row["name"] = title
        if content_html is not None:
            row["content_html"] = content_html
        if status is not None:
            row["status"] = status

        raw = row.get("raw")
        if not isinstance(raw, dict):
            raw = {}
        if folder_freshdesk_id is not None:
            raw["canned_response_folder_id"] = folder_freshdesk_id
            raw["folder_id"] = folder_freshdesk_id
        if title is not None:
            raw["title"] = title
            raw["name"] = title
        if content_html is not None:
            raw["content"] = content_html
            raw["content_html"] = content_html
        if status is not None:
            raw["status"] = status
        row["raw"] = raw

        # Update search_text
        st_parts = []
        if isinstance(row.get("name"), str):
            st_parts.append(row["name"])
        if isinstance(row.get("content_html"), str):
            st_parts.append(row["content_html"])
        row["search_text"] = " ".join([p for p in st_parts if p])

        row["updated_at"] = now
        row["last_synced_at"] = now
        kb[idx] = row
        _save("knowledge_and_templates.json", kb)

        _append_log("ok", tenant_row=tenant_row, meta={"updated": True})
        return {"canned_response": row}
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(ex))
        _append_log("error", error=e["error"])
        return e

def create_canned_response_folder(tenant_id, name, status=None, **_extra):
    import json, os, datetime, re, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, tenant_row=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{now}|create_canned_response_folder|{latency_ms}|{len(logs)}".encode("utf-8")).hexdigest()[:24],
            "endpoint": "create_canned_response_folder",
            "tenant_id": tenant_id,
            "credential_id": (tenant_row or {}).get("id"),
            "status": status_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _valid_ulid(prefix, s):
        if not isinstance(s, str): return False
        return re.match(rf"^{re.escape(prefix)}[0-9A-HJKMNP-TV-Z]{{26}}$", s) is not None

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        # best-effort ULID-ish 26 chars
        r = random.SystemRandom()
        return prefix + "".join(r.choice(_CROCK) for _ in range(26))

    def _tenant_and_auth():
        tenants = _load("tenants.json")
        if not isinstance(tenants, list):
            return None, _err("UNAUTHORIZED", "Tenant store unavailable")
        trow = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
        if not trow or trow.get("status") != "active":
            return None, _err("UNAUTHORIZED", "Tenant is unknown or not active")
        auth_type = trow.get("auth_type")
        if auth_type == "api_key":
            if not trow.get("api_key_ciphertext"):
                return None, _err("UNAUTHORIZED", "Tenant has no valid Freshdesk credentials")
        elif auth_type == "oauth":
            if not trow.get("oauth_access_token_ciphertext"):
                return None, _err("UNAUTHORIZED", "Tenant has no valid Freshdesk credentials")
        else:
            return None, _err("UNAUTHORIZED", "Tenant has no valid Freshdesk credentials")
        return trow, None

    # Validate inputs
    if not _valid_ulid("fdten_", tenant_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid tenant_id format")

    if not isinstance(name, str) or not name.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    name = name.strip()

    allowed_status = {"active", "draft", "archived"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, draft, archived")
    else:
        status = "active"

    trow, terr = _tenant_and_auth()
    if terr:
        _log(terr["error"]["code"])
        return terr

    # Internal permission model not present in datastore; treat as allowed when authenticated.
    # Create local row first with freshdesk_id=null and raw=request payload
    kb = _load("knowledge_and_templates.json")
    if not isinstance(kb, list):
        _log("CONFLICT", trow)
        return _err("CONFLICT", "Knowledge store unavailable")

    # Generate unique local id
    for _ in range(10):
        new_id = _new_id("fdkb_")
        if not any(isinstance(r, dict) and r.get("id") == new_id for r in kb):
            break
    else:
        _log("CONFLICT", trow)
        return _err("CONFLICT", "Could not allocate id")

    row = {
        "id": new_id,
        "tenant_id": tenant_id,
        "record_type": "canned_folder",
        "status": status,
        "freshdesk_id": None,
        "parent_freshdesk_id": None,
        "name": name,
        "title": None,
        "content_html": None,
        "raw": {"name": name, "status": status, "request_payload": {"name": name, "status": status}},
        "search_text": name[:20000],
        "last_synced_at": None,
        "created_at": now,
        "updated_at": now
    }
    kb.append(row)
    _save("knowledge_and_templates.json", kb)

    # Simulate upstream success: assign a deterministic freshdesk_id if possible
    kb2 = _load("knowledge_and_templates.json")
    if not isinstance(kb2, list):
        _log("CONFLICT", trow)
        return _err("CONFLICT", "Knowledge store unavailable after create")
    target = next((r for r in kb2 if isinstance(r, dict) and r.get("id") == new_id), None)
    if not target:
        _log("NOT_FOUND", trow)
        return _err("NOT_FOUND", "Created folder not found")

    used_ids = set()
    for r in kb2:
        if isinstance(r, dict) and r.get("tenant_id") == tenant_id and r.get("record_type") == "canned_folder":
            fid = r.get("freshdesk_id")
            if isinstance(fid, int) and fid > 0:
                used_ids.add(fid)
    # pick next integer id
    next_fid = 1
    if used_ids:
        next_fid = max(used_ids) + 1

    # Enforce unique(tenant_id, record_type, freshdesk_id) where not null
    if next_fid in used_ids:
        _log("CONFLICT", trow)
        return _err("CONFLICT", "Upstream id collision")

    target["freshdesk_id"] = next_fid
    target["raw"] = {
        "id": next_fid,
        "name": name,
        "status": status,
        "created_via": "create_canned_response_folder"
    }
    target["last_synced_at"] = now
    target["updated_at"] = now

    _save("knowledge_and_templates.json", kb2)

    _log("OK", trow)
    return {"canned_response_folder": target}

def update_canned_response_folder(tenant_id, canned_response_folder_id=None, freshdesk_id=None, name=None, status=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_canned_response_folder"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status_code, tenant_row=None, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
                "credential_type": (tenant_row.get("auth_type") if isinstance(tenant_row, dict) else None),
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now_iso(),
                **({"error": error} if error is not None else {}),
                **({"meta": meta} if meta is not None else {}),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _tenant_has_creds(t):
        if not isinstance(t, dict):
            return False
        if t.get("status") != "active":
            return False
        at = t.get("auth_type")
        if at == "api_key":
            return bool(t.get("api_key_ciphertext"))
        if at == "oauth":
            return bool(t.get("oauth_access_token_ciphertext"))
        return False

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _enforce_rate_limit(tenant_row):
        rpm = tenant_row.get("rate_limit_per_minute")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= cutoff:
                count += 1
        if count >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=rpm)
        return None

    try:
        if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
            e = _err("VALIDATION_ERROR", "tenant_id is malformed.", field="tenant_id")
            _append_log("error", error=e["error"])
            return e

        if canned_response_folder_id is None and freshdesk_id is None:
            e = _err("VALIDATION_ERROR", "Either canned_response_folder_id or freshdesk_id must be provided.")
            _append_log("error", error=e["error"])
            return e

        if canned_response_folder_id is not None and (not isinstance(canned_response_folder_id, str) or not canned_response_folder_id.strip()):
            e = _err("VALIDATION_ERROR", "canned_response_folder_id must be a non-empty string.", field="canned_response_folder_id")
            _append_log("error", error=e["error"])
            return e
        if freshdesk_id is not None and (not isinstance(freshdesk_id, int) or isinstance(freshdesk_id, bool) or freshdesk_id < 1):
            e = _err("VALIDATION_ERROR", "freshdesk_id must be a positive integer.", field="freshdesk_id")
            _append_log("error", error=e["error"])
            return e
        if name is not None and (not isinstance(name, str) or not name.strip()):
            e = _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
            _append_log("error", error=e["error"])
            return e
        if status is not None and status not in ("active", "draft", "archived", "deleted"):
            e = _err("VALIDATION_ERROR", "status must be one of: active, draft, archived, deleted.", field="status")
            _append_log("error", error=e["error"])
            return e

        if name is None and status is None:
            e = _err("VALIDATION_ERROR", "At least one updatable field must be provided.")
            _append_log("error", error=e["error"])
            return e

        tenants = _load("tenants.json")
        if not isinstance(tenants, list):
            tenants = []
        tenant_row = None
        for t in tenants:
            if isinstance(t, dict) and t.get("id") == tenant_id and t.get("status") != "deleted":
                tenant_row = t
                break
        if tenant_row is None:
            e = _err("NOT_FOUND", "Tenant not found.")
            _append_log("error", error=e["error"])
            return e
        if not _tenant_has_creds(tenant_row):
            e = _err("UNAUTHORIZED", "Tenant Freshdesk credentials are missing/invalid.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        rl = _enforce_rate_limit(tenant_row)
        if rl:
            _append_log("error", tenant_row=tenant_row, error=rl["error"])
            return rl

        kb = _load("knowledge_and_templates.json")
        if not isinstance(kb, list):
            kb = []

        idx = None
        for i, r in enumerate(kb):
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_id:
                continue
            if r.get("record_type") != "canned_folder":
                continue
            if canned_response_folder_id is not None and r.get("id") == canned_response_folder_id:
                idx = i
                break
            if canned_response_folder_id is None and freshdesk_id is not None and r.get("freshdesk_id") == freshdesk_id:
                idx = i
                break

        if idx is None:
            e = _err("NOT_FOUND", "Canned response folder not found for this tenant.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        row = kb[idx]
        if row.get("freshdesk_id") is None:
            e = _err("INVALID_TRANSITION", "Cannot update canned response folder because it has not been created in Freshdesk yet (freshdesk_id is null).")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        if status is not None:
            cur = row.get("status")
            allowed = {
                "draft": ["active", "archived", "deleted"],
                "active": ["archived", "deleted"],
                "archived": ["active", "deleted"],
                "deleted": [],
            }
            if cur not in allowed or status not in allowed.get(cur, []):
                e = _err("INVALID_TRANSITION", f"Cannot transition canned_folder status from '{cur}' to '{status}'.", from_status=cur, to_status=status)
                _append_log("error", tenant_row=tenant_row, error=e["error"])
                return e

        now = _now_iso()
        if name is not None:
            row["name"] = name
        if status is not None:
            row["status"] = status

        raw = row.get("raw")
        if not isinstance(raw, dict):
            raw = {}
        if name is not None:
            raw["name"] = name
        if status is not None:
            raw["status"] = status
        row["raw"] = raw

        row["search_text"] = " ".join([p for p in [(row.get("name") if isinstance(row.get("name"), str) else None)] if p])

        row["updated_at"] = now
        row["last_synced_at"] = now

        kb[idx] = row
        _save("knowledge_and_templates.json", kb)

        _append_log("ok", tenant_row=tenant_row, meta={"updated": True})
        return {"canned_response_folder": row}
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(ex))
        _append_log("error", error=e["error"])
        return e

