            if cat != category_freshdesk_id:
                continue

        if qn:
            st = r.get("search_text")
            ok = False
            if isinstance(st, str) and qn in st.lower():
                ok = True
            else:
                raw = r.get("raw")
                if isinstance(raw, dict):
                    try:
                        raw_s = json.dumps(raw, ensure_ascii=False).lower()
                        if qn in raw_s:
                            ok = True
                    except Exception:
                        ok = False
            if not ok:
                continue

        rows.append(r)

    total = len(rows)

    # Sort
    def _key(r):
        if sort in ("updated_at", "created_at"):
            dt = _parse_dt(r.get(sort))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if sort == "freshdesk_id":
            v = r.get("freshdesk_id")
            return v if isinstance(v, int) else -1
        if sort == "title":
            v = r.get("title")
            if v is None and isinstance(r.get("raw"), dict):
                v = r["raw"].get("title")
            return (v or "").lower()
        return 0

    reverse = (order == "desc")
    try:
        rows.sort(key=_key, reverse=reverse)
    except Exception:
        _log("CONFLICT", trow)
        return _err("CONFLICT", "Failed to sort results")

    # Paginate
    page = rows[offset:offset + limit]
    next_off = offset + limit
    has_more = next_off < total
    next_cursor = None
    if has_more:
        payload = f"off:{next_off}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    _log("OK", trow)
    return {
        "solution_articles": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order
        }
    }

def list_solution_folders(tenant_id, category_id, per_page=None, page=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def _ulid_like(s):
        return isinstance(s, str) and re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{10,}$", s or "") is not None

    def _gen_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # 48-bit ms timestamp (10 chars base32) + 16 chars randomness
        ms = int(time.time() * 1000)
        ts = []
        for _ in range(10):
            ts.append(alphabet[ms & 31])
            ms >>= 5
        ts = "".join(reversed(ts))
        rnd = "".join(random.choice(alphabet) for _ in range(16))
        return f"{prefix}_{ts}{rnd}"

    def _log_call(tenant_row, endpoint, status, latency_ms, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_ulid("fdlog"),
            "timestamp": _now(),
            "tenant_id": tenant_row["id"] if tenant_row else tenant_id,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limited(tenant_row):
        # rate_limit_per_minute enforced per tenant via request_logs.json, last 60s
        rl = tenant_row.get("rate_limit_per_minute")
        if not _is_int(rl) or rl < 1:
            return False, None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = r.get("timestamp")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")) if isinstance(ts, str) else None
            except Exception:
                dt = None
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= rl:
            return True, rl
        return False, rl

    t0 = time.time()

    # Validate inputs
    if not _ulid_like(tenant_id):
        return _err("VALIDATION_ERROR", "Invalid tenant_id format.")
    if not _is_int(category_id) or category_id <= 0:
        return _err("VALIDATION_ERROR", "category_id must be a positive integer.")
    if per_page is None:
        per_page = None
    else:
        if not _is_int(per_page) or per_page < 1 or per_page > 100:
            return _err("VALIDATION_ERROR", "per_page must be an integer between 1 and 100.")
    if page is None:
        page = 1
    if not _is_int(page) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row or tenant_row.get("status") != "active":
        # Map failures to UNAUTHORIZED as we cannot resolve a usable tenant context
        return _err("UNAUTHORIZED", "No active tenant context available for this request.")

    # Check credentials presence (plaintext not available; only presence indicates configured)
    auth_type = tenant_row.get("auth_type")
    has_creds = False
    if auth_type == "api_key":
        has_creds = tenant_row.get("api_key_ciphertext") is not None
    elif auth_type == "oauth":
        has_creds = tenant_row.get("oauth_access_token_ciphertext") is not None
    else:
        has_creds = False
    if not has_creds:
        return _err("UNAUTHORIZED", "Tenant has no valid Freshdesk credentials configured.")

    limited, rl = _rate_limited(tenant_row)
    if limited:
        latency_ms = (time.time() - t0) * 1000
        _log_call(tenant_row, "list_solution_folders", "RATE_LIMIT", latency_ms, detail={"rate_limit_per_minute": rl})
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_per_minute=rl)

    # Determine effective per_page
    if per_page is None:
        dps = tenant_row.get("default_page_size")
        if not _is_int(dps) or dps < 1 or dps > 100:
            dps = 30
        per_page = dps

    # Read cached folders for this category
    kat = _load("knowledge_and_templates.json")
    if not isinstance(kat, list):
        kat = []
    rows = [
        r for r in kat
        if isinstance(r, dict)
        and r.get("tenant_id") == tenant_id
        and r.get("record_type") == "solution_folder"
        and r.get("status") != "deleted"
        and r.get("parent_freshdesk_id") == category_id
    ]

    # Stable ordering: by freshdesk_id then created_at
    def _key(r):
        fid = r.get("freshdesk_id")
        fid = fid if _is_int(fid) else 10**18
        ca = r.get("created_at") or ""
        return (fid, ca, r.get("id") or "")
    rows.sort(key=_key)

    total = len(rows)
    start = (page - 1) * per_page
    end = start + per_page
    page_rows = rows[start:end]
    has_more = end < total

    latency_ms = (time.time() - t0) * 1000
    _log_call(tenant_row, "list_solution_folders", "OK", latency_ms, detail={"page": page, "per_page": per_page})

    return {
        "folders": page_rows,
        "meta": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
        },
    }

