        latency_ms = (time.time() - t0) * 1000
        _log_call(tenant_row, "create_solution_category", "RATE_LIMIT", latency_ms, detail={"rate_limit_per_minute": rl})
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_per_minute=rl)

    kat = _load("knowledge_and_templates.json")
    if not isinstance(kat, list):
        kat = []

    # Idempotency-ish: if an active category exists with same name, return it
    # (Freshdesk doesn't guarantee uniqueness by name, but this server makes it safe for retries)
    existing = next(
        (
            r for r in kat
            if isinstance(r, dict)
            and r.get("tenant_id") == tenant_id
            and r.get("record_type") == "solution_category"
            and r.get("status") != "deleted"
            and isinstance(r.get("name"), str)
            and r.get("name").strip().lower() == name.strip().lower()
        ),
        None,
    )
    if existing is not None and existing.get("freshdesk_id") is not None:
        latency_ms = (time.time() - t0) * 1000
        _log_call(tenant_row, "create_solution_category", "OK", latency_ms, detail={"idempotent": True, "freshdesk_id": existing.get("freshdesk_id")})
        return {"category": existing, "meta": {"idempotent": True}}

    now = _now()

    # Stage local create with freshdesk_id = null and raw = request payload
    local_id = _gen_ulid("fdkat")
    request_payload = {
        "name": name.strip(),
    }
    if description is not None:
        request_payload["description"] = description
    if visible_in_portal is not None:
        request_payload["visible_in_portal"] = visible_in_portal

    staged = {
        "id": local_id,
        "tenant_id": tenant_id,
        "record_type": "solution_category",
        "status": "draft",
        "freshdesk_id": None,
        "parent_freshdesk_id": None,
        "name": name.strip(),
        "title": None,
        "content_html": None,
        "raw": {"staged_request": request_payload},
        "search_text": " ".join([name.strip(), description or ""]).strip() or None,
        "last_synced_at": None,
        "created_at": now,
        "updated_at": now,
    }
    kat.append(staged)
    _save("knowledge_and_templates.json", kat)

    # Simulate upstream success offline: assign a new numeric freshdesk_id and mark active
    new_freshdesk_id = _next_numeric_id(kat, tenant_id)
    upstream_response = {
        "id": new_freshdesk_id,
        "name": name.strip(),
        "description": description,
        "visible_in_portal": visible_in_portal if visible_in_portal is not None else True,
        "created_at": now,
        "updated_at": now,
    }

    # Ensure unique(tenant_id, record_type, freshdesk_id) where freshdesk_id not null
    conflict = next(
        (
            r for r in kat
            if isinstance(r, dict)
            and r.get("id") != local_id
            and r.get("tenant_id") == tenant_id
            and r.get("record_type") == "solution_category"
            and r.get("freshdesk_id") == new_freshdesk_id
        ),
        None,
    )
    if conflict is not None:
        # Rollback staged row by marking deleted (retain raw), since we already persisted staging
        for r in kat:
            if isinstance(r, dict) and r.get("id") == local_id:
                r["status"] = "deleted"
                r["updated_at"] = _now()
                r["last_synced_at"] = _now()
                break
        _save("knowledge_and_templates.json", kat)
        latency_ms = (time.time() - t0) * 1000
        _log_call(tenant_row, "create_solution_category", "CONFLICT", latency_ms, detail={"freshdesk_id": new_freshdesk_id})
        return _err("CONFLICT", "Conflict creating solution category (duplicate freshdesk_id).", freshdesk_id=new_freshdesk_id)

    # Update staged row with upstream response
    updated = None
    for r in kat:
        if isinstance(r, dict) and r.get("id") == local_id:
            r["freshdesk_id"] = new_freshdesk_id
            r["status"] = "active"
            r["raw"] = upstream_response
            r["last_synced_at"] = now
            r["updated_at"] = now
            # search_text refresh
            r["search_text"] = " ".join([name.strip(), description or ""]).strip() or None
            updated = r
            break

    if updated is None:
        latency_ms = (time.time() - t0) * 1000
        _log_call(tenant_row, "create_solution_category", "NOT_FOUND", latency_ms)
        return _err("NOT_FOUND", "Staged category row not found during finalize.")

    _save("knowledge_and_templates.json", kat)

    latency_ms = (time.time() - t0) * 1000
    _log_call(tenant_row, "create_solution_category", "OK", latency_ms, detail={"freshdesk_id": new_freshdesk_id})
    return {"category": updated}

def update_solution_category(tenant_id, category_id, name=None, description=None, visible_in_portal=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(18))

    def _log(endpoint, tenant_id_val, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("fdreq"),
            "endpoint": endpoint,
            "tenant_id": tenant_id_val,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    start = time.time()
    endpoint = "update_solution_category"

    try:
        if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
            out = _err("VALIDATION_ERROR", "tenant_id is invalid.", field="tenant_id")
            _log(endpoint, tenant_id if isinstance(tenant_id, str) else None, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out
        if not _is_int(category_id) or category_id <= 0:
            out = _err("VALIDATION_ERROR", "category_id must be a positive integer.", field="category_id")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out
        if name is None and description is None and visible_in_portal is None:
            out = _err("VALIDATION_ERROR", "At least one of name, description, visible_in_portal must be provided.")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out
        if name is not None and not isinstance(name, str):
            out = _err("VALIDATION_ERROR", "name must be a string.", field="name")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out
        if description is not None and not isinstance(description, str):
            out = _err("VALIDATION_ERROR", "description must be a string.", field="description")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out
        if visible_in_portal is not None and not isinstance(visible_in_portal, bool):
            out = _err("VALIDATION_ERROR", "visible_in_portal must be a boolean.", field="visible_in_portal")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        tenants = _load("tenants.json")
        tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
        if not tenant or tenant.get("status") != "active":
            out = _err("UNAUTHORIZED", "No active tenant context available for this request.")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        # Credential prerequisite: must have required ciphertext present for the auth_type and not deleted
        auth_type = tenant.get("auth_type")
        has_creds = False
        if auth_type == "api_key":
            has_creds = bool(tenant.get("api_key_ciphertext"))
        elif auth_type == "oauth":
            has_creds = bool(tenant.get("oauth_access_token_ciphertext"))
        if not has_creds:
            out = _err("UNAUTHORIZED", "Tenant has no valid Freshdesk credentials configured.")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        # Rate limit per tenant per minute (internal safety)
        rate = tenant.get("rate_limit_per_minute")
        if not isinstance(rate, int) or rate < 1:
            rate = 60
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                recent += 1
        if recent >= rate:
            out = _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rate)
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        # Find existing cached solution_category
        kat = _load("knowledge_and_templates.json")
        if not isinstance(kat, list):
            kat = []
        rec = None
        for row in kat:
            if not isinstance(row, dict):
                continue
            if row.get("tenant_id") != tenant_id:
                continue
            if row.get("record_type") != "solution_category":
                continue
            if row.get("freshdesk_id") == category_id:
                rec = row
                break

        if not rec or rec.get("status") == "deleted":
            out = _err("NOT_FOUND", "Solution category not found.", category_id=category_id)
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        # Enforce lifecycle transitions if status change is attempted (not in this tool). So just update fields.
        now_iso = _now_iso()
        if not isinstance(rec.get("raw"), dict):
            rec["raw"] = {}

        if name is not None:
            rec["name"] = name
            rec["raw"]["name"] = name
        if description is not None:
            # category description is commonly in raw as "description"
            rec["raw"]["description"] = description
        if visible_in_portal is not None:
            rec["raw"]["visible_in_portal"] = visible_in_portal

        # Update denormalized search_text
        parts = []
        if isinstance(rec.get("name"), str):
            parts.append(rec["name"])
        if isinstance(rec.get("title"), str):
            parts.append(rec["title"])
        if isinstance(rec["raw"].get("description"), str):
            parts.append(rec["raw"]["description"])
        rec["search_text"] = " ".join(parts).strip() if parts else rec.get("search_text")

        rec["updated_at"] = now_iso
        rec["last_synced_at"] = now_iso

        _save("knowledge_and_templates.json", kat)

        out = {"category": rec}
        _log(endpoint, tenant_id, "ok", (time.time() - start) * 1000)
        return out
    except Exception as e:
        out = _err("CONFLICT", "Unexpected error.", detail=str(e))
        _log(endpoint, tenant_id if isinstance(tenant_id, str) else None, "error", (time.time() - start) * 1000, out["error"]["code"])
        return out

