            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                recent += 1
        if recent >= rate:
            out = _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rate)
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        kat = _load("knowledge_and_templates.json")
        if not isinstance(kat, list):
            kat = []

        # Ensure category exists and active-ish
        cat = None
        for row in kat:
            if not isinstance(row, dict):
                continue
            if row.get("tenant_id") != tenant_id:
                continue
            if row.get("record_type") != "solution_category":
                continue
            if row.get("freshdesk_id") == category_id and row.get("status") != "deleted":
                cat = row
                break
        if not cat:
            out = _err("NOT_FOUND", "Solution category not found.", category_id=category_id)
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

