        now_iso = _now_iso()
        staged_raw = {
            "name": name,
            "description": description,
            "visibility": visibility,
            "category_id": category_id,
        }
        # Simulate upstream success by assigning a new unique freshdesk_id (offline server)
        used_ids = set()
        for row in kat:
            if isinstance(row, dict) and row.get("tenant_id") == tenant_id and row.get("record_type") == "solution_folder":
                fid = row.get("freshdesk_id")
                if isinstance(fid, int):
                    used_ids.add(fid)
        new_freshdesk_id = 1
        while new_freshdesk_id in used_ids:
            new_freshdesk_id += 1

        upstream_raw = dict(staged_raw)
        upstream_raw["id"] = new_freshdesk_id

        folder_row = {
            "id": _gen_id("fdkat"),
            "tenant_id": tenant_id,
            "record_type": "solution_folder",
            "status": "active",
            "freshdesk_id": new_freshdesk_id,
            "parent_freshdesk_id": category_id,  # folder->category
            "name": name,
            "title": None,
            "content_html": None,
            "raw": upstream_raw,
            "search_text": " ".join([p for p in [name, description] if isinstance(p, str) and p.strip()]).strip() or None,
            "last_synced_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }

        # Enforce unique(tenant_id, record_type, freshdesk_id) where not null
        for row in kat:
            if not isinstance(row, dict):
                continue
            if row.get("tenant_id") == tenant_id and row.get("record_type") == "solution_folder" and row.get("freshdesk_id") == folder_row["freshdesk_id"]:
                out = _err("CONFLICT", "A solution folder with this Freshdesk id already exists in cache.")
                _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
                return out

        kat.append(folder_row)
        _save("knowledge_and_templates.json", kat)

        out = {"folder": folder_row}
        _log(endpoint, tenant_id, "ok", (time.time() - start) * 1000)
        return out
    except Exception as e:
        out = _err("CONFLICT", "Unexpected error.", detail=str(e))
        _log(endpoint, tenant_id if isinstance(tenant_id, str) else None, "error", (time.time() - start) * 1000, out["error"]["code"])
        return out

