            if r.get("tenant_id") != tenant_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                recent += 1
        if recent >= rate:
            out = _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rate)
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        kat = _load("knowledge_and_templates.json")
        if not isinstance(kat, list):
            kat = []

        # Require category exists
        cat = None
        for row in kat:
            if not isinstance(row, dict):
                continue
            if row.get("tenant_id") == tenant_id and row.get("record_type") == "solution_category" and row.get("freshdesk_id") == category_id and row.get("status") != "deleted":
                cat = row
                break
        if not cat:
            out = _err("NOT_FOUND", "Solution category not found.", category_id=category_id)
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        # Cached folder lookup
        folder = None
        for row in kat:
            if not isinstance(row, dict):
                continue
            if row.get("tenant_id") != tenant_id or row.get("record_type") != "solution_folder":
                continue
            if row.get("freshdesk_id") == folder_id and row.get("status") != "deleted":
                # verify scoped to category
                if row.get("parent_freshdesk_id") == category_id or (isinstance(row.get("raw"), dict) and row["raw"].get("category_id") == category_id):
                    folder = row
                    break

        if folder:
            out = {"folder": folder}
            _log(endpoint, tenant_id, "ok", (time.time() - start) * 1000)
            return out

        # Not cached: simulate upstream fetch+upsert (offline). If not found, return NOT_FOUND.
        out = _err("NOT_FOUND", "Solution folder not found.", category_id=category_id, folder_id=folder_id)
        _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
        return out
    except Exception as e:
        out = _err("CONFLICT", "Unexpected error.", detail=str(e))
        _log(endpoint, tenant_id if isinstance(tenant_id, str) else None, "error", (time.time() - start) * 1000, out["error"]["code"])
        return out

def update_solution_category_folder(tenant_id, category_id, folder_id, name=None, description=None, visibility=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(18))

    def _log(endpoint, tenant_id_val, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("fdreq"),
            "endpoint": endpoint,
            "tenant_id": tenant_id_val,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    start = time.time()
    endpoint = "update_solution_category_folder"

    try:
        if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
            out = _err("VALIDATION_ERROR", "tenant_id is invalid.", field="tenant_id")
            _log(endpoint, tenant_id if isinstance(tenant_id, str) else None, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out
        if not _is_int(category_id) or category_id <= 0:
            out = _err("VALIDATION_ERROR", "category_id must be a positive integer.", field="category_id")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out
        if not _is_int(folder_id) or folder_id <= 0:
            out = _err("VALIDATION_ERROR", "folder_id must be a positive integer.", field="folder_id")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out
        if name is None and description is None and visibility is None:
            out = _err("VALIDATION_ERROR", "At least one of name, description, visibility must be provided.")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out
        if name is not None and (not isinstance(name, str) or not name.strip()):
            out = _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out
        if description is not None and not isinstance(description, str):
            out = _err("VALIDATION_ERROR", "description must be a string.", field="description")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out
        if visibility is not None and not _is_int(visibility):
            out = _err("VALIDATION_ERROR", "visibility must be an integer.", field="visibility")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        tenants = _load("tenants.json")
        tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
        if not tenant or tenant.get("status") != "active":
            out = _err("UNAUTHORIZED", "No active tenant context available for this request.")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        auth_type = tenant.get("auth_type")
        has_creds = False
        if auth_type == "api_key":
            has_creds = bool(tenant.get("api_key_ciphertext"))
        elif auth_type == "oauth":
            has_creds = bool(tenant.get("oauth_access_token_ciphertext"))
        if not has_creds:
            out = _err("UNAUTHORIZED", "Tenant has no valid Freshdesk credentials configured.")
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        rate = tenant.get("rate_limit_per_minute")
        if not isinstance(rate, int) or rate < 1:
            rate = 60
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                recent += 1
        if recent >= rate:
            out = _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rate)
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        kat = _load("knowledge_and_templates.json")
        if not isinstance(kat, list):
            kat = []

        # Category must exist (and not deleted)
        cat = None
        for row in kat:
            if not isinstance(row, dict):
                continue
            if row.get("tenant_id") == tenant_id and row.get("record_type") == "solution_category" and row.get("freshdesk_id") == category_id and row.get("status") != "deleted":
                cat = row
                break
        if not cat:
            out = _err("NOT_FOUND", "Solution category not found.", category_id=category_id)
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        # Folder must exist under the category and be updatable (freshdesk_id non-null is guaranteed by folder_id input)
        folder = None
        for row in kat:
            if not isinstance(row, dict):
                continue
            if row.get("tenant_id") != tenant_id or row.get("record_type") != "solution_folder":
                continue
            if row.get("freshdesk_id") != folder_id:
                continue
            if row.get("status") == "deleted":
                continue
            # enforce scoping
            if row.get("parent_freshdesk_id") != category_id and not (isinstance(row.get("raw"), dict) and row["raw"].get("category_id") == category_id):
                continue
            folder = row
            break

        if not folder:
            out = _err("NOT_FOUND", "Solution folder not found under the specified category.", category_id=category_id, folder_id=folder_id)
            _log(endpoint, tenant_id, "error", (time.time() - start) * 1000, out["error"]["code"])
            return out

        # Update (and refresh raw/last_synced_at)
        now_iso = _now_iso()
        if not isinstance(folder.get("raw"), dict):
            folder["raw"] = {}
        folder["raw"]["id"] = folder_id
        folder["raw"]["category_id"] = category_id

        if name is not None:
            folder["name"] = name
            folder["raw"]["name"] = name
        if description is not None:
            folder["raw"]["description"] = description
        if visibility is not None:
            folder["raw"]["visibility"] = visibility

        # Search text update
        parts = []
        if isinstance(folder.get("name"), str):
            parts.append(folder["name"])
        if isinstance(folder["raw"].get("description"), str):
            parts.append(folder["raw"]["description"])
        folder["search_text"] = " ".join([p for p in parts if p and isinstance(p, str)]).strip() or folder.get("search_text")

        folder["updated_at"] = now_iso
        folder["last_synced_at"] = now_iso

        _save("knowledge_and_templates.json", kat)

        out = {"folder": folder}
        _log(endpoint, tenant_id, "ok", (time.time() - start) * 1000)
        return out
    except Exception as e:
        out = _err("CONFLICT", "Unexpected error.", detail=str(e))
        _log(endpoint, tenant_id if isinstance(tenant_id, str) else None, "error", (time.time() - start) * 1000, out["error"]["code"])
        return out

def create_solution_article(tenant_id, solution_folder_freshdesk_id, title, description_html, status, tags=None, seo_data=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_solution_article"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status_code, tenant_row=None, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
            "credential_type": (tenant_row.get("auth_type") if isinstance(tenant_row, dict) else None),
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now(),
            **({"error": error} if error is not None else {}),
            **({"meta": meta} if meta is not None else {}),
        })
        _save("request_logs.json", logs)

    def _resolve_tenant(tenants):
        for st in ("active", "suspended"):
            for t in tenants:
                if isinstance(t, dict) and t.get("id") == tenant_id and t.get("status") == st:
                    return t
        for t in tenants:
            if isinstance(t, dict) and t.get("id") == tenant_id and t.get("status") == "deleted":
                return t
        return None

    def _tenant_has_creds(t):
        at = t.get("auth_type")
        if at == "api_key":
            return bool(t.get("api_key_ciphertext"))
        if at == "oauth":
            return bool(t.get("oauth_access_token_ciphertext"))
        return False

    def _gen_ulid_like(prefix):
        # ULID-ish, uppercase base32 without I/L/O/U; 26 chars
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # 48-bit time + 80-bit randomness -> 26 chars; we'll just do random but fixed length
        return prefix + "_" + "".join(alphabet[b % 32] for b in os.urandom(26))

    try:
        if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id) is None:
            e = _err("VALIDATION_ERROR", "tenant_id is malformed.", field="tenant_id")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(solution_folder_freshdesk_id, int) or isinstance(solution_folder_freshdesk_id, bool) or solution_folder_freshdesk_id < 1:
            e = _err("VALIDATION_ERROR", "solution_folder_freshdesk_id must be an integer >= 1.", field="solution_folder_freshdesk_id")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(title, str) or not title.strip():
            e = _err("VALIDATION_ERROR", "title is required and must be non-empty.", field="title")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(description_html, str) or not description_html.strip():
            e = _err("VALIDATION_ERROR", "description_html is required and must be non-empty.", field="description_html")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(status, int) or isinstance(status, bool) or status not in (1, 2):
            e = _err("VALIDATION_ERROR", "status must be one of {1,2}.", field="status")
            _append_log("error", error=e["error"])
            return e
        if tags is not None:
            if not isinstance(tags, list) or any((not isinstance(t, str)) for t in tags):
                e = _err("VALIDATION_ERROR", "tags must be an array of strings.", field="tags")
                _append_log("error", error=e["error"])
                return e
        if seo_data is not None and not isinstance(seo_data, dict):
            e = _err("VALIDATION_ERROR", "seo_data must be an object.", field="seo_data")
            _append_log("error", error=e["error"])
            return e

        tenants = _load("tenants.json")
        if not isinstance(tenants, list):
            tenants = []
        tenant = _resolve_tenant(tenants)
        if tenant is None or tenant.get("status") == "deleted":
            e = _err("NOT_FOUND", "Tenant not found.", tenant_id=tenant_id)
            _append_log("error", tenant_row=tenant if isinstance(tenant, dict) else None, error=e["error"])
            return e
        if not _tenant_has_creds(tenant):
            e = _err("UNAUTHORIZED", "Tenant has no valid Freshdesk credentials configured.", tenant_id=tenant_id)
            _append_log("error", tenant_row=tenant, error=e["error"])
            return e

        kat = _load("knowledge_and_templates.json")
        if not isinstance(kat, list):
            kat = []

        now = _now()

        # Create local staged row first with freshdesk_id=null and raw=request payload
        local_id = _gen_ulid_like("fdkb")
        payload = {
            "solution_folder_id": solution_folder_freshdesk_id,
            "title": title,
            "description": description_html,
            "status": status,
        }
        if tags is not None:
            payload["tags"] = tags
        if seo_data is not None:
            payload["seo_data"] = seo_data

        record_status = "draft" if status == 1 else "active"
        new_row = {
            "id": local_id,
            "tenant_id": tenant_id,
            "record_type": "solution_article",
            "status": record_status,
            "freshdesk_id": None,
            "parent_freshdesk_id": solution_folder_freshdesk_id,
            "name": None,
            "title": title,
            "content_html": description_html,
            "raw": payload,
            "search_text": " ".join([title, description_html] + (tags or []))[:20000],
            "last_synced_at": None,
            "created_at": now,
            "updated_at": now,
        }
        kat.append(new_row)
        _save("knowledge_and_templates.json", kat)

        # Offline "upstream success": assign a synthetic freshdesk_id and set last_synced_at.
        # Ensure uniqueness (tenant_id, record_type, freshdesk_id)
        max_fd = 0
        for r in kat:
            if isinstance(r, dict) and r.get("tenant_id") == tenant_id and r.get("record_type") == "solution_article":
                v = r.get("freshdesk_id")
                if isinstance(v, int) and v > max_fd:
                    max_fd = v
        assigned_fd = max_fd + 1 if max_fd > 0 else int.from_bytes(os.urandom(2), "big") + 1000

        # Re-check uniqueness
        if any(isinstance(r, dict) and r.get("tenant_id") == tenant_id and r.get("record_type") == "solution_article" and r.get("freshdesk_id") == assigned_fd for r in kat):
            assigned_fd = int.from_bytes(os.urandom(2), "big") + 2000

        upstream_obj = dict(payload)
        upstream_obj["id"] = assigned_fd

        new_row["freshdesk_id"] = assigned_fd
        new_row["raw"] = upstream_obj
        new_row["last_synced_at"] = now
        new_row["updated_at"] = now
        _save("knowledge_and_templates.json", kat)

        _append_log("success", tenant_row=tenant, meta={"id": new_row["id"], "freshdesk_id": assigned_fd})
        return {"solution_article": new_row}
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected server error.", detail=str(ex))
        _append_log("error", error=e["error"])
        return e

def view_solution_article(tenant_id, solution_article_freshdesk_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    start = time.time()
    now_ts = _now()

    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        return _err("VALIDATION_ERROR", "tenant_id is malformed.", field="tenant_id")
    if not _is_int(solution_article_freshdesk_id) or solution_article_freshdesk_id < 1:
        return _err("VALIDATION_ERROR", "solution_article_freshdesk_id must be an integer >= 1.", field="solution_article_freshdesk_id")

    tenants = _load("tenants.json")
    kat = _load("knowledge_and_templates.json")

    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant or tenant.get("status") != "active":
        return _err("UNAUTHORIZED", "Tenant not authorized or not active for Freshdesk operations.", tenant_id=tenant_id)

    auth_type = tenant.get("auth_type")
    if auth_type == "api_key":
        if not tenant.get("api_key_ciphertext"):
            return _err("UNAUTHORIZED", "Tenant Freshdesk API key is not configured.", tenant_id=tenant_id)
    elif auth_type == "oauth":
        if not tenant.get("oauth_access_token_ciphertext"):
            return _err("UNAUTHORIZED", "Tenant Freshdesk OAuth access token is not configured.", tenant_id=tenant_id)
        exp = tenant.get("oauth_token_expires_at")
        if exp:
            try:
                exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00"))
                if exp_dt <= datetime.datetime.now(datetime.timezone.utc):
                    return _err("UNAUTHORIZED", "Tenant Freshdesk OAuth access token is expired.", tenant_id=tenant_id)
            except Exception:
                return _err("VALIDATION_ERROR", "Tenant oauth_token_expires_at is invalid in datastore.", tenant_id=tenant_id)
    else:
        return _err("UNAUTHORIZED", "Tenant Freshdesk authentication is not configured.", tenant_id=tenant_id)

    rl = tenant.get("rate_limit_per_minute")
    if not _is_int(rl) or rl < 1:
        return _err("VALIDATION_ERROR", "Tenant rate_limit_per_minute is invalid in datastore.", tenant_id=tenant_id)
    req_log = tenant.get("_request_log")
    if not isinstance(req_log, list):
        req_log = []
        tenant["_request_log"] = req_log

    cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
    recent = 0
    for r in req_log:
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= rl:
        req_log.append({
            "endpoint": "view_solution_article",
            "tenant_id": tenant_id,
            "status": "RATE_LIMIT",
            "timestamp": now_ts,
            "latency_ms": int((time.time() - start) * 1000),
        })
        for i, t in enumerate(tenants):
            if t.get("id") == tenant_id:
                tenants[i] = tenant
                break
        _save("tenants.json", tenants)
        return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=rl)

    row = next((r for r in kat
                if r.get("tenant_id") == tenant_id
                and r.get("record_type") == "solution_article"
                and r.get("freshdesk_id") == solution_article_freshdesk_id), None)

    if row is None or row.get("status") == "deleted":
        req_log.append({
            "endpoint": "view_solution_article",
            "tenant_id": tenant_id,
            "status": "NOT_FOUND",
            "timestamp": now_ts,
            "latency_ms": int((time.time() - start) * 1000),
        })
        for i, t in enumerate(tenants):
            if t.get("id") == tenant_id:
                tenants[i] = tenant
                break
        _save("tenants.json", tenants)
        return _err("NOT_FOUND", "Solution article not found.", solution_article_freshdesk_id=solution_article_freshdesk_id)

    # Refreshed-from-Freshdesk when needed: offline, we treat cached as source of truth and only bump last_synced_at if missing.
    changed = False
    if not row.get("last_synced_at"):
        row["last_synced_at"] = _now()
        row["updated_at"] = row["last_synced_at"]
        changed = True
        _save("knowledge_and_templates.json", kat)

    req_log.append({
        "endpoint": "view_solution_article",
        "tenant_id": tenant_id,
        "status": "OK",
        "timestamp": now_ts,
        "latency_ms": int((time.time() - start) * 1000),
    })
    for i, t in enumerate(tenants):
        if t.get("id") == tenant_id:
            if changed:
                tenant["updated_at"] = _now()
            tenants[i] = tenant
            break
    _save("tenants.json", tenants)

    return {"data": row}

def update_solution_article(tenant_id, solution_article_freshdesk_id, solution_folder_freshdesk_id=None, title=None, description_html=None, status=None, tags=None, seo_data=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    start = time.time()
    now_ts = _now()

    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        return _err("VALIDATION_ERROR", "tenant_id is malformed.", field="tenant_id")
    if not _is_int(solution_article_freshdesk_id) or solution_article_freshdesk_id < 1:
        return _err("VALIDATION_ERROR", "solution_article_freshdesk_id must be an integer >= 1.", field="solution_article_freshdesk_id")

    if solution_folder_freshdesk_id is not None and (not _is_int(solution_folder_freshdesk_id) or solution_folder_freshdesk_id < 1):
        return _err("VALIDATION_ERROR", "solution_folder_freshdesk_id must be an integer >= 1.", field="solution_folder_freshdesk_id")
    if title is not None and (not isinstance(title, str) or len(title.strip()) < 1):
        return _err("VALIDATION_ERROR", "title must be non-empty when provided.", field="title")
    if description_html is not None and (not isinstance(description_html, str) or len(description_html.strip()) < 1):
        return _err("VALIDATION_ERROR", "description_html must be non-empty when provided.", field="description_html")
    if status is not None and (not _is_int(status) or status not in (1, 2)):
        return _err("VALIDATION_ERROR", "status must be one of {1,2} when provided.", field="status")
    if tags is not None:
        if not isinstance(tags, list) or any((not isinstance(t, str)) for t in tags):
            return _err("VALIDATION_ERROR", "tags must be an array of strings when provided.", field="tags")
    if seo_data is not None and not isinstance(seo_data, dict):
        return _err("VALIDATION_ERROR", "seo_data must be an object when provided.", field="seo_data")

    tenants = _load("tenants.json")
    kat = _load("knowledge_and_templates.json")

    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant or tenant.get("status") != "active":
        return _err("UNAUTHORIZED", "Tenant not authorized or not active for Freshdesk operations.", tenant_id=tenant_id)

    auth_type = tenant.get("auth_type")
    if auth_type == "api_key":
        if not tenant.get("api_key_ciphertext"):
            return _err("UNAUTHORIZED", "Tenant Freshdesk API key is not configured.", tenant_id=tenant_id)
    elif auth_type == "oauth":
        if not tenant.get("oauth_access_token_ciphertext"):
            return _err("UNAUTHORIZED", "Tenant Freshdesk OAuth access token is not configured.", tenant_id=tenant_id)
        exp = tenant.get("oauth_token_expires_at")
        if exp:
            try:
                exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00"))
                if exp_dt <= datetime.datetime.now(datetime.timezone.utc):
                    return _err("UNAUTHORIZED", "Tenant Freshdesk OAuth access token is expired.", tenant_id=tenant_id)
            except Exception:
                return _err("VALIDATION_ERROR", "Tenant oauth_token_expires_at is invalid in datastore.", tenant_id=tenant_id)
    else:
        return _err("UNAUTHORIZED", "Tenant Freshdesk authentication is not configured.", tenant_id=tenant_id)

    rl = tenant.get("rate_limit_per_minute")
    if not _is_int(rl) or rl < 1:
        return _err("VALIDATION_ERROR", "Tenant rate_limit_per_minute is invalid in datastore.", tenant_id=tenant_id)
    req_log = tenant.get("_request_log")
    if not isinstance(req_log, list):
        req_log = []
        tenant["_request_log"] = req_log

    cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
    recent = 0
    for r in req_log:
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= rl:
        req_log.append({
            "endpoint": "update_solution_article",
            "tenant_id": tenant_id,
            "status": "RATE_LIMIT",
            "timestamp": now_ts,
            "latency_ms": int((time.time() - start) * 1000),
        })
        for i, t in enumerate(tenants):
            if t.get("id") == tenant_id:
                tenants[i] = tenant
                break
        _save("tenants.json", tenants)
        return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=rl)

    idx = None
    row = None
    for i, r in enumerate(kat):
        if r.get("tenant_id") == tenant_id and r.get("record_type") == "solution_article" and r.get("freshdesk_id") == solution_article_freshdesk_id:
            idx = i
            row = r
            break

    if row is None or row.get("status") == "deleted":
        req_log.append({
            "endpoint": "update_solution_article",
            "tenant_id": tenant_id,
            "status": "NOT_FOUND",
            "timestamp": now_ts,
            "latency_ms": int((time.time() - start) * 1000),
        })
        for i, t in enumerate(tenants):
            if t.get("id") == tenant_id:
                tenants[i] = tenant
                break
        _save("tenants.json", tenants)
        return _err("NOT_FOUND", "Solution article not found.", solution_article_freshdesk_id=solution_article_freshdesk_id)

    # Cannot update upstream object that does not exist
    if row.get("freshdesk_id") is None:
        req_log.append({
            "endpoint": "update_solution_article",
            "tenant_id": tenant_id,
            "status": "CONFLICT",
            "timestamp": now_ts,
            "latency_ms": int((time.time() - start) * 1000),
        })
        for i, t in enumerate(tenants):
            if t.get("id") == tenant_id:
                tenants[i] = tenant
                break
        _save("tenants.json", tenants)
        return _err("CONFLICT", "Cannot update a solution article that has not been created upstream (freshdesk_id is null).", id=row.get("id"))

    # If moving folder, require the destination folder exists in cache (offline)
    if solution_folder_freshdesk_id is not None:
        parent = next((r for r in kat
                       if r.get("tenant_id") == tenant_id
                       and r.get("record_type") == "solution_folder"
                       and r.get("freshdesk_id") == solution_folder_freshdesk_id
                       and r.get("status") != "deleted"), None)
        if parent is None:
            req_log.append({
                "endpoint": "update_solution_article",
                "tenant_id": tenant_id,
                "status": "NOT_FOUND",
                "timestamp": now_ts,
                "latency_ms": int((time.time() - start) * 1000),
            })
            for i, t in enumerate(tenants):
                if t.get("id") == tenant_id:
                    tenants[i] = tenant
                    break
            _save("tenants.json", tenants)
            return _err("NOT_FOUND", "Destination solution folder not found in cache for tenant.", solution_folder_freshdesk_id=solution_folder_freshdesk_id)

    # Apply updates
    if title is not None:
        row["title"] = title
    if description_html is not None:
        row["content_html"] = description_html
    if status is not None:
        row["status"] = "draft" if status == 1 else "active"
    if solution_folder_freshdesk_id is not None:
        row["parent_freshdesk_id"] = solution_folder_freshdesk_id

    # Update raw to reflect refreshed upstream object
    raw = row.get("raw")
    if not isinstance(raw, dict):
        raw = {}
    # Freshdesk uses description for HTML content
    if title is not None:
        raw["title"] = title
    if description_html is not None:
        raw["description"] = description_html
    if status is not None:
        raw["status"] = status
    if solution_folder_freshdesk_id is not None:
        raw["folder_id"] = solution_folder_freshdesk_id
    if tags is not None:
        raw["tags"] = tags
    if seo_data is not None:
        raw["seo_data"] = seo_data
    raw["id"] = row.get("freshdesk_id")
    row["raw"] = raw

    # refresh search_text
    st_parts = []
    if row.get("title"):
        st_parts.append(str(row["title"]))
    if row.get("content_html"):
        st_parts.append(str(row["content_html"]))
    row["search_text"] = " ".join(st_parts)[:20000] if st_parts else row.get("search_text")

    row["last_synced_at"] = _now()
    row["updated_at"] = row["last_synced_at"]

    kat[idx] = row
    _save("knowledge_and_templates.json", kat)

    req_log.append({
        "endpoint": "update_solution_article",
        "tenant_id": tenant_id,
        "status": "OK",
        "timestamp": now_ts,
        "latency_ms": int((time.time() - start) * 1000),
    })
    for i, t in enumerate(tenants):
        if t.get("id") == tenant_id:
            tenant["updated_at"] = _now()
            tenants[i] = tenant
            break
    _save("tenants.json", tenants)

    return {"data": row}

