def create_agent(tenant_id, name, email, mobile=None, phone=None, job_title=None, department_ids=None, group_ids=None, role_ids=None, ticket_scope=None, occasional=None, signature=None, time_zone=None, language=None, custom_fields=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_agent"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_log_store():
        # Prefer any existing conventional log file; else create vendor-neutral request_logs.json
        candidates = ["request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"]
        for c in candidates:
            p = os.path.join(_DB, c)
            if os.path.exists(p):
                return c
        return "request_logs.json"

    def _append_log(status, tenant_id_val=None, error_code=None):
        n = _get_log_store()
        logs = _load(n)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(time.time())).encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "tenant_id": tenant_id_val,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        logs.append(row)
        _save(n, logs)

    def _validate_tenant_id(x):
        if not isinstance(x, str):
            return False
        return re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{10,}$", x) is not None

    def _valid_email(x):
        if not isinstance(x, str) or not x:
            return False
        # pragmatic email validation
        return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", x) is not None

    def _validate_int_array(arr, field):
        if arr is None:
            return None
        if not isinstance(arr, list):
            return _err("VALIDATION_ERROR", f"{field} must be an array of integers", field=field)
        for i, v in enumerate(arr):
            if not isinstance(v, int) or v < 1:
                return _err("VALIDATION_ERROR", f"{field}[{i}] must be an integer >= 1", field=field)
        return None

    # Input validation
    if not _validate_tenant_id(tenant_id):
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tenant_id is malformed", field="tenant_id")
    if not isinstance(name, str) or len(name.strip()) < 1:
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required", field="name")
    if not _valid_email(email):
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "email is invalid", field="email")

    for field_name, arr in [("department_ids", department_ids), ("group_ids", group_ids), ("role_ids", role_ids)]:
        e = _validate_int_array(arr, field_name)
        if e:
            _append_log("error", tenant_id, "VALIDATION_ERROR")
            return e

    if ticket_scope is not None:
        if not isinstance(ticket_scope, int) or ticket_scope not in (1, 2, 3):
            _append_log("error", tenant_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "ticket_scope must be one of 1,2,3", field="ticket_scope")
    if occasional is not None and not isinstance(occasional, bool):
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "occasional must be boolean", field="occasional")
    if custom_fields is not None and not isinstance(custom_fields, dict):
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "custom_fields must be an object", field="custom_fields")

    # Resolve tenant and enforce tenant-level rate limit (per minute)
    tenants = _load("tenants.json")
    if not isinstance(tenants, list):
        tenants = []
    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant or tenant.get("status") != "active":
        _append_log("error", tenant_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active tenant context available for this request")

    # Verify tenant has a "valid Freshdesk connection" (per rules: must have required ciphertext present)
    auth_type = tenant.get("auth_type")
    if auth_type == "api_key":
        if not tenant.get("api_key_ciphertext"):
            _append_log("error", tenant_id, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tenant has no valid Freshdesk API key configured")
    elif auth_type == "oauth":
        if not tenant.get("oauth_access_token_ciphertext"):
            _append_log("error", tenant_id, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tenant has no valid Freshdesk OAuth token configured")
    else:
        _append_log("error", tenant_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant has no valid Freshdesk connection configured")

    # rate limit check against request logs
    rl = tenant.get("rate_limit_per_minute")
    if not isinstance(rl, int) or rl < 1:
        rl = 60
    log_file = _get_log_store()
    logs = _load(log_file)
    if not isinstance(logs, list):
        logs = []
    now = datetime.datetime.utcnow()
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") != tenant_id:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= rl:
        _append_log("error", tenant_id, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rl)

    # Enforce unique-ish per tenant for agents: unique(tenant_id, entity_type, lower(email)) where active and email not null
    pao = _load("people_and_orgs.json")
    if not isinstance(pao, list):
        pao = []
    email_l = email.strip().lower()
    for row in pao:
        if not isinstance(row, dict):
            continue
        if row.get("tenant_id") == tenant_id and row.get("entity_type") == "agent" and row.get("status") == "active":
            em = row.get("email")
            if isinstance(em, str) and em.strip().lower() == email_l:
                _append_log("error", tenant_id, "CONFLICT")
                return _err("CONFLICT", "An active agent with this email already exists in the local cache", field="email")

    # Create local staged row first (freshdesk_id null) with raw=request payload (business rule)
    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # 16 chars of pseudo-random Crockford base32
        import random
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(16))

    now_iso = _now_iso()
    payload = {
        "name": name,
        "email": email,
    }
    # only include optional fields if provided (reflect request payload)
    if mobile is not None: payload["mobile"] = mobile
    if phone is not None: payload["phone"] = phone
    if job_title is not None: payload["job_title"] = job_title
    if department_ids is not None: payload["department_ids"] = department_ids
    if group_ids is not None: payload["group_ids"] = group_ids
    if role_ids is not None: payload["role_ids"] = role_ids
    if ticket_scope is not None: payload["ticket_scope"] = ticket_scope
    if occasional is not None: payload["occasional"] = occasional
    if signature is not None: payload["signature"] = signature
    if time_zone is not None: payload["time_zone"] = time_zone
    if language is not None: payload["language"] = language
    if custom_fields is not None: payload["custom_fields"] = custom_fields

    local_id = _ulid_like("fdpao")
    staged = {
        "id": local_id,
        "tenant_id": tenant_id,
        "entity_type": "agent",
        "status": "active",
        "freshdesk_id": None,
        "name": name,
        "email": email,
        "phone": phone if phone is not None else None,
        "company_freshdesk_id": None,
        "is_active": True if isinstance(occasional, bool) else None,  # best-effort; schema says is_active for agents
        "raw": payload,
        "search_text": " ".join([p for p in [name, email, phone or "", mobile or ""] if isinstance(p, str)]).strip().lower() or None,
        "last_synced_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    pao.append(staged)
    _save("people_and_orgs.json", pao)

    # Simulate upstream Freshdesk success by assigning a new numeric freshdesk_id and "response" object.
    # (Offline datastore; we persist what would be returned.)
    max_fd = 0
    for row in pao:
        if not isinstance(row, dict):
            continue
        if row.get("tenant_id") == tenant_id and row.get("entity_type") == "agent":
            v = row.get("freshdesk_id")
            if isinstance(v, int) and v > max_fd:
                max_fd = v
    new_fd_id = max_fd + 1 if max_fd > 0 else 1

    upstream_obj = dict(payload)
    upstream_obj["id"] = new_fd_id
    upstream_obj["created_at"] = now_iso
    upstream_obj["updated_at"] = now_iso
    # Freshdesk commonly uses active flag; keep best-effort
    if "active" not in upstream_obj:
        upstream_obj["active"] = True

    # Replace/merge staged row with upstream response, set last_synced_at
    for i, row in enumerate(pao):
        if isinstance(row, dict) and row.get("id") == local_id:
            row["freshdesk_id"] = new_fd_id
            row["raw"] = upstream_obj
            row["last_synced_at"] = now_iso
            row["updated_at"] = now_iso
            # refresh denormalized fields
            row["name"] = upstream_obj.get("name")
            row["email"] = upstream_obj.get("email")
            row["phone"] = upstream_obj.get("phone", row.get("phone"))
            row["is_active"] = upstream_obj.get("active") if isinstance(upstream_obj.get("active"), bool) else row.get("is_active")
            row["search_text"] = " ".join([p for p in [row.get("name") or "", row.get("email") or "", row.get("phone") or "", upstream_obj.get("mobile") or ""] if isinstance(p, str)]).strip().lower() or None
            pao[i] = row
            break
    _save("people_and_orgs.json", pao)

    _append_log("ok", tenant_id, None)
    return {
        "agent": next((r for r in pao if isinstance(r, dict) and r.get("id") == local_id), None),
        "tenant_id": tenant_id,
    }

def update_agent(tenant_id, agent_freshdesk_id, name=None, email=None, mobile=None, phone=None, job_title=None, department_ids=None, group_ids=None, role_ids=None, ticket_scope=None, occasional=None, signature=None, time_zone=None, language=None, custom_fields=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_agent"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _append_log(status, tenant_row=None, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
                "credential_type": (tenant_row.get("auth_type") if isinstance(tenant_row, dict) else None),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now_iso(),
                **({"error": error} if error is not None else {}),
                **({"meta": meta} if meta is not None else {}),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _tenant_has_creds(t):
        if not isinstance(t, dict):
            return False
        if t.get("status") != "active":
            return False
        at = t.get("auth_type")
        if at == "api_key":
            return bool(t.get("api_key_ciphertext"))
        if at == "oauth":
            return bool(t.get("oauth_access_token_ciphertext"))
        return False

    def _valid_email(x):
        return isinstance(x, str) and re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", x) is not None

    def _validate_int_array(arr, field):
        if arr is None:
            return None
        if not isinstance(arr, list):
            return _err("VALIDATION_ERROR", f"{field} must be an array of integers.", field=field)
        for v in arr:
            if not isinstance(v, int) or isinstance(v, bool) or v < 1:
                return _err("VALIDATION_ERROR", f"{field} must contain only positive integers.", field=field)
        return None

    def _enforce_rate_limit(tenant_row):
        rpm = tenant_row.get("rate_limit_per_minute")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= cutoff:
                count += 1
        if count >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=rpm)
        return None

    try:
        if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
            e = _err("VALIDATION_ERROR", "tenant_id is malformed.", field="tenant_id")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(agent_freshdesk_id, int) or isinstance(agent_freshdesk_id, bool) or agent_freshdesk_id < 1:
            e = _err("VALIDATION_ERROR", "agent_freshdesk_id must be a positive integer.", field="agent_freshdesk_id")
            _append_log("error", error=e["error"])
            return e

        if name is not None and (not isinstance(name, str) or not name.strip()):
            e = _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
            _append_log("error", error=e["error"])
            return e
        if email is not None and not _valid_email(email):
            e = _err("VALIDATION_ERROR", "email must be a valid email address.", field="email")
            _append_log("error", error=e["error"])
            return e
        for fval, fname in ((mobile, "mobile"), (phone, "phone"), (job_title, "job_title"), (signature, "signature"), (time_zone, "time_zone"), (language, "language")):
            if fval is not None and (not isinstance(fval, str) or not fval.strip()):
                e = _err("VALIDATION_ERROR", f"{fname} must be a non-empty string.", field=fname)
                _append_log("error", error=e["error"])
                return e
        if ticket_scope is not None and ticket_scope not in (1, 2, 3):
            e = _err("VALIDATION_ERROR", "ticket_scope must be one of: 1, 2, 3.", field="ticket_scope")
            _append_log("error", error=e["error"])
            return e
        if occasional is not None and not isinstance(occasional, bool):
            e = _err("VALIDATION_ERROR", "occasional must be a boolean.", field="occasional")
            _append_log("error", error=e["error"])
            return e
        if custom_fields is not None and not isinstance(custom_fields, dict):
            e = _err("VALIDATION_ERROR", "custom_fields must be an object.", field="custom_fields")
            _append_log("error", error=e["error"])
            return e

        for arr, fname in ((department_ids, "department_ids"), (group_ids, "group_ids"), (role_ids, "role_ids")):
            verr = _validate_int_array(arr, fname)
            if verr:
                _append_log("error", error=verr["error"])
                return verr

        if all(v is None for v in (name, email, mobile, phone, job_title, department_ids, group_ids, role_ids, ticket_scope, occasional, signature, time_zone, language, custom_fields)):
            e = _err("VALIDATION_ERROR", "At least one updatable field must be provided.")
            _append_log("error", error=e["error"])
            return e

        tenants = _load("tenants.json")
        if not isinstance(tenants, list):
            tenants = []
        tenant_row = None
        for t in tenants:
            if isinstance(t, dict) and t.get("id") == tenant_id and t.get("status") != "deleted":
                tenant_row = t
                break
        if tenant_row is None:
            e = _err("NOT_FOUND", "Tenant not found.")
            _append_log("error", error=e["error"])
            return e
        if not _tenant_has_creds(tenant_row):
            e = _err("UNAUTHORIZED", "Tenant Freshdesk credentials are missing/invalid.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        rl = _enforce_rate_limit(tenant_row)
        if rl:
            _append_log("error", tenant_row=tenant_row, error=rl["error"])
            return rl

        ents = _load("people_and_orgs.json")
        if not isinstance(ents, list):
            ents = []

        idx = None
        for i, r in enumerate(ents):
            if isinstance(r, dict) and r.get("tenant_id") == tenant_id and r.get("entity_type") == "agent" and r.get("freshdesk_id") == agent_freshdesk_id:
                idx = i
                break
        if idx is None:
            e = _err("NOT_FOUND", "Agent not found for this tenant.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        row = ents[idx]
        if row.get("status") == "deleted":
            e = _err("INVALID_TRANSITION", "Cannot update a deleted agent.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        # enforce "unique-ish" email for active agents when email present
        if email is not None:
            email_l = email.strip().lower()
            for j, other in enumerate(ents):
                if j == idx or not isinstance(other, dict):
                    continue
                if other.get("tenant_id") != tenant_id or other.get("entity_type") != "agent" or other.get("status") != "active":
                    continue
                oemail = other.get("email")
                if isinstance(oemail, str) and oemail.strip().lower() == email_l:
                    e = _err("CONFLICT", "An agent with this email already exists for this tenant.", field="email")
                    _append_log("error", tenant_row=tenant_row, error=e["error"])
                    return e

        now = _now_iso()
        if name is not None:
            row["name"] = name
        if email is not None:
            row["email"] = email
        if phone is not None:
            row["phone"] = phone
        if mobile is not None:
            # store in raw; schema doesn't have dedicated mobile
            pass
        if row.get("is_active") is None and occasional is not None:
            # keep is_active as-is; occasional isn't is_active
            pass

        raw = row.get("raw")
        if not isinstance(raw, dict):
            raw = {}
        # best-effort merge into raw
        if name is not None:
            raw["name"] = name
        if email is not None:
            raw["email"] = email
        if mobile is not None:
            raw["mobile"] = mobile
        if phone is not None:
            raw["phone"] = phone
        if job_title is not None:
            raw["job_title"] = job_title
        if department_ids is not None:
            raw["department_ids"] = department_ids
        if group_ids is not None:
            raw["group_ids"] = group_ids
        if role_ids is not None:
            raw["role_ids"] = role_ids
        if ticket_scope is not None:
            raw["ticket_scope"] = ticket_scope
        if occasional is not None:
            raw["occasional"] = occasional
        if signature is not None:
            raw["signature"] = signature
        if time_zone is not None:
            raw["time_zone"] = time_zone
        if language is not None:
            raw["language"] = language
        if custom_fields is not None:
            raw["custom_fields"] = custom_fields
        row["raw"] = raw

        st_parts = []
        for k in ("name", "email", "phone"):
            v = row.get(k)
            if isinstance(v, str) and v.strip():
                st_parts.append(v.strip())
        row["search_text"] = " ".join(st_parts) if st_parts else row.get("search_text")

        row["updated_at"] = now
        row["last_synced_at"] = now

        ents[idx] = row
        _save("people_and_orgs.json", ents)

        _append_log("ok", tenant_row=tenant_row, meta={"updated": True})
        return {"agent": row}
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(ex))
        _append_log("error", error=e["error"])
        return e

def search_agents(tenant_id, query, limit=None, cursor=None, sort=None, status=None, is_active=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_agents"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_log_store():
        candidates = ["request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"]
        for c in candidates:
            if os.path.exists(os.path.join(_DB, c)):
                return c
        return "request_logs.json"

    def _append_log(status_s, tenant_id_val=None, error_code=None):
        n = _get_log_store()
        logs = _load(n)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(time.time())).encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "tenant_id": tenant_id_val,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save(n, logs)

    def _validate_tenant_id(x):
        return isinstance(x, str) and re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{10,}$", x) is not None

    if not _validate_tenant_id(tenant_id):
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tenant_id is malformed", field="tenant_id")
    if not isinstance(query, str) or len(query.strip()) < 1:
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a non-empty string", field="query")

    tenants = _load("tenants.json")
    if not isinstance(tenants, list):
        tenants = []
    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant or tenant.get("status") != "active":
        _append_log("error", tenant_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active tenant context available for this request")

    # Rate limit
    rl = tenant.get("rate_limit_per_minute")
    if not isinstance(rl, int) or rl < 1:
        rl = 60
    log_file = _get_log_store()
    logs = _load(log_file)
    if not isinstance(logs, list):
        logs = []
    now = datetime.datetime.utcnow()
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict) or r.get("tenant_id") != tenant_id:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= rl:
        _append_log("error", tenant_id, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rl)

    # Defaults
    if limit is None:
        dps = tenant.get("default_page_size")
        limit = dps if isinstance(dps, int) and 1 <= dps <= 100 else 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")

    if sort is None:
        sort = "updated_at"
    if sort not in ("name", "-name", "updated_at", "-updated_at", "created_at", "-created_at"):
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")

    if status is None:
        status = "active"  # default excludes deleted per business rules
    if status not in ("active", "deleted"):
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be 'active' or 'deleted'", field="status")
    if is_active is not None and not isinstance(is_active, bool):
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_active must be boolean", field="is_active")

    # Cursor: base64 encoded integer offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _append_log("error", tenant_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                raise ValueError("neg")
        except Exception:
            _append_log("error", tenant_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    pao = _load("people_and_orgs.json")
    if not isinstance(pao, list):
        pao = []

    q = query.strip().lower()

    def _hay(row):
        st = row.get("search_text")
        if isinstance(st, str) and st:
            return st.lower()
        raw = row.get("raw")
        parts = []
        if isinstance(row.get("name"), str): parts.append(row["name"])
        if isinstance(row.get("email"), str): parts.append(row["email"])
        if isinstance(row.get("phone"), str): parts.append(row["phone"])
        if isinstance(raw, dict):
            for k in ("mobile", "job_title", "signature", "time_zone", "language"):
                v = raw.get(k)
                if isinstance(v, str):
                    parts.append(v)
        return " ".join(parts).lower()

    rows = []
    for r in pao:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") != tenant_id or r.get("entity_type") != "agent":
            continue
        if status == "active":
            if r.get("status") == "deleted":
                continue
        else:
            if r.get("status") != "deleted":
                continue
        if is_active is not None:
            if r.get("is_active") is None:
                continue
            if r.get("is_active") != is_active:
                continue
        if q not in _hay(r):
            continue
        rows.append(r)

    # Sort
    key = sort.lstrip("-")
    desc = sort.startswith("-")

    def _keyfn(r):
        v = r.get(key)
        if key in ("created_at", "updated_at"):
            if isinstance(v, str):
                return v
            return ""
        if isinstance(v, str):
            return v.lower()
        return v if v is not None else ""

    rows.sort(key=_keyfn, reverse=desc)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    _append_log("ok", tenant_id, None)
    return {
        "agents": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "has_more": has_more,
        "tenant_id": tenant_id,
    }

