        _append_log("error", tenant_id, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rl)

    if limit is None:
        dps = tenant.get("default_page_size")
        limit = dps if isinstance(dps, int) and 1 <= dps <= 100 else 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")

    if sort is None:
        sort = "updated_at"
    if sort not in ("name", "-name", "updated_at", "-updated_at", "created_at", "-created_at"):
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")

    if status is None:
        status = "active"  # default excludes deleted
    if status not in ("active", "deleted"):
        _append_log("error", tenant_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be 'active' or 'deleted'", field="status")

    # Cursor: base64 encoded integer offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _append_log("error", tenant_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                raise ValueError("neg")
        except Exception:
            _append_log("error", tenant_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    pao = _load("people_and_orgs.json")
    if not isinstance(pao, list):
        pao = []

    rows = []
    for r in pao:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") != tenant_id or r.get("entity_type") != "group":
            continue
        if status == "active":
            if r.get("status") == "deleted":
                continue
        else:
            if r.get("status") != "deleted":
                continue
        rows.append(r)

    # Sort
    key = sort.lstrip("-")
    desc = sort.startswith("-")

    def _keyfn(r):
        v = r.get(key)
        if key in ("created_at", "updated_at"):
            return v if isinstance(v, str) else ""
        if isinstance(v, str):
            return v.lower()
        return v if v is not None else ""

    rows.sort(key=_keyfn, reverse=desc)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    _append_log("ok", tenant_id, None)
    return {
        "groups": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "has_more": has_more,
        "tenant_id": tenant_id,
    }

def create_group(tenant_id, body, **_extra):
    import json, os, datetime, re, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # 26-char ULID-like randomness (not time-sortable, but conforms to pattern)
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(26))

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _log(endpoint, tenant_id, status, latency_ms, credential_id=None, error_code=None):
        _ensure_request_log()
        logs = _load("request_logs.json")
        logs.append(
            {
                "id": _gen_id("fdreq"),
                "endpoint": endpoint,
                "tenant_id": tenant_id,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int(latency_ms),
                "timestamp": _now(),
            }
        )
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "create_group"

    # Validate inputs
    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{26}$", tenant_id):
        _log(endpoint, tenant_id if isinstance(tenant_id, str) else None, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tenant_id must be a valid fdten_ ULID", field="tenant_id")

    if not isinstance(body, dict):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body must be an object", field="body")

    allowed = {"name", "description", "auto_ticket_assign", "escalate_to", "unassigned_for", "business_hour_id", "members"}
    extra = set(body.keys()) - allowed
    if extra:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body contains unknown fields", unknown_fields=sorted(extra))

    if "name" not in body or not isinstance(body.get("name"), str) or not body["name"].strip():
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body.name is required and must be a non-empty string", field="name")

    def _check_int(name, min_v=None):
        if name in body and body[name] is not None:
            if not isinstance(body[name], int):
                return _err("VALIDATION_ERROR", f"body.{name} must be an integer", field=name)
            if min_v is not None and body[name] < min_v:
                return _err("VALIDATION_ERROR", f"body.{name} must be >= {min_v}", field=name)
        return None

    for nm, mn in [("escalate_to", 1), ("business_hour_id", 1), ("unassigned_for", 0)]:
        e = _check_int(nm, mn)
        if e:
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code=e["error"]["code"])
            return e

    for nm in ["auto_ticket_assign"]:
        if nm in body and body[nm] is not None and not isinstance(body[nm], bool):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"body.{nm} must be a boolean", field=nm)

    if "members" in body and body["members"] is not None:
        if not isinstance(body["members"], list):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body.members must be an array of integers", field="members")
        for i, v in enumerate(body["members"]):
            if not isinstance(v, int) or v < 1:
                _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "body.members items must be integers >= 1", field="members", index=i)

    # Resolve tenant + "credentials" (ambient auth, but tenant must be usable)
    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant or tenant.get("status") == "deleted":
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "tenant not found", tenant_id=tenant_id)
    if tenant.get("status") != "active":
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "tenant is not active", tenant_id=tenant_id, status=tenant.get("status"))

    auth_type = tenant.get("auth_type")
    if auth_type == "api_key":
        if not tenant.get("api_key_ciphertext"):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "tenant has no valid Freshdesk API key configured", tenant_id=tenant_id)
    elif auth_type == "oauth":
        if not tenant.get("oauth_access_token_ciphertext"):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "tenant has no valid Freshdesk OAuth token configured", tenant_id=tenant_id)
    else:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "tenant has no valid Freshdesk credentials configured", tenant_id=tenant_id)

    # Rate limit per tenant
    rate = tenant.get("rate_limit_per_minute")
    if not isinstance(rate, int) or rate < 1 or rate > 600:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tenant rate_limit_per_minute is misconfigured", tenant_id=tenant_id)
    _ensure_request_log()
    logs = _load("request_logs.json")
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if r.get("tenant_id") != tenant_id:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= rate:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "rate limit exceeded", limit_per_minute=rate)

    # "Upstream" create: since offline, we simulate successful upstream by minting a freshdesk_id and returning canonical object
    people = _load("people_and_orgs.json")

    # Validate referenced agent ids (members/escalate_to) if cached for tenant
    agent_ids_cached = {p.get("freshdesk_id") for p in people if p.get("tenant_id") == tenant_id and p.get("entity_type") == "agent" and p.get("status") == "active" and isinstance(p.get("freshdesk_id"), int)}
    for ref_field in ["escalate_to"]:
        if body.get(ref_field) is not None and agent_ids_cached and body.get(ref_field) not in agent_ids_cached:
            # soft FK: only enforce if we have any agents cached; otherwise allow
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"body.{ref_field} does not refer to a known cached agent", field=ref_field)

    if body.get("members") and agent_ids_cached:
        for v in body["members"]:
            if v not in agent_ids_cached:
                _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "body.members contains an agent id not found in cache", field="members", bad_member=v)

    # Determine next freshdesk_id (per tenant+type)
    existing_ids = [
        p.get("freshdesk_id")
        for p in people
        if p.get("tenant_id") == tenant_id and p.get("entity_type") == "group" and isinstance(p.get("freshdesk_id"), int)
    ]
    next_fd_id = (max(existing_ids) + 1) if existing_ids else 1

    upstream_group = {
        "id": next_fd_id,
        "name": body.get("name"),
        "description": body.get("description"),
        "auto_ticket_assign": body.get("auto_ticket_assign"),
        "escalate_to": body.get("escalate_to"),
        "unassigned_for": body.get("unassigned_for"),
        "business_hour_id": body.get("business_hour_id"),
        "members": body.get("members") if body.get("members") is not None else [],
    }

    # Upsert into cache (unique(tenant_id, entity_type, freshdesk_id))
    now = _now()
    existing = next((p for p in people if p.get("tenant_id") == tenant_id and p.get("entity_type") == "group" and p.get("freshdesk_id") == next_fd_id), None)
    if existing:
        # Shouldn't happen given we picked next id, but keep consistent
        existing["status"] = "active"
        existing["name"] = upstream_group.get("name")
        existing["email"] = None
        existing["phone"] = None
        existing["company_freshdesk_id"] = None
        existing["is_active"] = None
        existing["raw"] = upstream_group
        existing["search_text"] = (upstream_group.get("name") or "").lower()
        existing["last_synced_at"] = now
        existing["updated_at"] = now
        row = existing
    else:
        row = {
            "id": _gen_id("fdpo"),
            "tenant_id": tenant_id,
            "entity_type": "group",
            "status": "active",
            "freshdesk_id": next_fd_id,
            "name": upstream_group.get("name"),
            "email": None,
            "phone": None,
            "company_freshdesk_id": None,
            "is_active": None,
            "raw": upstream_group,
            "search_text": (upstream_group.get("name") or "").lower(),
            "last_synced_at": now,
            "created_at": now,
            "updated_at": now,
        }
        people.append(row)

    _save("people_and_orgs.json", people)
    _log(endpoint, tenant_id, "ok", (time.time() - t0) * 1000)

    return {"data": upstream_group}

