        if not isinstance(body["choices"], list) or any((not isinstance(x, str)) for x in body["choices"]):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body.choices must be an array of strings", field="choices")

    if "name" in body and body["name"] is not None:
        if not isinstance(body["name"], str) or not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", body["name"]):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body.name must match ^[a-zA-Z_][a-zA-Z0-9_]*$", field="name")

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant or tenant.get("status") == "deleted":
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "tenant not found", tenant_id=tenant_id)
    if tenant.get("status") != "active":
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "tenant is not active", tenant_id=tenant_id, status=tenant.get("status"))

    auth_type = tenant.get("auth_type")
    if auth_type == "api_key":
        if not tenant.get("api_key_ciphertext"):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "tenant has no valid Freshdesk API key configured", tenant_id=tenant_id)
    elif auth_type == "oauth":
        if not tenant.get("oauth_access_token_ciphertext"):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "tenant has no valid Freshdesk OAuth token configured", tenant_id=tenant_id)
    else:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "tenant has no valid Freshdesk credentials configured", tenant_id=tenant_id)

    rate = tenant.get("rate_limit_per_minute")
    if not isinstance(rate, int) or rate < 1 or rate > 600:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tenant rate_limit_per_minute is misconfigured", tenant_id=tenant_id)

    _ensure_request_log()
    logs = _load("request_logs.json")
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if r.get("tenant_id") != tenant_id:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= rate:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "rate limit exceeded", limit_per_minute=rate)

    fields = _load("custom_fields.json")

    # Determine field name: either provided, else derive from label (cf_<slug>)
    if body.get("name") is None:
        base = re.sub(r"[^a-zA-Z0-9_]+", "_", body["label"].strip().lower())
        base = re.sub(r"_+", "_", base).strip("_")
        if not base:
            base = "field"
        derived = "cf_" + base
        # Must match regex; ensure leading char
        if not re.match(r"^[a-zA-Z_]", derived):
            derived = "cf_" + "field"
        name = derived
    else:
        name = body["name"]

    if not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", name):
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "field name must match ^[a-zA-Z_][a-zA-Z0-9_]*$", field="name")

    # Enforce unique(tenant_id, field_scope, name)
    for f in fields:
        if f.get("tenant_id") == tenant_id and f.get("field_scope") == "ticket" and f.get("name") == name and f.get("status") != "deleted":
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="CONFLICT")
            return _err("CONFLICT", "ticket field name already exists", field_scope="ticket", name=name)

    # "Upstream" create: mint freshdesk_id
    existing_ids = [
        f.get("freshdesk_id")
        for f in fields
        if f.get("tenant_id") == tenant_id and f.get("field_scope") == "ticket" and isinstance(f.get("freshdesk_id"), int)
    ]
    next_fd_id = (max(existing_ids) + 1) if existing_ids else 1

    # Construct upstream-ish response
    upstream = {
        "id": next_fd_id,
        "name": name,
        "label": body.get("label"),
        "type": body.get("type"),
        "required": body.get("required"),
        "position": body.get("position"),
        "default_value": body.get("default_value"),
        "choices": body.get("choices"),
        "description": body.get("description"),
        "customers_can_edit": body.get("customers_can_edit"),
        "customers_can_view": body.get("customers_can_view"),
        "displayed_to_customers": body.get("displayed_to_customers"),
    }

    now = _now()
    row = {
        "id": _gen_id("fdcf"),
        "tenant_id": tenant_id,
        "field_scope": "ticket",
        "status": "active",
        "freshdesk_id": next_fd_id,
        "name": name,
        "label": body.get("label"),
        "field_type": body.get("type"),
        "required": body.get("required"),
        "properties": upstream,
        "position": body.get("position"),
        "last_synced_at": now,
        "created_at": now,
        "updated_at": now,
    }
    fields.append(row)
    _save("custom_fields.json", fields)

    _log(endpoint, tenant_id, "ok", (time.time() - t0) * 1000)
    return {"data": upstream}

def view_ticket_field(tenant_id, ticket_field_id, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(26))

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _log(endpoint, tenant_id, status, latency_ms, credential_id=None, error_code=None):
        _ensure_request_log()
        logs = _load("request_logs.json")
        logs.append(
            {
                "id": _gen_id("fdreq"),
                "endpoint": endpoint,
                "tenant_id": tenant_id,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int(latency_ms),
                "timestamp": _now(),
            }
        )
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "view_ticket_field"

    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{26}$", tenant_id):
        _log(endpoint, tenant_id if isinstance(tenant_id, str) else None, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tenant_id must be a valid fdten_ ULID", field="tenant_id")
    if not isinstance(ticket_field_id, int) or ticket_field_id < 1:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "ticket_field_id must be an integer >= 1", field="ticket_field_id")

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant or tenant.get("status") == "deleted":
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "tenant not found", tenant_id=tenant_id)
    if tenant.get("status") != "active":
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "tenant is not active", tenant_id=tenant_id, status=tenant.get("status"))

    auth_type = tenant.get("auth_type")
    if auth_type == "api_key":
        if not tenant.get("api_key_ciphertext"):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "tenant has no valid Freshdesk API key configured", tenant_id=tenant_id)
    elif auth_type == "oauth":
        if not tenant.get("oauth_access_token_ciphertext"):
            _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "tenant has no valid Freshdesk OAuth token configured", tenant_id=tenant_id)
    else:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "tenant has no valid Freshdesk credentials configured", tenant_id=tenant_id)

    rate = tenant.get("rate_limit_per_minute")
    if not isinstance(rate, int) or rate < 1 or rate > 600:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tenant rate_limit_per_minute is misconfigured", tenant_id=tenant_id)

    _ensure_request_log()
    logs = _load("request_logs.json")
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if r.get("tenant_id") != tenant_id:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= rate:
        _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "rate limit exceeded", limit_per_minute=rate)

    fields = _load("custom_fields.json")
    row = next(
        (
            f
            for f in fields
            if f.get("tenant_id") == tenant_id
            and f.get("field_scope") == "ticket"
            and f.get("freshdesk_id") == ticket_field_id
            and f.get("status") != "deleted"
        ),
        None,
    )

    if row:
        props = row.get("properties")
        if isinstance(props, dict) and props.get("id") == ticket_field_id:
            obj = props
        else:
            obj = {
                "id": ticket_field_id,
                "name": row.get("name"),
                "label": row.get("label"),
                "type": row.get("field_type"),
                "required": row.get("required"),
                "position": row.get("position"),
            }
        _log(endpoint, tenant_id, "ok", (time.time() - t0) * 1000)
        return {"data": obj}

    # Offline upstream fetch not available
    _log(endpoint, tenant_id, "error", (time.time() - t0) * 1000, error_code="NOT_FOUND")
    return _err("NOT_FOUND", "ticket field not found", ticket_field_id=ticket_field_id)

def update_ticket_field(tenant_id, ticket_field_id, body, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        # ULID-like stable length not required by schema for non-tenant collections; use prefix + uuid.
        return f"{prefix}_{uuid.uuid4().hex}"

    def _get_tenant(tenants, tid):
        for t in tenants:
            if t.get("id") == tid:
                return t
        return None

    def _has_valid_creds(tenant_row):
        if not tenant_row or tenant_row.get("status") != "active":
            return False
        at = tenant_row.get("auth_type")
        if at == "api_key":
            return tenant_row.get("api_key_ciphertext") is not None
        if at == "oauth":
            return tenant_row.get("oauth_access_token_ciphertext") is not None
        return False

    def _rate_limit_check_and_log(tenant_row, endpoint, status, started_at, extra=None):
        # request_logs.json is implicit; create/append.
        logs = _load("request_logs.json")
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        tenant_logs = []
        for r in logs:
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                if dt >= window_start:
                    tenant_logs.append(r)
        limited = len(tenant_logs) >= int(tenant_row.get("rate_limit_per_minute") or 60)

        latency_ms = int(max(0, (time.time() - started_at) * 1000))
        row = {
            "id": _gen_id("req"),
            "tenant_id": tenant_row.get("id") if tenant_row else None,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now.isoformat(),
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)
        return limited

    started = time.time()

    # Validate inputs
    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{26}$", tenant_id):
        # No tenant => cannot rate-limit/log per-tenant reliably; still log globally with tenant_id as provided.
        tenants = _load("tenants.json")
        fake_tenant = {"id": tenant_id, "rate_limit_per_minute": 600}
        _rate_limit_check_and_log(fake_tenant, "update_ticket_field", "error", started, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid tenant_id format.")
    if not isinstance(ticket_field_id, int) or ticket_field_id < 1:
        tenants = _load("tenants.json")
        trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id, "rate_limit_per_minute": 600}
        _rate_limit_check_and_log(trow, "update_ticket_field", "error", started, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "ticket_field_id must be an integer >= 1.")
    if not isinstance(body, dict):
        tenants = _load("tenants.json")
        trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id, "rate_limit_per_minute": 600}
        _rate_limit_check_and_log(trow, "update_ticket_field", "error", started, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "body must be an object.")
    allowed = {
        "label",
        "name",
        "type",
        "required",
        "position",
        "default_value",
        "choices",
        "description",
        "customers_can_edit",
        "customers_can_view",
        "displayed_to_customers",
        "deleted",
    }
    unknown = [k for k in body.keys() if k not in allowed]
    if unknown:
        tenants = _load("tenants.json")
        trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id, "rate_limit_per_minute": 600}
        _rate_limit_check_and_log(trow, "update_ticket_field", "error", started, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "body contains unknown properties.", unknown_properties=unknown)

    if "position" in body:
        if not isinstance(body["position"], int) or body["position"] < 1:
            tenants = _load("tenants.json")
            trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id, "rate_limit_per_minute": 600}
            _rate_limit_check_and_log(trow, "update_ticket_field", "error", started, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "position must be an integer >= 1.")
    if "choices" in body:
        if body["choices"] is not None:
            if not isinstance(body["choices"], list) or any(not isinstance(x, str) for x in body["choices"]):
                tenants = _load("tenants.json")
                trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id, "rate_limit_per_minute": 600}
                _rate_limit_check_and_log(trow, "update_ticket_field", "error", started, {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "choices must be an array of strings.")
    if "required" in body and not isinstance(body["required"], bool):
        tenants = _load("tenants.json")
        trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id, "rate_limit_per_minute": 600}
        _rate_limit_check_and_log(trow, "update_ticket_field", "error", started, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "required must be boolean.")
    for bkey in ("customers_can_edit", "customers_can_view", "displayed_to_customers", "deleted"):
        if bkey in body and not isinstance(body[bkey], bool):
            tenants = _load("tenants.json")
            trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id, "rate_limit_per_minute": 600}
            _rate_limit_check_and_log(trow, "update_ticket_field", "error", started, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{bkey} must be boolean.")
    for skey in ("label", "name", "type", "description"):
        if skey in body and body[skey] is not None and not isinstance(body[skey], str):
            tenants = _load("tenants.json")
            trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id, "rate_limit_per_minute": 600}
            _rate_limit_check_and_log(trow, "update_ticket_field", "error", started, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{skey} must be a string.")
    if "default_value" in body:
        dv = body["default_value"]
        if dv is not None and not isinstance(dv, (str, int, float, bool)):
            tenants = _load("tenants.json")
            trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id, "rate_limit_per_minute": 600}
            _rate_limit_check_and_log(trow, "update_ticket_field", "error", started, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "default_value must be string, number, boolean, or null.")

    tenants = _load("tenants.json")
    tenant = _get_tenant(tenants, tenant_id)
    if tenant is None:
        _rate_limit_check_and_log({"id": tenant_id, "rate_limit_per_minute": 600}, "update_ticket_field", "error", started, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Tenant not found.")
    if not _has_valid_creds(tenant):
        _rate_limit_check_and_log(tenant, "update_ticket_field", "error", started, {"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Tenant has no valid Freshdesk credentials.")

    # Rate limit before performing mutation (count recent logs)
    # We log after, but must enforce based on existing logs.
    logs = _load("request_logs.json")
    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if r.get("tenant_id") != tenant_id:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if dt >= window_start:
            recent += 1
    if recent >= int(tenant.get("rate_limit_per_minute") or 60):
        _rate_limit_check_and_log(tenant, "update_ticket_field", "error", started, {"error_code": "RATE_LIMIT"})
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    fields = _load("custom_fields.json")
    target = None
    for f in fields:
        if f.get("tenant_id") == tenant_id and f.get("field_scope") == "ticket" and f.get("freshdesk_id") == ticket_field_id:
            target = f
            break
    if target is None or target.get("status") == "deleted":
        _rate_limit_check_and_log(tenant, "update_ticket_field", "error", started, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Ticket field not found.")

    if target.get("freshdesk_id") is None:
        _rate_limit_check_and_log(tenant, "update_ticket_field", "error", started, {"error_code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "Cannot update a field that has not been created upstream (freshdesk_id is null).")

    # Enforce unique(tenant_id, field_scope, name) if name is changing
    if "name" in body and body["name"] is not None:
        new_name = body["name"]
        if not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", new_name):
            _rate_limit_check_and_log(tenant, "update_ticket_field", "error", started, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "name must match regex ^[a-zA-Z_][a-zA-Z0-9_]*$.")
        for f in fields:
            if f is target:
                continue
            if f.get("tenant_id") == tenant_id and f.get("field_scope") == "ticket" and f.get("status") != "deleted" and f.get("name") == new_name:
                _rate_limit_check_and_log(tenant, "update_ticket_field", "error", started, {"error_code": "CONFLICT"})
                return _err("CONFLICT", "A ticket field with this name already exists for this tenant.", field_scope="ticket", name=new_name)

    # Apply update (simulate upstream success by merging into properties/raw)
    now_iso = _now_iso()
    props = target.get("properties") if isinstance(target.get("properties"), dict) else {}
    raw = target.get("raw") if isinstance(target.get("raw"), dict) else {}

    # Map body keys to stored schema fields/properties
    if "label" in body:
        target["label"] = body["label"]
        props["label"] = body["label"]
        raw["label"] = body["label"]
    if "name" in body:
        target["name"] = body["name"]
        props["name"] = body["name"]
        raw["name"] = body["name"]
    if "type" in body:
        target["field_type"] = body["type"]
        props["type"] = body["type"]
        raw["type"] = body["type"]
    if "required" in body:
        target["required"] = body["required"]
        props["required"] = body["required"]
        raw["required"] = body["required"]
    if "position" in body:
        target["position"] = body["position"]
        props["position"] = body["position"]
        raw["position"] = body["position"]

    if "default_value" in body:
        props["default_value"] = body["default_value"]
        raw["default_value"] = body["default_value"]
    if "choices" in body:
        props["choices"] = body["choices"]
        raw["choices"] = body["choices"]
    if "description" in body:
        props["description"] = body["description"]
        raw["description"] = body["description"]
    if "customers_can_edit" in body:
        props["customers_can_edit"] = body["customers_can_edit"]
        raw["customers_can_edit"] = body["customers_can_edit"]
    if "customers_can_view" in body:
        props["customers_can_view"] = body["customers_can_view"]
        raw["customers_can_view"] = body["customers_can_view"]
    if "displayed_to_customers" in body:
        props["displayed_to_customers"] = body["displayed_to_customers"]
        raw["displayed_to_customers"] = body["displayed_to_customers"]

    # Interpret "deleted" as lifecycle change to disabled/deleted; Freshdesk behavior varies.
    if "deleted" in body:
        if body["deleted"] is True:
            # Prefer disable rather than hard delete; but schema supports deleted. Transition: active/disabled -> deleted.
            cur = target.get("status")
            if cur == "deleted":
                pass
            elif cur in ("active", "disabled"):
                target["status"] = "deleted"
            else:
                target["status"] = "deleted"
            raw["deleted"] = True
            props["deleted"] = True
        else:
            # cannot resurrect from deleted per lifecycle
            if target.get("status") == "deleted":
                _rate_limit_check_and_log(tenant, "update_ticket_field", "error", started, {"error_code": "INVALID_TRANSITION"})
                return _err("INVALID_TRANSITION", "Cannot transition a deleted field to a non-deleted state.")
            raw["deleted"] = False
            props["deleted"] = False

    target["properties"] = props
    target["raw"] = raw
    target["updated_at"] = now_iso
    target["last_synced_at"] = now_iso

    _save("custom_fields.json", fields)

    _rate_limit_check_and_log(tenant, "update_ticket_field", "ok", started)

    # Return updated "Freshdesk-like" object (derived from stored row)
    out = dict(target.get("raw") if isinstance(target.get("raw"), dict) else {})
    out.setdefault("id", target.get("freshdesk_id"))
    if target.get("name") is not None:
        out["name"] = target.get("name")
    if target.get("label") is not None:
        out["label"] = target.get("label")
    if target.get("field_type") is not None:
        out["type"] = target.get("field_type")
    if target.get("required") is not None:
        out["required"] = target.get("required")
    if target.get("position") is not None:
        out["position"] = target.get("position")
    return {"ticket_field": out}

def update_group(tenant_id, group_id, body, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")

