        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _get_tenant(tenants, tid):
        for t in tenants:
            if t.get("id") == tid:
                return t
        return None

    def _has_valid_creds(tenant_row):
        if not tenant_row or tenant_row.get("status") != "active":
            return False
        at = tenant_row.get("auth_type")
        if at == "api_key":
            return tenant_row.get("api_key_ciphertext") is not None
        if at == "oauth":
            return tenant_row.get("oauth_access_token_ciphertext") is not None
        return False

    def _log(tenant_row, endpoint, status, started_at, extra=None):
        logs = _load("request_logs.json")
        now = datetime.datetime.now(datetime.timezone.utc)
        latency_ms = int(max(0, (time.time() - started_at) * 1000))
        row = {
            "id": _gen_id("req"),
            "tenant_id": tenant_row.get("id") if tenant_row else None,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now.isoformat(),
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()

    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{26}$", tenant_id):
        _log({"id": tenant_id}, "update_group", "error", started, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid tenant_id format.")
    if not isinstance(group_id, int) or group_id < 1:
        tenants = _load("tenants.json")
        trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id}
        _log(trow, "update_group", "error", started, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "group_id must be an integer >= 1.")
    if not isinstance(body, dict):
        tenants = _load("tenants.json")
        trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id}
        _log(trow, "update_group", "error", started, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "body must be an object.")

    allowed = {"name", "description", "auto_ticket_assign", "escalate_to", "unassigned_for", "business_hour_id", "members"}
    unknown = [k for k in body.keys() if k not in allowed]
    if unknown:
        tenants = _load("tenants.json")
        trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id}
        _log(trow, "update_group", "error", started, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "body contains unknown properties.", unknown_properties=unknown)

    for skey in ("name", "description"):
        if skey in body and body[skey] is not None and not isinstance(body[skey], str):
            tenants = _load("tenants.json")
            trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id}
            _log(trow, "update_group", "error", started, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{skey} must be a string.")
    if "auto_ticket_assign" in body and not isinstance(body["auto_ticket_assign"], bool):
        tenants = _load("tenants.json")
        trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id}
        _log(trow, "update_group", "error", started, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "auto_ticket_assign must be boolean.")
    for ikey, minv in (("escalate_to", 1), ("business_hour_id", 1)):
        if ikey in body:
            if not isinstance(body[ikey], int) or body[ikey] < minv:
                tenants = _load("tenants.json")
                trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id}
                _log(trow, "update_group", "error", started, {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"{ikey} must be an integer >= {minv}.")
    if "unassigned_for" in body:
        if not isinstance(body["unassigned_for"], int) or body["unassigned_for"] < 0:
            tenants = _load("tenants.json")
            trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id}
            _log(trow, "update_group", "error", started, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "unassigned_for must be an integer >= 0.")
    if "members" in body:
        if body["members"] is not None:
            if not isinstance(body["members"], list) or any((not isinstance(x, int) or x < 1) for x in body["members"]):
                tenants = _load("tenants.json")
                trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id}
                _log(trow, "update_group", "error", started, {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "members must be an array of integers >= 1.")

    tenants = _load("tenants.json")
    tenant = _get_tenant(tenants, tenant_id)
    if tenant is None:
        _log({"id": tenant_id}, "update_group", "error", started, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Tenant not found.")
    if not _has_valid_creds(tenant):
        _log(tenant, "update_group", "error", started, {"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Tenant has no valid Freshdesk credentials.")

    # Rate limit (per minute) based on existing request logs
    logs = _load("request_logs.json")
    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if r.get("tenant_id") != tenant_id:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if dt >= window_start:
            recent += 1
    if recent >= int(tenant.get("rate_limit_per_minute") or 60):
        _log(tenant, "update_group", "error", started, {"error_code": "RATE_LIMIT"})
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Groups are cached in people_and_orgs as entity_type='group'
    pao = _load("people_and_orgs.json")
    target = None
    for r in pao:
        if r.get("tenant_id") == tenant_id and r.get("entity_type") == "group" and r.get("freshdesk_id") == group_id:
            target = r
            break
    if target is None or target.get("status") == "deleted":
        _log(tenant, "update_group", "error", started, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Group not found.")

    if target.get("freshdesk_id") is None:
        _log(tenant, "update_group", "error", started, {"error_code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "Cannot update a group that has not been created upstream (freshdesk_id is null).")

    now_iso = _now_iso()
    raw = target.get("raw") if isinstance(target.get("raw"), dict) else {}

    if "name" in body:
        target["name"] = body["name"]
        raw["name"] = body["name"]
    if "description" in body:
        raw["description"] = body["description"]
    if "auto_ticket_assign" in body:
        raw["auto_ticket_assign"] = body["auto_ticket_assign"]
    if "escalate_to" in body:
        raw["escalate_to"] = body["escalate_to"]
    if "unassigned_for" in body:
        raw["unassigned_for"] = body["unassigned_for"]
    if "business_hour_id" in body:
        raw["business_hour_id"] = body["business_hour_id"]
    if "members" in body:
        raw["members"] = body["members"]

    # Update search_text
    st_parts = []
    if target.get("name"):
        st_parts.append(str(target.get("name")))
    if isinstance(raw.get("description"), str) and raw.get("description"):
        st_parts.append(raw.get("description"))
    target["search_text"] = " ".join(st_parts).lower() if st_parts else target.get("search_text")

    target["raw"] = raw
    target["updated_at"] = now_iso
    target["last_synced_at"] = now_iso

    _save("people_and_orgs.json", pao)
    _log(tenant, "update_group", "ok", started)

    out = dict(target.get("raw") if isinstance(target.get("raw"), dict) else {})
    out.setdefault("id", target.get("freshdesk_id"))
    if target.get("name") is not None:
        out["name"] = target.get("name")
    return {"group": out}

