        now = datetime.datetime.now(datetime.timezone.utc)
        latency_ms = int(max(0, (time.time() - started_at) * 1000))
        row = {
            "id": _gen_id("req"),
            "tenant_id": tenant_row.get("id") if tenant_row else None,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now.isoformat(),
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()

    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{26}$", tenant_id):
        _log({"id": tenant_id}, "list_contact_fields", "error", started, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid tenant_id format.")

    if page is not None:
        if not isinstance(page, int) or page < 1:
            tenants = _load("tenants.json")
            trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id}
            _log(trow, "list_contact_fields", "error", started, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if per_page is not None:
        if not isinstance(per_page, int) or per_page < 1 or per_page > 100:
            tenants = _load("tenants.json")
            trow = _get_tenant(tenants, tenant_id) or {"id": tenant_id}
            _log(trow, "list_contact_fields", "error", started, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "per_page must be an integer between 1 and 100.")

    tenants = _load("tenants.json")
    tenant = _get_tenant(tenants, tenant_id)
    if tenant is None:
        _log({"id": tenant_id}, "list_contact_fields", "error", started, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Tenant not found.")
    if not _has_valid_creds(tenant):
        _log(tenant, "list_contact_fields", "error", started, {"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Tenant has no valid Freshdesk credentials.")

    # Rate limit check based on existing logs
    logs = _load("request_logs.json")
    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if r.get("tenant_id") != tenant_id:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if dt >= window_start:
            recent += 1
    if recent >= int(tenant.get("rate_limit_per_minute") or 60):
        _log(tenant, "list_contact_fields", "error", started, {"error_code": "RATE_LIMIT"})
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    fields = _load("custom_fields.json")
    rows = []
    for f in fields:
        if f.get("tenant_id") != tenant_id:
            continue
        if f.get("field_scope") != "contact":
            continue
        if f.get("status") == "deleted":
            continue
        rows.append(f)

    # Sort by position then name
    def _pos(x):
        p = x.get("position")
        return p if isinstance(p, int) else 10**9

    rows.sort(key=lambda x: (_pos(x), (x.get("name") or "").lower(), x.get("freshdesk_id") or 0))

    # Pagination
    if per_page is None:
        per_page = int(tenant.get("default_page_size") or 25)
        if per_page < 1:
            per_page = 25
        if per_page > 100:
            per_page = 100
    if page is None:
        page = 1

    total = len(rows)
    start = (page - 1) * per_page
    end = start + per_page
    page_rows = rows[start:end]
    has_more = end < total

    # Return Freshdesk-like objects based on raw/properties
    out = []
    for r in page_rows:
        obj = dict(r.get("raw") if isinstance(r.get("raw"), dict) else {})
        if r.get("freshdesk_id") is not None:
            obj.setdefault("id", r.get("freshdesk_id"))
        obj.setdefault("name", r.get("name"))
        if r.get("label") is not None:
            obj.setdefault("label", r.get("label"))
        if r.get("field_type") is not None:
            obj.setdefault("type", r.get("field_type"))
        if r.get("required") is not None:
            obj.setdefault("required", r.get("required"))
        if r.get("position") is not None:
            obj.setdefault("position", r.get("position"))
        if isinstance(r.get("properties"), dict):
            for k, v in r["properties"].items():
                obj.setdefault(k, v)
        out.append(obj)

    _log(tenant, "list_contact_fields", "ok", started)

    return {
        "contact_fields": out,
        "meta": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "has_more": has_more,
            "total_pages": int(math.ceil(total / float(per_page))) if per_page else 0,
        },
    }

