        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_contact_field"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, tenant_row=None, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
                "credential_type": (tenant_row.get("auth_type") if isinstance(tenant_row, dict) else None),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now_iso(),
                **({"error": error} if error is not None else {}),
                **({"meta": meta} if meta is not None else {}),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _tenant_has_creds(t):
        if not isinstance(t, dict):
            return False
        if t.get("status") != "active":
            return False
        at = t.get("auth_type")
        if at == "api_key":
            return bool(t.get("api_key_ciphertext"))
        if at == "oauth":
            return bool(t.get("oauth_access_token_ciphertext"))
        return False

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _enforce_rate_limit(tenant_row):
        rpm = tenant_row.get("rate_limit_per_minute")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= cutoff:
                count += 1
        if count >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=rpm)
        return None

    def _gen_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(alphabet[b % 32] for b in os.urandom(26))

    try:
        if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
            e = _err("VALIDATION_ERROR", "tenant_id is malformed.", field="tenant_id")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(field, dict):
            e = _err("VALIDATION_ERROR", "field must be an object.", field="field")
            _append_log("error", error=e["error"])
            return e

        for req in ("name", "label", "field_type"):
            if req not in field:
                e = _err("VALIDATION_ERROR", f"field.{req} is required.", field=f"field.{req}")
                _append_log("error", error=e["error"])
                return e

        fname = field.get("name")
        if not isinstance(fname, str) or not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", fname or ""):
            e = _err("VALIDATION_ERROR", "field.name must match regex ^[a-zA-Z_][a-zA-Z0-9_]*$.", field="field.name")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(field.get("label"), str) or not field.get("label").strip():
            e = _err("VALIDATION_ERROR", "field.label must be a non-empty string.", field="field.label")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(field.get("field_type"), str) or not field.get("field_type").strip():
            e = _err("VALIDATION_ERROR", "field.field_type must be a non-empty string.", field="field.field_type")
            _append_log("error", error=e["error"])
            return e
        if "required" in field and field.get("required") is not None and not isinstance(field.get("required"), bool):
            e = _err("VALIDATION_ERROR", "field.required must be a boolean.", field="field.required")
            _append_log("error", error=e["error"])
            return e
        if "properties" in field and field.get("properties") is not None and not isinstance(field.get("properties"), dict):
            e = _err("VALIDATION_ERROR", "field.properties must be an object.", field="field.properties")
            _append_log("error", error=e["error"])
            return e
        if "position" in field and field.get("position") is not None and (not isinstance(field.get("position"), int) or isinstance(field.get("position"), bool)):
            e = _err("VALIDATION_ERROR", "field.position must be an integer.", field="field.position")
            _append_log("error", error=e["error"])
            return e

        tenants = _load("tenants.json")
        if not isinstance(tenants, list):
            tenants = []
        tenant_row = None
        for t in tenants:
            if isinstance(t, dict) and t.get("id") == tenant_id and t.get("status") != "deleted":
                tenant_row = t
                break
        if tenant_row is None:
            e = _err("NOT_FOUND", "Tenant not found.")
            _append_log("error", error=e["error"])
            return e

        if not _tenant_has_creds(tenant_row):
            e = _err("UNAUTHORIZED", "Tenant Freshdesk credentials are missing/invalid.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        rl = _enforce_rate_limit(tenant_row)
        if rl:
            _append_log("error", tenant_row=tenant_row, error=rl["error"])
            return rl

        fields = _load("custom_fields.json")
        if not isinstance(fields, list):
            fields = []

        # Enforce unique(tenant_id, field_scope, name)
        for r in fields:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") == tenant_id and r.get("field_scope") == "contact" and r.get("name") == fname:
                if r.get("status") != "deleted":
                    e = _err("CONFLICT", "A contact field with this name already exists for this tenant.", field="field.name")
                    _append_log("error", tenant_row=tenant_row, error=e["error"])
                    return e

        now = _now_iso()
        new_row = {
            "id": _gen_ulid_like("fdcf"),
            "tenant_id": tenant_id,
            "field_scope": "contact",
            "status": "active",
            "freshdesk_id": None,
            "name": fname,
            "label": field.get("label"),
            "field_type": field.get("field_type"),
            "required": field.get("required"),
            "properties": field.get("properties") if isinstance(field.get("properties"), dict) else {},
            "position": field.get("position"),
            "last_synced_at": now,
            "created_at": now,
            "updated_at": now,
        }

        # As per create_* rules, stage locally with freshdesk_id=null and properties/raw payload stored
        # custom_fields schema stores properties; keep request payload in properties for traceability
        new_row["properties"] = {**(new_row["properties"] if isinstance(new_row["properties"], dict) else {}), **{"_request": field}}

        fields.append(new_row)
        _save("custom_fields.json", fields)

        _append_log("ok", tenant_row=tenant_row, meta={"created": True})
        return {"field": new_row}
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(ex))
        _append_log("error", error=e["error"])
        return e

def update_contact_field(tenant_id, field_id, field, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_contact_field"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, tenant_row=None, message=None, meta=None):
        try:
            import secrets
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
                "credential_type": (tenant_row.get("auth_type") if isinstance(tenant_row, dict) else None),
                "status": status,
                "message": message,
                "meta": meta or {},
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now()
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _tenant_ok(ten):
        if not isinstance(ten, dict):
            return False
        if ten.get("status") != "active":
            return False
        at = ten.get("auth_type")
        if at == "api_key":
            return ten.get("api_key_ciphertext") is not None
        if at == "oauth":
            return ten.get("oauth_access_token_ciphertext") is not None
        return False

    def _enforce_rate_limit(ten):
        try:
            rpm = ten.get("rate_limit_per_minute")
            if not isinstance(rpm, int) or rpm < 1:
                return None
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return None
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            c = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("tenant_id") != ten.get("id"):
                    continue
                ts = r.get("ts")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded for tenant", limit_per_minute=rpm)
            return None
        except Exception:
            return None

    # Validate inputs
    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        _log("error", None, "invalid tenant_id")
        return _err("VALIDATION_ERROR", "tenant_id is invalid")
    if not isinstance(field_id, str) or not re.match(r"^fdfld_[0-9A-HJKMNP-TV-Z]{10,}$", field_id):
        _log("error", None, "invalid field_id")
        return _err("VALIDATION_ERROR", "field_id is invalid")
    if not isinstance(field, dict):
        _log("error", None, "invalid field body")
        return _err("VALIDATION_ERROR", "field must be an object")

    allowed = {"label", "required", "properties", "position", "status"}
    for k in field.keys():
        if k not in allowed:
            _log("error", None, "unknown property", {"key": k})
            return _err("VALIDATION_ERROR", "field has unknown property", property=k)

    if "label" in field and field["label"] is not None and (not isinstance(field["label"], str) or not field["label"].strip()):
        _log("error", None, "invalid label")
        return _err("VALIDATION_ERROR", "field.label must be a non-empty string when provided")
    if "required" in field and field["required"] is not None and not isinstance(field["required"], bool):
        _log("error", None, "invalid required")
        return _err("VALIDATION_ERROR", "field.required must be boolean when provided")
    if "properties" in field and field["properties"] is not None and not isinstance(field["properties"], dict):
        _log("error", None, "invalid properties")
        return _err("VALIDATION_ERROR", "field.properties must be an object when provided")
    if "position" in field and field["position"] is not None and not isinstance(field["position"], int):
        _log("error", None, "invalid position")
        return _err("VALIDATION_ERROR", "field.position must be an integer when provided")
    if "status" in field and field["status"] is not None:
        if field["status"] not in ("active", "disabled", "deleted"):
            _log("error", None, "invalid status")
            return _err("VALIDATION_ERROR", "field.status is invalid", allowed=["active", "disabled", "deleted"])

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if tenant_row is None:
        _log("error", None, "tenant not found")
        return _err("NOT_FOUND", "Tenant not found", tenant_id=tenant_id)

    if not _tenant_ok(tenant_row):
        _log("error", tenant_row, "unauthorized")
        return _err("UNAUTHORIZED", "Tenant has no valid Freshdesk credentials or is not active")

    rl = _enforce_rate_limit(tenant_row)
    if rl:
        _log("error", tenant_row, rl["error"]["message"])
        return rl

    fields = _load("custom_fields.json")
    if not isinstance(fields, list):
        fields = []

    idx = None
    row = None
    for i, r in enumerate(fields):
        if isinstance(r, dict) and r.get("id") == field_id and r.get("tenant_id") == tenant_id and r.get("field_scope") == "contact":
            idx = i
            row = r
            break
    if row is None:
        _log("error", tenant_row, "field not found", {"field_id": field_id})
        return _err("NOT_FOUND", "Contact field not found", field_id=field_id)

    # Update tools require the upstream object to exist
    if row.get("freshdesk_id") is None:
        _log("error", tenant_row, "cannot update unsynced field", {"field_id": field_id})
        return _err("INVALID_TRANSITION", "Cannot update a field that has not been created upstream (freshdesk_id is null)", field_id=field_id)

    # Enforce lifecycle transitions
    if "status" in field and field["status"] is not None:
        cur = row.get("status")
        nxt = field["status"]
        transitions = {
            "active": ["disabled", "deleted"],
            "disabled": ["active", "deleted"],
            "deleted": []
        }
        if cur not in transitions or nxt not in ("active", "disabled", "deleted"):
            _log("error", tenant_row, "invalid lifecycle values", {"current": cur, "next": nxt})
            return _err("VALIDATION_ERROR", "Invalid status value")
        if nxt != cur and nxt not in transitions.get(cur, []):
            _log("error", tenant_row, "invalid transition", {"current": cur, "next": nxt})
            return _err("INVALID_TRANSITION", "Illegal status transition", current=cur, next=nxt)

    # Apply updates
    now = _now()
    if "label" in field:
        row["label"] = field["label"]
    if "required" in field:
        row["required"] = field["required"]
    if "properties" in field:
        row["properties"] = field["properties"] if field["properties"] is not None else {}
    if "position" in field:
        row["position"] = field["position"]
    if "status" in field and field["status"] is not None:
        row["status"] = field["status"]

    # Refresh raw/last_synced_at to reflect upstream update (offline server: treat as succeeded)
    # Keep properties non-null as per schema
    if row.get("properties") is None or not isinstance(row.get("properties"), dict):
        row["properties"] = {}
    row["last_synced_at"] = now
    row["updated_at"] = now

    fields[idx] = row
    _save("custom_fields.json", fields)

    _log("ok", tenant_row, None, {"field_id": field_id, "freshdesk_id": row.get("freshdesk_id")})
    return {"contact_field": row}

