                ts = r.get("ts")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded for tenant", limit_per_minute=rpm)
            return None
        except Exception:
            return None

    def _decode_cursor(c):
        # Cursor is base64url(json) with {"i": start_index}
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            raise ValueError("cursor must be a non-empty string")
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
        except Exception:
            raise ValueError("malformed cursor")
        if not isinstance(obj, dict) or "i" not in obj:
            raise ValueError("malformed cursor payload")
        i = obj["i"]
        if not isinstance(i, int) or i < 0:
            raise ValueError("malformed cursor index")
        return i

    def _encode_cursor(i):
        payload = json.dumps({"i": i}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Validate tenant_id
    if not isinstance(tenant_id, str) or not re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        _log("error", None, "invalid tenant_id")
        return _err("VALIDATION_ERROR", "tenant_id is invalid")

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if tenant_row is None:
        _log("error", None, "tenant not found")
        return _err("NOT_FOUND", "Tenant not found", tenant_id=tenant_id)

    if not _tenant_ok(tenant_row):
        _log("error", tenant_row, "unauthorized")
        return _err("UNAUTHORIZED", "Tenant has no valid Freshdesk credentials or is not active")

    rl = _enforce_rate_limit(tenant_row)
    if rl:
        _log("error", tenant_row, rl["error"]["message"])
        return rl

    # Defaults
    if limit is None:
        dp = tenant_row.get("default_page_size")
        limit = dp if isinstance(dp, int) else 25
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", tenant_row, "invalid limit", {"limit": limit})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    if sort is None:
        sort = "updated_at"
    if sort not in ("created_at", "updated_at", "name"):
        _log("error", tenant_row, "invalid sort", {"sort": sort})
        return _err("VALIDATION_ERROR", "sort is invalid", allowed=["created_at", "updated_at", "name"])

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _log("error", tenant_row, "invalid order", {"order": order})
        return _err("VALIDATION_ERROR", "order is invalid", allowed=["asc", "desc"])

    # Cursor
    try:
        start = _decode_cursor(cursor)
    except ValueError as e:
        _log("error", tenant_row, str(e))
        return _err("VALIDATION_ERROR", "cursor is invalid")

    rows = _load("people_and_orgs.json")
    if not isinstance(rows, list):
        rows = []

    # Filter by tenant_id, entity_type=company, and exclude status='deleted' by default
    companies = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") != tenant_id:
            continue
        if r.get("entity_type") != "company":
            continue
        if r.get("status") == "deleted":
            continue
        companies.append(r)

    total = len(companies)

    def _sort_key(r):
        v = r.get(sort)
        if sort in ("created_at", "updated_at"):
            if isinstance(v, str):
                return v
            return ""
        if sort == "name":
            n = r.get("name")
            return (n or "").casefold()
        return ""

    reverse = (order == "desc")
    companies.sort(key=_sort_key, reverse=reverse)

    if start > total:
        # Cursor beyond end: return empty page but not error
        page = []
        has_more = False
        next_cursor = None
    else:
        page = companies[start:start + limit]
        next_index = start + len(page)
        has_more = next_index < total
        next_cursor = _encode_cursor(next_index) if has_more else None

    _log("ok", tenant_row, None, {"returned": len(page), "total": total, "has_more": has_more})
    return {
        "companies": page,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total
        },
        "sort": {"field": sort, "order": order}
    }

