        row = {
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
            "endpoint": "search_companies",
            "credential_id": None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _validate_tenant_id(x):
        return isinstance(x, str) and re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{10,}$", x or "") is not None

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c.strip():
            raise ValueError("malformed cursor")
        try:
            raw = base64.urlsafe_b64decode(c.encode("ascii") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("off:"):
                raise ValueError("malformed cursor")
            off = int(s.split(":", 1)[1])
            if off < 0:
                raise ValueError("malformed cursor")
            return off
        except Exception:
            raise ValueError("malformed cursor")

    def _encode_cursor(off):
        s = f"off:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("ascii").rstrip("=")

    # Validate inputs
    if not _validate_tenant_id(tenant_id):
        _log("VALIDATION_ERROR", meta={"field": "tenant_id"})
        return _err("VALIDATION_ERROR", "Invalid tenant_id format.", field="tenant_id")
    if not isinstance(query, str) or not query.strip():
        _log("VALIDATION_ERROR", meta={"field": "query"})
        return _err("VALIDATION_ERROR", "query must be a non-empty string.", field="query")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("VALIDATION_ERROR", meta={"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
    try:
        offset = _decode_cursor(cursor)
    except ValueError:
        _log("VALIDATION_ERROR", meta={"field": "cursor"})
        return _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")

    tenants = _load("tenants.json")
    if not isinstance(tenants, list):
        tenants = []
    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if tenant is None or tenant.get("status") != "active":
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant connection missing or invalid.")

    auth_type = tenant.get("auth_type")
    if auth_type == "api_key":
        if not tenant.get("api_key_ciphertext"):
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tenant connection missing or invalid.")
    elif auth_type == "oauth":
        if not tenant.get("oauth_access_token_ciphertext"):
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tenant connection missing or invalid.")
    else:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant connection missing or invalid.")

    # Rate limit per minute
    rate_limit = tenant.get("rate_limit_per_minute")
    if not isinstance(rate_limit, int) or rate_limit < 1:
        rate_limit = 60
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = (datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60))
    cnt = 0
    for r in logs:
        if not isinstance(r, dict): 
            continue
        if r.get("tenant_id") != tenant_id:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if dt >= window_start:
            cnt += 1
    if cnt >= rate_limit:
        _log("RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=rate_limit)

    q = query.strip().lower()

    people = _load("people_and_orgs.json")
    if not isinstance(people, list):
        people = []

    def _hay(p):
        st = p.get("search_text")
        if isinstance(st, str) and st:
            return st.lower()
        parts = []
        nm = p.get("name")
        if isinstance(nm, str): parts.append(nm)
        em = p.get("email")
        if isinstance(em, str): parts.append(em)
        ph = p.get("phone")
        if isinstance(ph, str): parts.append(ph)
        raw = p.get("raw")
        if isinstance(raw, dict):
            for k in ("name", "domains", "description", "note", "industry", "website", "phone"):
                v = raw.get(k)
                if isinstance(v, str):
                    parts.append(v)
                elif isinstance(v, list):
                    parts.extend([x for x in v if isinstance(x, str)])
        return " ".join(parts).lower()

    matches = []
    for p in people:
        if not isinstance(p, dict):
            continue
        if p.get("tenant_id") != tenant_id:
            continue
        if p.get("entity_type") != "company":
            continue
        if p.get("status") == "deleted":
            continue
        if q in _hay(p):
            matches.append(p)

    # Deterministic sort: by name then freshdesk_id
    def _key(p):
        nm = p.get("name")
        if not isinstance(nm, str):
            nm = ""
        fid = p.get("freshdesk_id")
        if not isinstance(fid, int):
            fid = 0
        return (nm.lower(), fid, p.get("id") or "")
    matches.sort(key=_key)

    total = len(matches)
    page = matches[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    _log("OK", meta={"total": total, "returned": len(page), "offset": offset})
    return {
        "companies": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "cursor": cursor,
        },
    }

def find_company_by_name(tenant_id, name, **_extra):
    import json, os, datetime, re, time, difflib, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "find_company_by_name"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _append_log(status, tenant_row=None, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
                "credential_type": (tenant_row.get("auth_type") if isinstance(tenant_row, dict) else None),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now_iso(),
                **({"error": error} if error is not None else {}),
                **({"meta": meta} if meta is not None else {}),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _tenant_has_creds(t):
        if not isinstance(t, dict):
            return False
        if t.get("status") != "active":
            return False
        at = t.get("auth_type")
        if at == "api_key":
            return bool(t.get("api_key_ciphertext"))
        if at == "oauth":
            return bool(t.get("oauth_access_token_ciphertext"))
        return False

    def _enforce_rate_limit(tenant_row):
        rpm = tenant_row.get("rate_limit_per_minute")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_row.get("id"):
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= cutoff:
                count += 1
        if count >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant.", limit_per_minute=rpm)
        return None

    try:
        if not isinstance(tenant_id, str) or re.match(r"^fdten_[0-9A-Z]{10,}$", tenant_id) is None:
            e = _err("VALIDATION_ERROR", "tenant_id is malformed.", field="tenant_id")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(name, str) or not name.strip():
            e = _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
            _append_log("error", error=e["error"])
            return e

        tenants = _load("tenants.json")
        if not isinstance(tenants, list):
            tenants = []
        tenant_row = None
        for t in tenants:
            if isinstance(t, dict) and t.get("id") == tenant_id and t.get("status") != "deleted":
                tenant_row = t
                break
        if tenant_row is None:
            e = _err("NOT_FOUND", "Tenant not found.")
            _append_log("error", error=e["error"])
            return e
        if not _tenant_has_creds(tenant_row):
            e = _err("UNAUTHORIZED", "Tenant Freshdesk credentials are missing/invalid.")
            _append_log("error", tenant_row=tenant_row, error=e["error"])
            return e

        rl = _enforce_rate_limit(tenant_row)
        if rl:
            _append_log("error", tenant_row=tenant_row, error=rl["error"])
            return rl

        ents = _load("people_and_orgs.json")
        if not isinstance(ents, list):
            ents = []

        q = name.strip().lower()

        companies = []
        for r in ents:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_id or r.get("entity_type") != "company" or r.get("status") == "deleted":
                continue
            nm = r.get("name") or ""
            if isinstance(nm, str):
                companies.append((nm, r))

        # exact match first
        for nm, r in companies:
            if nm.strip().lower() == q:
                _append_log("ok", tenant_row=tenant_row, meta={"match": "exact"})
                return {"company": r}

        # near match using difflib ratio
        best = None
        best_score = 0.0
        for nm, r in companies:
            score = difflib.SequenceMatcher(None, q, nm.strip().lower()).ratio()
            if score > best_score:
                best_score = score
                best = r
        if best is None or best_score < 0.75:
            e = _err("NOT_FOUND", "No matching company found.")
            _append_log("error", tenant_row=tenant_row, error=e["error"], meta={"best_score": best_score})
            return e

        _append_log("ok", tenant_row=tenant_row, meta={"match": "fuzzy", "score": best_score})
        return {"company": best, "match_score": best_score}
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(ex))
        _append_log("error", error=e["error"])
        return e

