            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _validate_tenant_id(x):
        return isinstance(x, str) and re.match(r"^fdten_[0-9A-HJKMNP-TV-Z]{10,}$", x or "") is not None

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c.strip():
            raise ValueError("malformed cursor")
        try:
            raw = base64.urlsafe_b64decode(c.encode("ascii") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("off:"):
                raise ValueError("malformed cursor")
            off = int(s.split(":", 1)[1])
            if off < 0:
                raise ValueError("malformed cursor")
            return off
        except Exception:
            raise ValueError("malformed cursor")

    def _encode_cursor(off):
        s = f"off:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("ascii").rstrip("=")

    # Validate inputs
    if not _validate_tenant_id(tenant_id):
        _log("VALIDATION_ERROR", meta={"field": "tenant_id"})
        return _err("VALIDATION_ERROR", "Invalid tenant_id format.", field="tenant_id")

    allowed_status = {"active", "disabled", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("VALIDATION_ERROR", meta={"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status value.", field="status", allowed=sorted(list(allowed_status)))

    if limit is None:
        limit = 200
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", meta={"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    try:
        offset = _decode_cursor(cursor)
    except ValueError:
        _log("VALIDATION_ERROR", meta={"field": "cursor"})
        return _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")

    tenants = _load("tenants.json")
    if not isinstance(tenants, list):
        tenants = []
    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if tenant is None or tenant.get("status") != "active":
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant connection missing or invalid.")

    auth_type = tenant.get("auth_type")
    if auth_type == "api_key":
        if not tenant.get("api_key_ciphertext"):
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tenant connection missing or invalid.")
    elif auth_type == "oauth":
        if not tenant.get("oauth_access_token_ciphertext"):
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tenant connection missing or invalid.")
    else:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant connection missing or invalid.")

    # Rate limit per minute
    rate_limit = tenant.get("rate_limit_per_minute")
    if not isinstance(rate_limit, int) or rate_limit < 1:
        rate_limit = 60
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = (datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60))
    cnt = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") != tenant_id:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if dt >= window_start:
            cnt += 1
    if cnt >= rate_limit:
        _log("RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=rate_limit)

    fields = _load("custom_fields.json")
    if not isinstance(fields, list):
        fields = []

    rows = []
    for f in fields:
        if not isinstance(f, dict):
            continue
        if f.get("tenant_id") != tenant_id:
            continue
        if f.get("field_scope") != "company":
            continue
        if status is not None:
            if f.get("status") != status:
                continue
        else:
            # default exclude deleted
            if f.get("status") == "deleted":
                continue
        rows.append(f)

    # Sort by position (nulls last), then name
    def _key(f):
        pos = f.get("position")
        pos_key = pos if isinstance(pos, int) else 10**9
        nm = f.get("name")
        nm_key = nm.lower() if isinstance(nm, str) else ""
        fid = f.get("freshdesk_id")
        fid_key = fid if isinstance(fid, int) else 0
        return (pos_key, nm_key, fid_key, f.get("id") or "")
    rows.sort(key=_key)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    _log("OK", meta={"total": total, "returned": len(page), "offset": offset, "filter_status": status})
    return {
        "fields": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "cursor": cursor,
        },
    }

def create_tenant(name, freshdesk_domain, freshdesk_api_base_url, auth_type, api_key=None, oauth_access_token=None, oauth_refresh_token=None, oauth_token_expires_at=None, default_page_size=None, rate_limit_per_minute=None, **_extra):
    import json, os, datetime, re, time, secrets, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_tenant"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, error=None, meta=None, tenant_row=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "tenant_id": (tenant_row or {}).get("id") if isinstance(tenant_row, dict) else None,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now_iso(),
                **({"error": error} if error is not None else {}),
                **({"meta": meta} if meta is not None else {}),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _gen_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(alphabet[b % 32] for b in os.urandom(26))

    def _is_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u.strip())
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _norm_domain(d):
        d = (d or "").strip().lower()
        if d.startswith("https://") or d.startswith("http://"):
            try:
                d = urllib.parse.urlparse(d).netloc.lower()
            except Exception:
                pass
        if d.endswith("/"):
            d = d[:-1]
        if "." in d:
            return d.split(".")[0]
        return d

    def _parse_dt(s):
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            s = s.strip()
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        except Exception:
            return None

    try:
        if not isinstance(name, str) or not name.strip():
            e = _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(freshdesk_domain, str) or not freshdesk_domain.strip():
            e = _err("VALIDATION_ERROR", "freshdesk_domain must be a non-empty string.", field="freshdesk_domain")
            _append_log("error", error=e["error"])
            return e
        if not isinstance(freshdesk_api_base_url, str) or not freshdesk_api_base_url.strip() or not _is_url(freshdesk_api_base_url):
            e = _err("VALIDATION_ERROR", "freshdesk_api_base_url must be a valid http(s) URL.", field="freshdesk_api_base_url")
            _append_log("error", error=e["error"])
            return e
        if auth_type not in ("api_key", "oauth"):
            e = _err("VALIDATION_ERROR", "auth_type must be one of: api_key, oauth.", field="auth_type")
            _append_log("error", error=e["error"])
            return e
        if default_page_size is not None:
            if not isinstance(default_page_size, int) or isinstance(default_page_size, bool) or not (1 <= default_page_size <= 100):
                e = _err("VALIDATION_ERROR", "default_page_size must be an integer between 1 and 100.", field="default_page_size")
                _append_log("error", error=e["error"])
                return e
        if rate_limit_per_minute is not None:
            if not isinstance(rate_limit_per_minute, int) or isinstance(rate_limit_per_minute, bool) or not (1 <= rate_limit_per_minute <= 600):
                e = _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer between 1 and 600.", field="rate_limit_per_minute")
                _append_log("error", error=e["error"])
                return e

        norm = _norm_domain(freshdesk_domain)
        if not norm or not re.match(r"^[a-z0-9][a-z0-9-]{0,61}[a-z0-9]?$", norm):
            e = _err("VALIDATION_ERROR", "freshdesk_domain is invalid.", field="freshdesk_domain")
            _append_log("error", error=e["error"])
            return e

        # normalize api base url: store .../api/v2
        base = freshdesk_api_base_url.strip().rstrip("/")
        if base.endswith("/api/v2"):
            api_base = base
        else:
            api_base = base + "/api/v2"

        # auth requirements
        if auth_type == "api_key":
            if not isinstance(api_key, str) or not api_key.strip():
                e = _err("VALIDATION_ERROR", "api_key is required when auth_type='api_key'.", field="api_key")
                _append_log("error", error=e["error"])
                return e
        if auth_type == "oauth":
            if not isinstance(oauth_access_token, str) or not oauth_access_token.strip():
                e = _err("VALIDATION_ERROR", "oauth_access_token is required when auth_type='oauth'.", field="oauth_access_token")
                _append_log("error", error=e["error"])
                return e
            if not isinstance(oauth_refresh_token, str) or not oauth_refresh_token.strip():
                e = _err("VALIDATION_ERROR", "oauth_refresh_token is required when auth_type='oauth'.", field="oauth_refresh_token")
                _append_log("error", error=e["error"])
                return e
            expires = _parse_dt(oauth_token_expires_at)
            if expires is None:
                e = _err("VALIDATION_ERROR", "oauth_token_expires_at must be a valid RFC3339 date-time.", field="oauth_token_expires_at")
                _append_log("error", error=e["error"])
                return e

        tenants = _load("tenants.json")
        if not isinstance(tenants, list):
            tenants = []

        # conflict unique(freshdesk_domain)
        for t in tenants:
            if not isinstance(t, dict):
                continue
            if (t.get("freshdesk_domain") or "").lower() == norm and t.get("status") != "deleted":
                e = _err("CONFLICT", "A tenant with this freshdesk_domain already exists.", field="freshdesk_domain")
                _append_log("error", error=e["error"])
                return e

        now = _now_iso()
        tid = _gen_ulid_like("fdten")
        new_row = {
            "id": tid,
            "status": "active",
            "name": name.strip(),
            "freshdesk_domain": norm,
            "freshdesk_api_base_url": api_base,
            "auth_type": auth_type,
            "api_key_ciphertext": None,
            "oauth_access_token_ciphertext": None,
            "oauth_refresh_token_ciphertext": None,
            "oauth_token_expires_at": None,
            "default_page_size": default_page_size if default_page_size is not None else 25,
            "rate_limit_per_minute": rate_limit_per_minute if rate_limit_per_minute is not None else 60,
            "created_at": now,
            "updated_at": now,
        }

        # Store plaintext into *_ciphertext fields (offline/local store semantics)
        if auth_type == "api_key":
            new_row["api_key_ciphertext"] = api_key.strip()
        else:
            new_row["oauth_access_token_ciphertext"] = oauth_access_token.strip()
            new_row["oauth_refresh_token_ciphertext"] = oauth_refresh_token.strip()
            new_row["oauth_token_expires_at"] = expires

        tenants.append(new_row)
        _save("tenants.json", tenants)
        _append_log("ok", tenant_row=new_row, meta={"created": True})
        return {"tenant": new_row}
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(ex))
        _append_log("error", error=e["error"])
        return e

def update_tenant(tenant_id, name=None, freshdesk_domain=None, freshdesk_api_base_url=None, auth_type=None, api_key=None, oauth_access_token=None, oauth_refresh_token=None, oauth_token_expires_at=None, default_page_size=None, rate_limit_per_minute=None, status=None, **_extra):
    import json, os, datetime, re, time, secrets, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_s, t_id=None, error_code=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": "fdreq_" + secrets.token_hex(10).upper(),
            "endpoint": "update_tenant",
            "tenant_id": t_id,
            "credential_id": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)

    if not isinstance(tenant_id, str) or not re.fullmatch(r"^fdten_[0-9A-Z]{10,}$", tenant_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tenant_id is invalid")

    tenants = _load("tenants.json")
    idx = None
    for i, t in enumerate(tenants):
        if isinstance(t, dict) and t.get("id") == tenant_id:
            idx = i
            break
    if idx is None:
        _log("error", t_id=tenant_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Tenant not found", tenant_id=tenant_id)

    tenant = tenants[idx]
    old_status = tenant.get("status")

    # Validate and stage updates
    if name is not None:
        if not isinstance(name, str) or not name.strip():
            _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name must be a non-empty string")
        tenant["name"] = name.strip()

    # Domain update with uniqueness
    if freshdesk_domain is not None:
        if not isinstance(freshdesk_domain, str) or not freshdesk_domain.strip():
            _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "freshdesk_domain must be a non-empty string")
        dom = freshdesk_domain.strip().lower()
        if "." in dom:
            if not (dom.endswith(".freshdesk.com") or dom.endswith(".freshdesk.eu") or dom.endswith(".freshdesk.in") or dom.endswith(".freshdesk.co.uk") or dom.endswith(".freshdesk.de") or dom.endswith(".freshdesk.au") or dom.endswith(".freshdesk.jp") or dom.endswith(".freshdesk.sg")):
                _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "freshdesk_domain must be a subdomain (e.g., 'acme') or a Freshdesk domain ending with freshdesk.*")
            sub = dom.split(".")[0]
        else:
            sub = dom
        if not re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", sub):
            _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "freshdesk_domain subdomain is invalid")

        for t in tenants:
            if t.get("id") != tenant_id and t.get("freshdesk_domain", "").lower() == sub and t.get("status") != "deleted":
                _log("error", t_id=tenant_id, error_code="CONFLICT")
                return _err("CONFLICT", "A tenant with the same freshdesk_domain already exists", freshdesk_domain=sub)

        tenant["freshdesk_domain"] = sub

    if freshdesk_api_base_url is not None:
        if not isinstance(freshdesk_api_base_url, str) or not freshdesk_api_base_url.strip():
            _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "freshdesk_api_base_url must be a non-empty string")
        base = freshdesk_api_base_url.strip()
        try:
            u = urllib.parse.urlparse(base)
        except Exception:
            _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "freshdesk_api_base_url must be a valid URL")
        if u.scheme not in ("https", "http") or not u.netloc:
            _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "freshdesk_api_base_url must include scheme and host (e.g., https://acme.freshdesk.com)")
        norm_host = u.netloc.lower()
        if norm_host.startswith("www."):
            norm_host = norm_host[4:]
        # If tenant has domain set, try to keep consistent
        sub = tenant.get("freshdesk_domain")
        if isinstance(sub, str) and sub and not norm_host.startswith(sub.lower() + "."):
            _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "freshdesk_api_base_url host does not match tenant freshdesk_domain")
        tenant["freshdesk_api_base_url"] = f"{u.scheme}://{norm_host}/api/v2"

    if default_page_size is not None:
        if not isinstance(default_page_size, int) or not (1 <= default_page_size <= 100):
            _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "default_page_size must be an integer between 1 and 100")
        tenant["default_page_size"] = default_page_size

    if rate_limit_per_minute is not None:
        if not isinstance(rate_limit_per_minute, int) or not (1 <= rate_limit_per_minute <= 600):
            _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer between 1 and 600")
        tenant["rate_limit_per_minute"] = rate_limit_per_minute

    # Auth updates: allow changing auth_type; enforce implied fields
    if auth_type is not None:
        if auth_type not in ("api_key", "oauth"):
            _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "auth_type must be one of: api_key, oauth")
        tenant["auth_type"] = auth_type

    eff_auth_type = tenant.get("auth_type")
    if eff_auth_type == "api_key":
        if api_key is not None:
            if not isinstance(api_key, str) or not api_key.strip():
                _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
            tenant["api_key_ciphertext"] = api_key
        # if switching to api_key, api_key must exist
        if tenant.get("api_key_ciphertext") in (None, ""):
            _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "api_key is required when auth_type='api_key'")
        # redact oauth fields for api_key tenants
        tenant["oauth_access_token_ciphertext"] = None
        tenant["oauth_refresh_token_ciphertext"] = None
        tenant["oauth_token_expires_at"] = None
    elif eff_auth_type == "oauth":
        if oauth_access_token is not None:
            if not isinstance(oauth_access_token, str) or not oauth_access_token.strip():
                _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "oauth_access_token must be a non-empty string")
            tenant["oauth_access_token_ciphertext"] = oauth_access_token
        if oauth_refresh_token is not None:
            if not isinstance(oauth_refresh_token, str) or not oauth_refresh_token.strip():
                _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "oauth_refresh_token must be a non-empty string")
            tenant["oauth_refresh_token_ciphertext"] = oauth_refresh_token
        if oauth_token_expires_at is not None:
            if not isinstance(oauth_token_expires_at, str) or not oauth_token_expires_at.strip():
                _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "oauth_token_expires_at must be an ISO 8601 date-time string")
            try:
                dt = datetime.datetime.fromisoformat(oauth_token_expires_at.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                tenant["oauth_token_expires_at"] = dt.astimezone(datetime.timezone.utc).isoformat()
            except Exception:
                _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "oauth_token_expires_at must be an ISO 8601 date-time")
        # If switching to oauth, required fields must exist
        if tenant.get("oauth_access_token_ciphertext") in (None, "") or tenant.get("oauth_refresh_token_ciphertext") in (None, "") or tenant.get("oauth_token_expires_at") in (None, ""):
            _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "oauth_access_token, oauth_refresh_token, and oauth_token_expires_at are required when auth_type='oauth'")
        # redact api key field for oauth tenants
        tenant["api_key_ciphertext"] = None
    else:
        _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Tenant auth_type is invalid")

    # Status transition enforcement + redaction on delete
    if status is not None:
        if status not in ("active", "suspended", "deleted"):
            _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, suspended, deleted")
        transitions = {
            "active": ["suspended", "deleted"],
            "suspended": ["active", "deleted"],
            "deleted": []
        }
        if status != old_status:
            allowed = transitions.get(old_status, [])
            if status not in allowed:
                _log("error", t_id=tenant_id, error_code="INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", f"Illegal status transition from {old_status} to {status}", from_status=old_status, to_status=status)
            tenant["status"] = status
            if status == "deleted":
                # redact credentials on delete
                tenant["api_key_ciphertext"] = None
                tenant["oauth_access_token_ciphertext"] = None
                tenant["oauth_refresh_token_ciphertext"] = None
                tenant["oauth_token_expires_at"] = None

    tenant["updated_at"] = now
    tenants[idx] = tenant
    _save("tenants.json", tenants)
    _log("ok", t_id=tenant_id)

    return {"tenant": tenant}

def get_me(tenant_id=None, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, t_id=None, error_code=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": "fdreq_" + secrets.token_hex(10).upper(),
            "endpoint": "get_me",
            "tenant_id": t_id,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)

    # Ambient auth: pick an active tenant that has usable credentials.
    tenants = _load("tenants.json")
    candidates = []
    for t in tenants:
        if not isinstance(t, dict):
            continue
        if t.get("status") != "active":
            continue
        at = t.get("auth_type")
        if at == "api_key" and t.get("api_key_ciphertext"):
            candidates.append(t)
        elif at == "oauth" and t.get("oauth_access_token_ciphertext") and t.get("oauth_refresh_token_ciphertext") and t.get("oauth_token_expires_at"):
            candidates.append(t)

    if tenant_id is not None:
        if not isinstance(tenant_id, str) or not re.fullmatch(r"^fdten_[0-9A-Z]{10,}$", tenant_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tenant_id override is invalid")
        candidates = [t for t in candidates if t.get("id") == tenant_id]

    if not candidates:
        _log("error", t_id=tenant_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active tenant context available for the caller")

    # Deterministic selection: most recently updated
    def _ts(x):
        v = x.get("updated_at") or x.get("created_at") or ""
        return v
    candidates.sort(key=_ts, reverse=True)
    t = candidates[0]

    # Rate limit consumption: count requests in last 60s for this tenant
    logs = _load("request_logs.json")
    cutoff = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)).isoformat()
    used_last_min = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") != t.get("id"):
            continue
        ts = r.get("timestamp")
        if isinstance(ts, str) and ts >= cutoff:
            used_last_min += 1

    rl = t.get("rate_limit_per_minute") if isinstance(t.get("rate_limit_per_minute"), int) else None
    remaining = None
    if isinstance(rl, int):
        remaining = max(0, rl - used_last_min)

    me = {
        "tenant_id": t.get("id"),
        "tenant_status": t.get("status"),
        "scopes": ["read", "write"],  # integration server scope model placeholder
        "rate_limit": {
            "limit_per_minute": rl,
            "used_last_minute": used_last_min,
            "remaining": remaining
        }
    }

    _log("ok", t_id=t.get("id"))
    return {"me": me}

def update_ticket_status(tenant_id, id, status, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0259000" if __import__("os").path.isdir("./environment_mix/0259000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    def _log(status_s, t_id=None, error_code=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": "fdreq_" + secrets.token_hex(10).upper(),
            "endpoint": "update_ticket_status",
            "tenant_id": t_id,
            "credential_id": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(tenant_id, str) or not re.fullmatch(r"^fdten_[0-9A-Z]{10,}$", tenant_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tenant_id is invalid")
    if not isinstance(id, str) or not re.fullmatch(r"^fdtkt_[0-9A-Z]{10,}$", id):
        _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id is invalid")
    if status not in ("open", "pending", "resolved", "closed", "deleted"):
        _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: open, pending, resolved, closed, deleted")

    # Resolve tenant and enforce per-tenant rate limit
    tenants = _load("tenants.json")
    tenant = None
    for t in tenants:
        if isinstance(t, dict) and t.get("id") == tenant_id:
            tenant = t
            break
    if tenant is None or tenant.get("status") != "active":
        _log("error", t_id=tenant_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tenant is not active or not found")

    rl = tenant.get("rate_limit_per_minute")
    if isinstance(rl, int):
        logs = _load("request_logs.json")
        cutoff = (now_dt - datetime.timedelta(seconds=60)).isoformat()
        used = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tenant_id") != tenant_id:
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str) and ts >= cutoff:
                used += 1
        if used >= rl:
            _log("error", t_id=tenant_id, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Per-tenant rate limit exceeded", limit_per_minute=rl, used_last_minute=used)

    tickets = _load("tickets.json")
    idx = None
    for i, tk in enumerate(tickets):
        if isinstance(tk, dict) and tk.get("id") == id and tk.get("tenant_id") == tenant_id:
            idx = i
            break
    if idx is None:
        _log("error", t_id=tenant_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Ticket not found", tenant_id=tenant_id, id=id)

    ticket = tickets[idx]

    current = ticket.get("status")
    transitions = {
        "open": ["pending", "resolved", "closed", "deleted"],
        "pending": ["open", "resolved", "closed", "deleted"],
        "resolved": ["open", "closed", "deleted"],
        "closed": ["open", "deleted"],
        "deleted": []
    }
    if current not in transitions:
        _log("error", t_id=tenant_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Ticket has invalid current status", current_status=current)

    if status != current and status not in transitions[current]:
        _log("error", t_id=tenant_id, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Illegal ticket status transition from {current} to {status}", from_status=current, to_status=status)

    # Must exist upstream to update upstream status
    if ticket.get("freshdesk_id") is None:
        _log("error", t_id=tenant_id, error_code="FAILED_PRECONDITION")
        return _err("FAILED_PRECONDITION", "Cannot update upstream ticket when freshdesk_id is null", id=id)

    # Apply update locally; "refresh raw/last_synced_at" best-effort offline by annotating raw
    raw = ticket.get("raw") if isinstance(ticket.get("raw"), dict) else {}
    raw = dict(raw)
    raw["_integration"] = dict(raw.get("_integration") or {})
    raw["_integration"]["last_status_update"] = {
        "from": current,
        "to": status,
        "at": now
    }

    ticket["status"] = status
    ticket["raw"] = raw
    ticket["last_synced_at"] = now
    ticket["updated_at"] = now

    # Maintain denormalized search_text (simple approach)
    subj = ticket.get("subject") or ""
    desc = ticket.get("description_text") or ""
    tags = ticket.get("tags") if isinstance(ticket.get("tags"), list) else []
    ticket["search_text"] = " ".join([str(subj), str(desc), " ".join([str(x) for x in tags if x is not None])]).strip() or ticket.get("search_text")

    tickets[idx] = ticket
    _save("tickets.json", tickets)

    _log("ok", t_id=tenant_id)
    return {"ticket": ticket}
